          "patientRegistry": false,
          "designInfo": {
            "observationalModel": "COHORT",
            "timePerspective": "PROSPECTIVE"
          },
          "bioSpec": {
            "retention": "SAMPLES_WITHOUT_DNA",
            "description": "The following types of biospecimens will be retained for ancillary analyses:\n\n* Exhaled breath condensate\n* Blood samples\n\nThese specimens will be collected at baseline and at the end of the intervention phase, then stored for subsequent analysis in the context of the Bio-ILYAD study (biobank)."
          },
          "enrollmentInfo": {
            "count": 4312,
            "type": "ESTIMATED"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Mobile Screening Group",
              "description": "Participants receiving lung cancer screening via a mobile unit (truck) operated by trained nurses. This includes spirometry, blood pressure measurement, blood cholesterol testing, low-dose CT scan, and optional biospecimen collection.",
              "interventionNames": [
                "Diagnostic Test: Low-dose Chest CT Screening",
                "Diagnostic Test: Spirometry",
                "Diagnostic Test: Cardiovascular Risk Assessment",
                "Behavioral: Smoking Cessation Support",
                "Other: Optional Biospecimen Collection (Bio-ILYAD)"
              ]
            },
            {
              "label": "Non-Mobile Screening Group",
              "description": "Participants receiving the same screening procedures at a fixed hospital-based site (Lyon Sud), with possible involvement of medical or non-medical staff depending on availability.",
              "interventionNames": [
                "Diagnostic Test: Low-dose Chest CT Screening",
                "Diagnostic Test: Spirometry",
                "Diagnostic Test: Cardiovascular Risk Assessment",
                "Behavioral: Smoking Cessation Support",
                "Other: Optional Biospecimen Collection (Bio-ILYAD)"
              ]
            }
          ],
          "interventions": [
            {
              "type": "DIAGNOSTIC_TEST",
              "name": "Low-dose Chest CT Screening",
              "description": "Participants undergo a low-dose chest CT scan to screen for early lung cancer and assess associated conditions (emphysema, coronary calcifications, osteoporosis).",
              "armGroupLabels": [
                "Mobile Screening Group",
                "Non-Mobile Screening Group"
              ]
            },
            {
              "type": "DIAGNOSTIC_TEST",
              "name": "Spirometry",
              "description": "Assessment of lung function through spirometry, with optional plethysmography and diffusion testing to detect COPD and PRISM patterns.",
              "armGroupLabels": [
                "Mobile Screening Group",
                "Non-Mobile Screening Group"
              ]
            },
            {
              "type": "DIAGNOSTIC_TEST",
              "name": "Cardiovascular Risk Assessment",
              "description": "Cardiovascular risk is evaluated using SCORE2/SCORE2-OP tools, based on blood pressure and cholesterol levels.",
              "armGroupLabels": [
                "Mobile Screening Group",
                "Non-Mobile Screening Group"
              ]
            },
            {
              "type": "BEHAVIORAL",
              "name": "Smoking Cessation Support",
              "description": "Active smokers receive a structured smoking cessation intervention, including a baseline consultation and up to two follow-up sessions (which may be remote).",
              "armGroupLabels": [
                "Mobile Screening Group",
                "Non-Mobile Screening Group"
              ]
            },
            {
              "type": "OTHER",
              "name": "Optional Biospecimen Collection (Bio-ILYAD)",
              "description": "Optional collection of blood and exhaled breath condensate for future analysis of biomarkers in lung cancer detection.",
              "armGroupLabels": [
                "Mobile Screening Group",
                "Non-Mobile Screening Group"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Proportion of socially deprived participants included in the mobile screening group",
              "description": "The percentage of participants with an EPICES score ≥ 4 (indicating social vulnerability) in the mobile screening arm, compared to the non-mobile arm.",
              "timeFrame": "Baseline (Day 0)"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Participation by socio-demographic profile",
              "description": "Comparison of participants' characteristics between the two modalities (smoking status, age, sex, socio-professional category, income level, education, perceived ethnic identity, geographic isolation, presence of a general practitioner).",
              "timeFrame": "Inclusion"
            },
            {
              "measure": "Mobile feasibility",
              "description": "Feasibility of the mobile screening pathway, assessed by the attendance rate (proportion of invited participants who attend the mobile unit) and the completion rate (proportion of those attendees who complete the full screening process). Both will be reported separately as percentages.\n\nUnit of Measure: Percentage of participants (%)",
              "timeFrame": "Throughout inclusion period"
            },
            {
              "measure": "Feasibility of task-shifting to nurses",
              "description": "Rate of recourse to a physician and participant satisfaction in each modality.",
              "timeFrame": "Throughout inclusion period"
            },
            {
