          "briefTitle": "Formatting the Risk Prediction Models for Never-Smoking Lung Cancer",
          "officialTitle": "Validation and Optimization of Multidimensional Modelling for Never Smoking Lung Cancer Risk Prediction by Multicenter Prospective Study",
          "acronym": "FORMOSA"
        },
        "statusModule": {
          "statusVerifiedDate": "2026-02",
          "overallStatus": "RECRUITING",
          "expandedAccessInfo": {
            "hasExpandedAccess": false
          },
          "startDateStruct": {
