        },
        "sponsorCollaboratorsModule": {
          "responsibleParty": {
            "type": "PRINCIPAL_INVESTIGATOR",
            "investigatorFullName": "Gee-Chen Chang",
            "investigatorTitle": "Vice president of Chung Shan Medical University",
            "investigatorAffiliation": "Chung Shan Medical University"
          },
          "leadSponsor": {
            "name": "Chung Shan Medical University",
            "class": "OTHER"
          },
          "collaborators": [
            {
              "name": "Ministry of Health and Welfare, Taiwan",
