        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Monotherapy Dose-Escalation Cohorts",
              "type": "EXPERIMENTAL",
              "description": "Prior to the current amendment, no DLTs were observed at Dose Levels 1-5. Starting with the current protocol amendment, dosing decisions in monotherapy cohorts will utilize a 3+3 design for Dose Level 6. CRX100 infusion will occur every nine weeks (+/- 7 days). Subjects will receive up to a maximum of four infusions of CRX100 unless it is determined by the treating physician and the sponsor that it is in the best interest of the subjects to receive additional doses of CRX100 beyond four doses. A minimum of three DLT-evaluable subjects will be doses at Dose Level 6 and expanded to six subjects if determined necessary based on DLT incidence using the 3+3 design, and discussion with SRC and Sponsor.",
              "interventionNames": [
                "Biological: CRX100 suspension for infusion",
                "Combination Product: Fludarabine",
                "Combination Product: Cyclophosphamide"
              ]
            },
            {
              "label": "Combination Therapy Cohorts",
              "type": "EXPERIMENTAL",
              "description": "Subjects with relasped or refractory solid tumors, as defined in the inclusion criteria, will be enrolled to evaluate the safety and anti-tumor activity of CRX100 in combination with Pembrolizumab in patients with advanced solid malignancies. The dose of CRX100 used will be determined from the monotherapy cohorts.\n\nCRX100 infusion will occur every nine weeks (+/- 7 days). Subjects will receive up to a maximum of four doses of CRX100 unless it is determined by the treating physician and the sponsor that it is in the best interest of the subjects to receive additional doses of CRX100 beyond four doses.\n\nPembrolizumab will be administered at 200mg IV every three weeks (Q3W) per the approved label.",
              "interventionNames": [
                "Biological: CRX100 suspension for infusion",
                "Combination Product: Fludarabine",
                "Combination Product: Cyclophosphamide"
              ]
            }
          ],
          "interventions": [
            {
              "type": "BIOLOGICAL",
              "name": "CRX100 suspension for infusion",
              "description": "A fixed dose of CIK cells combined with the specified dose of CDSR.",
              "armGroupLabels": [
                "Combination Therapy Cohorts",
                "Monotherapy Dose-Escalation Cohorts"
              ]
            },
            {
              "type": "COMBINATION_PRODUCT",
              "name": "Fludarabine",
              "description": "25mg/m IV (five doses given from Day -7 until Day -3)",
              "armGroupLabels": [
                "Combination Therapy Cohorts",
                "Monotherapy Dose-Escalation Cohorts"
              ]
            },
            {
              "type": "COMBINATION_PRODUCT",
              "name": "Cyclophosphamide",
              "description": "60mg/kg intravenous (IV) (two doses given on Day -7 and -6)",
              "armGroupLabels": [
                "Combination Therapy Cohorts",
                "Monotherapy Dose-Escalation Cohorts"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Frequency of treatment-emergent Adverse Events and Dose Limiting Toxicities",
              "description": "The Primary Outcome Measure will be based on the frequency of treatment-emergent Adverse Events and Dose Limiting Toxicities during and after the administration of investigational drug in monotherapy and investigational drug with combination therapy.",
              "timeFrame": "28 days following dose administration for each dosed subject."
            },
            {
              "measure": "Determine the maximum tolerated dose (MTD), maximum feasible dose (MFD) or optimal biological dose (OBD) and determine recommended Phase 1b/Phase 2a dose level.",
              "description": "Review of safety review committee following subject treatment to review any AEs, SAEs, or DLTs",
              "timeFrame": "28 days following dose administration for each dosed subject."
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Biodistribution of CRX100 based on subject's viral load as assessed through a viral shedding assay.",
              "description": "To characterize the biodistribution of CRX100 based on each subject's viral load as assessed through a viral shedding assay, following a single dose of investigational product.",
              "timeFrame": "28 days following dose administration for each dosed subject."
            },
            {
              "measure": "Immune response to investigational drug based on subject's levels of neutralizing antibodies.",
              "description": "Levels of neutralizing vvDD antibodies will be summarized by dose level and time point following a single dose of investigational product.",
              "timeFrame": "28 days following dose administration for each dosed subject."
            },
            {
              "measure": "Early anti-tumor activity of investigational drug based on iRECIST criteria",
              "description": "Summarized based on best response observed using RECIST classification of response. Overall response and frequencies of each level of response.",
              "timeFrame": "6 months after dose administration for each dosed subject."
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\nSubjects must meet all the following criteria to be enrolled in this study:\n\n1. Age ≥18 years at the time of consent.\n2. Written informed consent in accordance with national, local, and institutional guidelines obtained prior to any study procedures. (Screening assessments performed prior to informed consent but within the 28-day screening window are acceptable for inclusion purposes).\n3. Subjects must have histologically confirmed diagnosis of one of the following tumors: triple negative adenocarcinoma of the breast (human epidermal growth factor receptor 2 negative, estrogen receptor negative and progesterone receptor negative \\[HER2-/ER-/PR-\\]), adenocarcinoma of the colon or rectum, hepatocellular carcinoma (HCC), osteosarcoma, epithelial ovarian cancer, malignant melanoma, non-small cell lung cancer (NSCLC), or gastric cancer. Documentation of the diagnosis with the original pathology report, or a recent biopsy, is required.\n4. Subjects must have relapsed disease or refractory disease. Subjects must have received, completed, or become intolerant of prior standard of care therapies or are not expected to derive any clinical benefit from standard of care therapies.\n5. Subjects with Ovarian cancer must have received at least one prior standard of care for their relapsed or refractory disease, which must include a platinum-based regimen.\n6. Subjects agree to provide fresh tumor tissue that has not been previously irradiated. If biopsy procedure is not safe to perform, then archival tumor tissue (20 slides or a tissue block) can be submitted.\n7. Subjects must have iRECIST evaluable disease using computed tomography (CT) or magnetic resonance imaging (MRI) with IV contrast, with at least one measurable target lesion.\n8. Subjects must have an Eastern Cooperative Oncology Group (ECOG) performance status of 0-1.\n9. Subjects are expected to have a life expectancy of at least 12 weeks from the time of enrollment.\n10. Adequate hematologic function at the time of screening, defined as: absolute lymphocyte count (ALC) \\>500 cells/mm3, absolute neutrophil count (ANC) \\>750 cells/mm3, hemoglobin \\>8 g/dL, and platelet count \\>50,000 cells/mm3. For subjects enrolling into the LDC cohorts, the criteria are defined as: ALC\\>500 cells/mm3, ANC\\>1000 cells/mm3, hemoglobin\\>8g/dL, and platelet count\\>100,000 cells/mm3.\n\n    a. Hemoglobin and platelet count thresholds must be achievable without transfusion of red blood cells or platelets, or use of growth factors administered within two weeks.\n11. Adequate organ function, defined as:\n\n    1. Renal function: serum creatinine \\<1.5x institutional upper limit of normal (ULN) or calculated creatinine clearance \\>50 mL/min.\n    2. Adequate hepatic function: total bilirubin ≤1.5x institutional ULN; aspartate aminotransferase (AST) and alanine aminotransferase (ALT) ≤2.5x institutional ULN, unless liver metastases are present, in which case it must be ≤5x ULN; International Normalized Ratio (INR) ≤1.5. For subjects with HCC, adequate hepatic function is defined as: total bilirubin ≤3x institutional upper limit of normal, AST/ALT ≤5x institutional ULN, INR ≤1.7, Child-Turcotte-Pugh score \\<8.\n12. Women of childbearing potential (defined as all subjects physiologically capable of becoming pregnant) must have negative serum ß-human chorionic gonadotropin (hCG) or urine pregnancy test.\n13. Women of childbearing potential must agree to use highly effective methods of contraception throughout the study and for six months after the last dose of CRX100.\n14. Males who have partners of childbearing potential must agree to use an effective barrier contraceptive method throughout the study and for six months after the last dose of CRX100.\n15. Subjects must be willing and able to comply with all study procedures, requirements, and follow-up examinations.\n\nExclusion Criteria:\n\nSubjects who meet any of the following criteria will be excluded from participation in this study:\n\n1. Subjects with new or progressive brain metastasis. Subjects with treated brain metastases are eligible if there is no evidence of progression for at least four weeks after central nervous system-directed treatment, as ascertained by clinical examination and brain imaging (MRI or CT) during the screening period.\n2. Subjects who received any chemotherapy or immunotherapies (non-cell-based therapies) or oncolytic virus therapy, radiotherapy, radiosurgery or investigational agents within three weeks of enrollment.\n3. Subjects who still are experiencing Grade 2 or higher AEs from prior therapies such as surgery, radiation therapy and systemic anti-cancer therapies unless approved by sponsor.\n4. Subjects who received any type of cell-based therapies within the last 12 weeks from the planned apheresis date.\n5. Subjects experiencing any active infections (bacterial, viral, or fungal) for which systemic antimicrobials are required. Subjects who need prophylactic anti-viral agents that can inhibit the replication of VACV will be excluded from participating.\n6. Subjects must not have history of active or symptomatic autoimmune disease or evidence of symptomatic autoimmune pneumonitis, glomerulonephritis, vasculitis, other symptomatic autoimmune disease, documented history of autoimmune disease or syndrome requiring systemic treatment in the past two years (i.e., with use of disease modifying agents, steroids or immunosuppressive agents) Exceptions are permitted for vitiligo, type I diabetes mellitus, residual hypothyroidism due to autoimmune condition requiring only hormone replacement, psoriasis not requiring systemic treatment, conditions not expected to recur in the absence of an external trigger or other conditions approved by the medical monitor.\n7. Have a condition requiring systemic treatment with either corticosteroids (\\>10 mg daily prednisone or equivalent) or other immunosuppressive medications within 14 days prior to apheresis, and within 14 days prior to infusion. Inhaled, intramuscular injection, or topical steroids and adrenal replacement doses (≤10 mg daily prednisone equivalents) are permitted. Stable doses of steroids are permitted for subjects with pre-treated brain metastases. Short-term (\\<48 hr) steroid pretreatment for contrast allergy for imaging is permitted.\n8. Known human immunodeficiency virus (HIV) infection, active chronic hepatitis B or C, life-threatening illnesses unrelated to cancer, or any serious medical or psychiatric illness that could, in the Investigator's opinion, interfere with participation in this study.\n9. Pregnant or nursing an infant (subject or household contacts).\n10. Clinically significant immunodeficiency (e.g., due to underlying illness and/or medication) in a subject or household contacts.\n11. Have any underlying medical condition (including, but not limited to, ongoing or active infection requiring treatment, symptomatic congestive heart failure, unstable angina pectoris, or cardiac arrhythmia), psychiatric condition that, in the opinion of the Investigator, would compromise study administration as per protocol or compromise the assessment of AEs.\n12. Have a history of another invasive malignancy, except for the following circumstance: individuals with a history of invasive malignancy are eligible if they have been disease free and off treatment for at least two years or are deemed by the Investigator to be at low risk for recurrence of that malignancy; individuals with the following cancers are eligible if diagnosed and treated: carcinoma in situ of the breast, oral cavity, or cervix, localized prostate cancer, or basal cell or squamous cell carcinoma of the skin. When enrolling a subject with another malignancy, the Investigator must discuss the subject with the Medical Monitor.",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ]
        },
