        "oversightModule": {
          "oversightHasDmc": true,
          "isFdaRegulatedDrug": false,
          "isFdaRegulatedDevice": false
        },
        "descriptionModule": {
          "briefSummary": "Lung cancer is currently the world's largest malignant tumor for cancer-related deaths with non-small cell lung cancer (NSCLC) accounting for 80%-85%. Epidermal growth factor receptor tyrosine kinase inhibitors (EGFR-TKIs), especially the 3rd-generation EGFR-TKIs have demonstrated strong antitumor effects in EGFR-positive patients.\n\nHowever, approximately 20% of EGFR-positive were primarily resistant to 3rd generation EGFR-TKIs, i.e., clinical non-response or disease progression in the short term.\n\nThis study aimed to clarify the molecular indicators that predict the benefits of 3-rd EGFR-TKIs as first-line therapy in NSCLCpatients with EGFR-positive. Further, to clarify their primary drug resistance mechanisms, which is of great significance for the treatment and clinical decision-making of NSCLC disease."
        },
        "conditionsModule": {
          "conditions": [
            "Lung Cancer, Non-small Cell",
            "EGFR Gene Mutation",
            "EGFR-TKI Resistant Mutation",
            "Primary Resistance",
            "Circulating Tumor DNA"
          ]
        },
        "designModule": {
          "studyType": "OBSERVATIONAL",
          "patientRegistry": true,
          "targetDuration": "5 Years",
          "designInfo": {
            "observationalModel": "COHORT",
            "timePerspective": "PROSPECTIVE"
          },
          "bioSpec": {
            "retention": "SAMPLES_WITH_DNA",
            "description": "1. The paraffin embeds tumor tissue at diognosis\n2. Peripheral venous blood"
          },
          "enrollmentInfo": {
            "count": 210,
            "type": "ESTIMATED"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "EGFR-positive lung patients recieving 3rd generation EGFR-TKIs as first-line therapy",
              "description": "Stage III-IV EGFR-positive lung patients receiving 3rd generation EGFR-TKIs (Osimertinib 80mg/Qd or Almonertinib 110mg/Qd or Furmonertinib 80mg/Qd) as first-line therapy.",
              "interventionNames": [
                "Other: Genomic profiles detection",
                "Other: circulating tumor DNA detection"
              ]
            }
          ],
          "interventions": [
            {
              "type": "OTHER",
              "name": "Genomic profiles detection",
              "description": "The Paraffin-embedded tumor tissue at diagnosis is collected and assessed by Next- generation gene sequencing",
              "armGroupLabels": [
                "EGFR-positive lung patients recieving 3rd generation EGFR-TKIs as first-line therapy"
              ]
            },
            {
              "type": "OTHER",
              "name": "circulating tumor DNA detection",
              "description": "The Plasma at diagnosis and at 1-month treatment are collected and assessed by Next-generation gene sequencing",
              "armGroupLabels": [
                "EGFR-positive lung patients recieving 3rd generation EGFR-TKIs as first-line therapy"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Objective Response Rate (ORR)",
              "description": "The proportion of patients with a complete response or partial response to treatment according to Response Evaluation Criteria in Solid Tumors (RECIST v1.1)",
              "timeFrame": "2 years"
            },
            {
              "measure": "Progression-free survival (PFS)",
              "description": "Time from the beginning of treatment to the first disease progression (PD) in patients with advanced NSCLC",
              "timeFrame": "3 years"
            },
            {
              "measure": "Differences in genomic profiles of tumor tissues and ctDNA clearance of third-generation EGFR-TKIs sensitive and primary drug-resistant NSCLC.",
              "description": "The patients who don't achieve partial response or progress within 6 months are defined as the primary resistant group. The genomic profiles and ctDNA clearance detected by Next-generation gene sequencing will be compared between the primary drug-resistant group and sensitive-drug group.",
              "timeFrame": "3 years"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Overall survival (OS)",
              "description": "Overall survival (OS) is defined as the duration from the beginning of first-line immunotherapy until death due to any cause. Subjects who are still alive at the end of the study observation period will be censored at the time of last known vital status",
              "timeFrame": "5 years"
            },
            {
              "measure": "Disease Control Rate (DCR)",
              "description": "The proportion of patients with a complete response or partial response or stable desease to treatment according to Response Evaluation Criteria in Solid Tumors (RECIST v1.1)",
              "timeFrame": "3 years"
            }
          ],
          "otherOutcomes": [
            {
              "measure": "The correlation between tumor microenvironment signature and efficacy of 3rd EGFR-TKIs",
              "description": "The baseline paraffin-embedded tissue is collected and assessed by multiplex immunohistochemistry, including T lymphocytes, B lymphocytes, NK lymphocytes, macrophagocyte, and DC cells. And explore the association between tumor microenvironment signature and primary resistance and the efficacy of 3rd EGFR-TKIs during the enrolled observation process.",
              "timeFrame": "3 years"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n1. Age \\>18 years;\n2. Histological or cytopathological diagnosed NSCLC;\n3. According to the American Joint Committee on Cancer (AJCC) eighth edition of the Lung Cancer Staging Manual, the clinical stage is unresectable IIIB-IV or recurrence and metastasis after surgery;\n4. At least one measurable lesion can be evaluated according to the Response Evaluation Criteria In Solid Tumours v1.1 (RECIST1.1) criteria;\n5. Positive EGFR mutation confirmed by tissue or cytology (pleural fluid, cerebrospinal fluid, etc.);\n6. Use of third-generation EGFR-TKIs approved by the NMPA for NSCLC as first-line therapy;\n7. Cooperate with the provision of clinicopathological data, imaging data, sample collection, and follow-up required for the research process, and agree to use the test data for subsequent research and product development;\n8. Agree to participate in this study and sign an informed consent form.\n\nExclusion Criteria:\n\n1. Patients who cannot understand the content of the experiment and cannot cooperate, and those who refuse to sign the informed consent form;\n2. Pregnant and lactating women;\n3. Other malignant neoplastic diseases within 3 years;\n4. Patients who have undergone other clinical drug trials;\n5. Received systemic anti-tumor therapy within 2 years;",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ],
          "studyPopulation": "Stage IIIB-IV EGFR-positive lung patients receiving 3rd generation EGFR-TKIs (Osimertinib 80mg/Qd or Almonertinib 110mg/Qd or Furmonertinib 80mg/Qd) as first-line therapy.",
          "samplingMethod": "NON_PROBABILITY_SAMPLE"
        },
