        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Adverse events/serious adverse events",
              "description": "to record and analyse the occasions and rates of subjects with adverse events (AEs) and serious adverse events (SAEs) to understand drug safety profile",
              "timeFrame": "From screening through completion of the study, an average of 3.5 years."
            },
            {
              "measure": "Maximum Tolerated Dose (MTD)",
              "description": "MTD is defined as the dose level with dose-limiting toxicity (DLT) rate of greater than 0.322 as calculated using the BOIN design at dose escalation phase.",
              "timeFrame": "From Day 1 of Cycle 1 to Day 28 of Cycle 1 of dose escalation phase (each cycle is 28 days)"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Preliminary efficacy",
              "description": "For patients with advanced solid tumors, efficacy is evaluated based on RECIST 1.1 criteria which evaluates tumor size changes. Preliminary efficacy is evaluated by Principal investigator.",
              "timeFrame": "From screening, every 3 cycles during treatment period (each cycle is 28 days) and at end of study, an average of 3.5 years."
            },
            {
              "measure": "Time to Maximum Concentration (Tmax)",
              "description": "To measure the time to reach maximum plasma drug concentration from dosing",
              "timeFrame": "On day 1-6 of the single dosing phase; patient will only be dosed once on Day 1 of this phase"
            },
            {
              "measure": "Maximum Concentration (Cmax)",
              "description": "To measure the maximum plasma drug concentration from dosing",
              "timeFrame": "On day 1-6 of the single dosing phase; patient will only be dosed once on Day 1 of this phase"
            },
            {
              "measure": "Area Under Curve (AUC0-t)",
              "description": "To calculate area under curve of drug plasma concentration from dosing to last measurable time point",
              "timeFrame": "On day 1-6 of the single dosing phase; patient will only be dosed once on Day 1 of this phase"
            },
            {
              "measure": "Half life (T1/2)",
              "description": "to measure the time needed to reach half maximal concentration from dosing",
              "timeFrame": "On day 1-6 of the single dosing phase; patient will only be dosed once on Day 1 of this phase"
            },
            {
