        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Changes in lung injury grading on chest computerized tomography within 3 months after radiotherapy",
              "description": "Kouloulias scale was used to evaluate the changes of lung injury grading in chest computerized tomography within 3 months after radiotherapy. The higher the grading is, the more serious the lung injury is",
              "timeFrame": "4 weeks and 12 weeks after radiotherapy"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Relationship between biomarkers and radioactive damage",
              "description": "The changes of the above cytokines in the blood of patients were monitored before and after radiotherapy, and the correlation between the changes of cytokines and the grade of radiation damage was analyzed",
              "timeFrame": "1 week before medication，4 weeks and 12 weeks after radiotherapy"
            },
            {
              "measure": "Relationship between biomarkers and therapy",
              "description": "The changes of the above cytokines in the blood of patients were monitored before and after radiotherapy, and the correlation between the changes of cytokines and treatment was analyzed",
              "timeFrame": "1 week before medication，4 weeks and 12 weeks after radiotherapy"
            },
            {
              "measure": "security",
              "description": "use the CTCAE5.0 scale to record adverse events to assess safety",
              "timeFrame": "Every week of the medication，4 weeks and 12 weeks after radiotherapy"
            }
