        "descriptionModule": {
          "briefSummary": "The purpose of this study is to assess the anti-tumor activity and safety of amivantamab which will be administered as a co-formulation with recombinant human hyaluronidase PH20 (rHuPH20) (subcutaneous co-formulation \\[SC-CF\\]) in combination treatment (all cohorts except Cohort 4) and to characterize the safety of amivantamab SC-CF (Cohort 4)."
        },
        "conditionsModule": {
          "conditions": [
            "Carcinoma, Non-small-Cell Lung"
          ]
        },
        "designModule": {
          "studyType": "INTERVENTIONAL",
          "phases": [
            "PHASE2"
          ],
          "designInfo": {
            "allocation": "NON_RANDOMIZED",
            "interventionModel": "PARALLEL",
            "primaryPurpose": "TREATMENT",
