            }
          },
          "enrollmentInfo": {
            "count": 520,
            "type": "ESTIMATED"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Cohort 1(Exon19del/Exon21 L858R NSCLC, 1L, Previously Untreated): Amivantamab (Q2W) + Lazertinib",
              "type": "EXPERIMENTAL",
              "description": "Participants with treatment-naive locally advanced or metastatic non-small cell lung cancer (NSCLC) harboring an epidermal growth factor receptor (EGFR) exon 19 deletion (exon19del) or exon 21 leucine 858 to arginine substitution (exon 21 L858R) mutation, will receive amivantamab SC-CF injection, 1600 milligrams (mg) or 2240 mg if body weight is greater than or equal to (\\>=) 80 kilograms (kg), on Cycle 1 Days 1, 8, 15, and 22 and on Days 1 and 15 of each subsequent 28-day cycle, starting with Cycle 2, along with lazertinib 240 mg orally once daily. Eligible participants will be given an option to enter long-term extension (LTE) phase and may continue to receive access to study treatment(s) within the study by transferring to the Drug Access (DA)-LTE Phase.",
              "interventionNames": [
                "Drug: Amivantamab",
                "Drug: Lazertinib"
              ]
            },
            {
              "label": "Cohort 2(Exon20 NSCLC,1L, Previously Untreated): Amivantamab (Q3W) + Chemotherapy",
              "type": "EXPERIMENTAL",
              "description": "Participants with treatment-naive locally advanced or metastatic NSCLC harboring an EGFR exon20ins mutation will receive Amivantamab SC-CF injection 1600 mg or 2240 mg if body weight is \\>=80 kg on Cycle 1 Day 1, 2400 mg or 3360 mg if body weight is \\>=80 kg on Cycle 1 Day 8 and 15 and on Day 1 of each subsequent 21-day cycle, starting with Cycle 2 along with pemetrexed 500 milligrams per meter square (mg/m\\^2) as intravenous (IV) infusion (with vitamin supplementation) on Day 1 of each 21-day cycle and IV infusion carboplatin area under the concentration-time curve 5 milligrams per milliliters (mg/mL) per minute (AUC 5) maximum 750 mg on Day 1 of each 21-day cycle, for up to 4 cycles. Eligible participants will be given an option to enter LTE phase and may continue to receive access to study treatment(s) within the study by transferring to the DA-LTE Phase.",
              "interventionNames": [
                "Drug: Amivantamab",
                "Drug: Carboplatin",
                "Drug: Pemetrexed"
              ]
            },
            {
              "label": "Cohort 3(Exon19del/Exon21 L858R NSCLC,2L,Post Osimertinib):Amivantamab(Q3W)+Lazertinib+Chemotherapy",
              "type": "EXPERIMENTAL",
              "description": "Participants with locally advanced or metastatic NSCLC harboring an EGFR exon19del or exon 21 L858R mutation who have experienced disease progression on or after treatment with a third-generation EGFR TKI (osimertinib), will receive amivantamab SC-CF injection 1600 mg or 2240 mg if body weight is \\>=80 kg on Cycle 1 Day 1, 2400 mg or 3360 mg if body weight is \\>=80 kg on Cycle 1 Day 8 and 15 and on Day 1 of each subsequent 21-day cycle starting with Cycle 2; in combination with IV infusion carboplatin area under the concentration-time curve 5 mg/mL per minute (AUC 5) maximum 750 mg on Day 1 of each 21-day cycle, for up to 4 cycles; and pemetrexed 500 mg/m\\^2 as an IV infusion (with vitamin supplementation) on Day 1 of each 21-day until disease progression. Lazertinib 240 mg orally once daily starting Cycle 5 Day 1 when carboplatin is complete or sooner if carboplatin discontinued earlier than Cycle 4. Eligible participants will be given an option to enter LTE phase and DA-LTE Phase.",
              "interventionNames": [
                "Drug: Amivantamab",
                "Drug: Lazertinib",
                "Drug: Carboplatin",
                "Drug: Pemetrexed"
              ]
            },
            {
              "label": "Cohort 3b(Exon19del/Exon21 L858R NSCLC, 2L, Post Osimertinib): Amivantamab (Q3W)+Chemotherapy",
              "type": "EXPERIMENTAL",
              "description": "Participants with locally advanced or metastatic NSCLC harboring an EGFR exon19del or exon 21 L858R mutation who have experienced disease progression on or after treatment with a third-generation EGFR TKI (osimertinib), will receive amivantamab SC-CF injection 1600 mg or 2240 mg if body weight is \\>=80 kg on Cycle 1 Day 1, 2400 mg or 3360 mg if body weight is \\>=80 kg on Cycle 1 Day 8 and 15 and on Day 1 of each subsequent 21-day cycle starting with Cycle 2; in combination with IV infusion carboplatin area under the concentration-time curve 5 mg/mL per minute (AUC 5) maximum 750 mg on Day 1 of each 21-day cycle, for up to 4 cycles; and pemetrexed 500 mg/m\\^2 as an IV infusion (with vitamin supplementation) on Day 1 of each 21-day until disease progression. Eligible participants will be given an option to enter LTE phase and may continue to receive access to study treatment(s) within the study by transferring to the DA-LTE Phase.",
              "interventionNames": [
                "Drug: Amivantamab",
                "Drug: Carboplatin",
                "Drug: Pemetrexed"
              ]
            },
            {
              "label": "Cohort 4(Previously Treated with Amivantamab IV): Switch from Amivantamab IV to SC-CF (Q2W)",
              "type": "EXPERIMENTAL",
              "description": "Participants who were previously on amivantamab IV once every 2 weeks (Q2W) regimen as part of standard of care, for at least 8 weeks, either as monotherapy or combination with lazertinib, will receive amivantamab SC-CF injection 1600 mg and 2240 mg if body weight is greater than or equal to 80 kg. Participants who continue to benefit from study treatments, as determined by their investigator, may shift to the drug access (DA)-LTE phase.",
              "interventionNames": [
                "Drug: Amivantamab",
                "Drug: Lazertinib"
              ]
