          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Integrative Care (Treatment)",
              "type": "EXPERIMENTAL",
              "description": "Participants in the Integrative arm will receive standard surgical and oncologic care at The Ottawa Hospital plus complementary care guided by a naturopathic doctor at The Centre for Health Innovation",
              "interventionNames": [
                "Dietary Supplement: Vitamin D3 Drops",
                "Dietary Supplement: Coriolus Versicolor",
                "Dietary Supplement: Trident SAP 66:33 Lemon",
                "Dietary Supplement: Probiotic Pro12",
                "Dietary Supplement: Provitalix Pure Whey Protein",
                "Dietary Supplement: Theracurmin 2X",
                "Dietary Supplement: Green Tea Extract",
                "Other: Nutrition Recommendations",
                "Other: Physical Activity Recommendations",
                "Behavioral: Psychological Recommendations"
              ]
            },
            {
              "label": "Standard Care (Control)",
              "type": "NO_INTERVENTION",
              "description": "Participants in the control arm will receive standard surgical and oncologic care at The Ottawa Hospital"
            }
          ],
          "interventions": [
            {
              "type": "DIETARY_SUPPLEMENT",
              "name": "Vitamin D3 Drops",
              "description": "1,000 - 10,000 units daily based on serum levels for the duration of the study",
              "armGroupLabels": [
                "Integrative Care (Treatment)"
              ],
              "otherNames": [
                "Vitamin D"
              ]
            },
            {
              "type": "DIETARY_SUPPLEMENT",
              "name": "Coriolus Versicolor",
              "description": "1.5g twice daily for the duration of the study",
              "armGroupLabels": [
                "Integrative Care (Treatment)"
              ]
            },
            {
              "type": "DIETARY_SUPPLEMENT",
              "name": "Trident SAP 66:33 Lemon",
              "description": "3g once daily for the duration of the study",
              "armGroupLabels": [
                "Integrative Care (Treatment)"
              ],
              "otherNames": [
                "Fish Oil"
              ]
            },
            {
              "type": "DIETARY_SUPPLEMENT",
              "name": "Probiotic Pro12",
              "description": "12 billion colony forming units daily during the peri-operative period (approximately 1 month pre and post-surgery)",
              "armGroupLabels": [
                "Integrative Care (Treatment)"
              ],
              "otherNames": [
                "Probiotics"
              ]
            },
            {
              "type": "DIETARY_SUPPLEMENT",
              "name": "Provitalix Pure Whey Protein",
              "description": "1 scoop (22g) once daily during the peri-operative period (approximately 1 month pre and post-surgery) and during any adjuvant chemotherapy and radiation treatments",
              "armGroupLabels": [
                "Integrative Care (Treatment)"
              ],
              "otherNames": [
                "Protein Powder"
              ]
            },
            {
              "type": "DIETARY_SUPPLEMENT",
              "name": "Theracurmin 2X",
              "description": "1.2g twice daily after the peri-operative period. including during adjuvant chemotherapy and radiation",
              "armGroupLabels": [
                "Integrative Care (Treatment)"
              ],
              "otherNames": [
                "Curcumin"
              ]
            },
            {
              "type": "DIETARY_SUPPLEMENT",
              "name": "Green Tea Extract",
              "description": "700 mg twice daily after the peri-operative period. Will not be given during adjuvant radiation or chemotherapy treatments.",
              "armGroupLabels": [
                "Integrative Care (Treatment)"
              ],
              "otherNames": [
                "EGCG"
              ]
            },
            {
              "type": "OTHER",
              "name": "Nutrition Recommendations",
              "description": "Based on the Mediterranean diet and lower glycemic index foods",
              "armGroupLabels": [
                "Integrative Care (Treatment)"
              ]
            },
            {
              "type": "OTHER",
              "name": "Physical Activity Recommendations",
              "description": "150 minutes moderate intensity aerobic exercise per week plus the addition of a resistance exercise program on 2 of those days",
              "armGroupLabels": [
                "Integrative Care (Treatment)"
              ]
            },
            {
              "type": "BEHAVIORAL",
              "name": "Psychological Recommendations",
              "description": "Activities with the intention of actively improving the participant's mental and emotional health",
              "armGroupLabels": [
                "Integrative Care (Treatment)"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Participant Recruitment Rates",
              "description": "Measured by the number of people who are enrolled in the study compared to the total number screened.",
              "timeFrame": "At the end of recruitment (estimated 1 year)"
            },
            {
              "measure": "Participant Retention Rates",
              "description": "Measured by the number of people who enrol in the study but subsequently withdraw. These numbers will be compared between arms.",
              "timeFrame": "2 Years"
            },
            {
              "measure": "Cross-over and contamination in the control arm - Supplement usage",
              "description": "Measured by the number of participants in the control arm who use the integrative interventions outlined in the protocol independent of a naturopathic doctor. Information on the number of supplements used and the length of use use will be collected at each standard of care visit.",
              "timeFrame": "1 Year"
            },
            {
              "measure": "Cross-over and contamination in the control arm - Mediterranean Diet Scores",
              "description": "Measured by the number of participants in the control arm who use the integrative interventions outlined in the protocol independent of a naturopathic doctor. Mediterranean diet scores (scale of 0-9) will be calculated in the control group using the Harvard Food Frequency Questionnaire to assess for changes over the 1 year follow up period.",
              "timeFrame": "1 year"
            },
            {
              "measure": "Cross-over and contamination in the control arm - Physical Activity levels",
              "description": "Changes in physical activity will be monitored using the International Physical Activity Questionnaire, which is used to calculate total metabolic equivalent task (MET) minutes.",
              "timeFrame": "1 Year"
            },
            {
              "measure": "Cross-over and contamination in the control arm - Psychological Health Activities",
              "description": "Measured by the number of participants in the control arm who perform activities in which the goal of the activity was to improve mental and emotional health.",
              "timeFrame": "1 Year"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Communication",
              "description": "Assessing the type and frequency of communications between research staff at The Ottawa Hospital (TOH) and the Centre for Health Innovation (CHI), as well as within TOH and the CHI through number of emails, phone calls, meetings (in-person or virtual) or any other communication method.",
              "timeFrame": "2 years"
            },
            {
              "measure": "Natural Killer Cell Function",
              "description": "Measured by serum Interferon Gamma Levels",
              "timeFrame": "Enrolment, 2-3 days pre-op, and 6 months and 12 months post surgery"
            },
            {
              "measure": "Qualitative Experience",
              "description": "Evaluate the qualitative experience of care of participants in both arms through semi-structured interviews",
              "timeFrame": "2 years"
            },
            {
              "measure": "Inflammatory Response",
              "description": "Measured by serum C-Reactive Protein Levels",
              "timeFrame": "Enrolment, 2-3 days pre-op, and 1 day, 3-4 weeks, 6 months, and 12 months post-surgery"
            },
            {
              "measure": "Neutrophil to Lymphocyte Ratio",
              "description": "Measured by collecting a complete blood count with differential and comparing neutrophil and lymphocyte levels",
              "timeFrame": "Enrolment, 2-3 days pre-op, and 6 months and 12 months post surgery"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion criteria\n\n• Adults eligible for complete resection of lung, gastric or esophageal cancer\n\nExclusion criteria\n\n* Small cell, carcinoid, or gastrointestinal stromal (GIST) tumours\n* Any wedge resections of lung cancer\n* History of cancer with active treatment in the last 3 years (not including superficial bladder cancer or non-melanoma skin cancer)\n* Patients currently receiving care guided by an ND or who have previously seen an ND in the last 3 months\n* Pregnant or breastfeeding women\\*\n* Any reason which, in the opinion of the Principal Investigator (or delegate), would prevent the subject from participating in the study\n* Use of an investigational drug or participation in an investigational study within 30 days prior to starting the study",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ]
        },
