        "oversightModule": {
          "oversightHasDmc": false
        },
        "descriptionModule": {
          "briefSummary": "This study is based on the finding that tumor cells that are grown in the laboratory can be modified in such a way that, when injected to the patient, they will stimulate his/her immune response. This approach will be evaluated in patients with melanoma and colorectal, gastric, ovarian, breast, lung and kidney epithelial cancer. Tumor cells grown in the laboratory will be modified to make them stimulatory to the immune system, irradiated to kill them, and injected to the patient eight times at two-week intervals. This protocol is expected to prolong survival of metastatic cancer patients."
        },
        "conditionsModule": {
          "conditions": [
            "Colorectal Cancer",
            "Ovarian Cancer",
            "Gastric Cancer",
            "Breast Cancer",
            "Lung Cancer",
            "Kidney Cancer",
            "Melanoma"
          ]
        },
        "designModule": {
          "studyType": "INTERVENTIONAL",
          "phases": [
            "PHASE1",
            "PHASE2"
          ],
          "designInfo": {
            "allocation": "NA",
            "interventionModel": "SINGLE_GROUP",
            "primaryPurpose": "PREVENTION",
            "maskingInfo": {
              "masking": "NONE"
            }
          },
          "enrollmentInfo": {
            "count": 50,
            "type": "ESTIMATED"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Autologous or Allogeneic tumor cells",
              "type": "EXPERIMENTAL",
              "description": "Intervention: 5 vaccine doses, 3 weeks apart, injected subcutaneously.",
              "interventionNames": [
                "Biological: Autologous or Allogeneic tumor cells"
              ]
            }
          ],
          "interventions": [
            {
              "type": "BIOLOGICAL",
              "name": "Autologous or Allogeneic tumor cells",
              "description": "Five vaccine doses, injected subcutaneously at 3-week intervals. Each dose is composed of irradiated and DNP-conjugated tumor cells.",
              "armGroupLabels": [
                "Autologous or Allogeneic tumor cells"
              ]
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* One of the following metastatic cancers: Melanoma, breast, ovary, colorectal, gastric, lung or kidney\n* Above 18 years of age\n* Failure of at least one chemotherapy protocol\n* Clinical performance status of ECOG 0,1\n* Absolute neutrophil count greater than 1000/mm3\n* Serum ALT/AST less than three times the upper limit of normal\n* Serum creatinine less than or equal to 1.6 mg/dl.\n* Must be able to understand and sign the Informed Consent document\n\nExclusion Criteria:\n\n* Below 18 years of age\n* Women who are pregnant\n* Life expectancy of less than three months",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ]
        },
