        },
        "descriptionModule": {
          "briefSummary": "The primary objectives are to compare progression-free survival (PFS) and overall survival (OS) in participants who receive sotorasib with platinum doublet chemotherapy versus participants who receive pembrolizumab with platinum doublet chemotherapy."
        },
        "conditionsModule": {
          "conditions": [
