              "type": "EXPERIMENTAL",
              "description": "Sotorasib administered in combination with carboplatin and pemetrexed.",
              "interventionNames": [
                "Drug: Sotorasib"
              ]
            },
            {
              "label": "Pembrolizumab combined with carboplatin and pemetrexed",
              "type": "ACTIVE_COMPARATOR",
