        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Progression-free Survival (PFS)",
              "description": "PFS is defined as the time from randomization until the first documentation of radiologic disease progression or death due to any cause, whichever occurs first. Progression will be based on Response Evaluation Criteria in Solid Tumors (RECIST) v1.1, per Blinded Independent Central Review (BICR).",
              "timeFrame": "Approximately 2.5 years"
            },
            {
              "measure": "Overall Survival (OS)",
              "description": "OS is defined as the time from randomization until death due to any cause.",
              "timeFrame": "Approximately 2.5 years"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Objective Response Rate (ORR)",
              "description": "Objective response is defined as the best overall response of complete response (CR) or partial response (PR), based on RECIST v1.1, per BICR.",
              "timeFrame": "From Baseline up to end of study (EOS) (approximately 5.5 years)"
            },
            {
              "measure": "Change in Quality-of-Life Questionnaire Core 30 (QLQ-C30) Dyspnea Domain Score",
              "timeFrame": "From Baseline to Week 12"
            },
            {
              "measure": "Change in Quality-of-Life Questionnaire Lung Cancer 13 (QLQ-LC13) Symptoms of Dyspnea Subscale",
              "timeFrame": "From Baseline to Week 12"
            },
            {
              "measure": "Change in QLQ-LC13 Symptoms of Cough Subscale",
              "timeFrame": "From Baseline to Week 12"
            },
            {
              "measure": "Change in QLQ-LC13 Symptoms of Chest Pain Subscale",
              "timeFrame": "From Baseline to Week 12"
            },
            {
              "measure": "Change in Physical Function as Measured by QLQ-C30",
              "timeFrame": "From Baseline to Week 12"
            },
            {
              "measure": "Change in Global Health Status as Measured by QLQ-C30",
              "timeFrame": "From Baseline to Week 12"
            },
            {
              "measure": "Progression-free Survival 2 (PFS2)",
              "description": "PFS2 is defined as the time from randomization to progression per investigator after initiation of new anticancer therapy or death from any cause, whichever occurs first.",
              "timeFrame": "From Baseline up to EOS (approximately 5.5 years)"
            },
            {
              "measure": "Change in QLQ-LC13 Subscale Scores",
              "timeFrame": "From Baseline up to EOS (approximately 5.5 years)"
            },
            {
              "measure": "Change in QLQ-C30 Subscale Scores",
              "timeFrame": "From Baseline up to EOS (approximately 5.5 years)"
            },
            {
              "measure": "Time to Deterioration in QLC-LC13 Subscale Scores",
              "timeFrame": "From Baseline to Week 12"
            },
            {
              "measure": "Time to Deterioration in QLC-C30 Subscale Scores",
              "timeFrame": "From Baseline to Week 12"
            },
            {
              "measure": "Change in Summary Scores and Visual Analogue Scale (VAS) Scores",
              "description": "Measured by EuroQol-5 Dimension (EQ-5D-5L).",
              "timeFrame": "From Baseline up to EOS (approximately 5.5 years)"
            },
            {
              "measure": "Duration of Response",
              "description": "Duration of response is defined as the time from the first documentation of objective response until the first documentation of disease progression per BICR or death due to any cause, whichever occurs first.",
              "timeFrame": "From Baseline up to EOS (approximately 5.5 years)"
            },
            {
              "measure": "Time to Response",
              "description": "Defined as the time from randomization to first evidence of PR or CR per BICR.",
              "timeFrame": "From Baseline up to EOS (approximately 5.5 years)"
            },
            {
              "measure": "Disease Control",
              "description": "Defined as CR plus PR plus stable disease based on RECIST v1.1 per BICR.",
              "timeFrame": "From Baseline up to EOS (approximately 5.5 years)"
            },
            {
              "measure": "PFS",
              "description": "Based on investigator tumor assessments per RECIST v1.1.",
              "timeFrame": "From Baseline up to EOS (approximately 5.5 years)"
            },
