        "descriptionModule": {
          "briefSummary": "The purpose of this study is to evaluate the safety of a cancer peptide vaccine to prevent or delay acquired resistance in advanced ALK+ lung cancer patients currently on ALK targeted therapy."
        },
        "conditionsModule": {
          "conditions": [
            "NSCLC Stage IV",
            "ALK Fusion Protein Expression"
          ]
        },
        "designModule": {
          "studyType": "INTERVENTIONAL",
          "phases": [
            "PHASE1",
            "PHASE2"
          ],
          "designInfo": {
            "allocation": "NA",
            "interventionModel": "SINGLE_GROUP",
            "primaryPurpose": "TREATMENT",
            "maskingInfo": {
              "masking": "NONE"
            }
          },
          "enrollmentInfo": {
            "count": 12,
            "type": "ESTIMATED"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Advanced ALK+ NSCLC",
              "type": "EXPERIMENTAL",
              "description": "All patients will receive the intervention",
              "interventionNames": [
                "Biological: Peptide vaccine"
              ]
            }
          ],
          "interventions": [
            {
              "type": "BIOLOGICAL",
              "name": "Peptide vaccine",
              "description": "Peptide vaccine",
              "armGroupLabels": [
                "Advanced ALK+ NSCLC"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Incidence of treatment-related adverse events",
              "description": "The safety of administering the ALK peptide vaccine will be assessed by the occurrence of the following adverse events:\n\n* Grade 3 or above drug-related toxicities\n* Drug-related toxicity by grade\n* Vaccine site reactions after vaccine injections\n* Immune-related adverse events (AEs)\n* Unacceptable toxicities\n* Treatment-emergent changes from normal to abnormal values in key laboratory parameters",
              "timeFrame": "Up to 2 years"
            },
            {
              "measure": "Vaccine-specific immune response",
              "description": "Vaccine-specific response will be evaluated by the fold change in interferon-producing mutant-ALK-specific CD8 and CD4 T cells in the peripheral blood.",
              "timeFrame": "Up to 2 years"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n1. Histologically or cytologically confirmed diagnosis of stage IV NSCLC (or recurrent NSCLC not a candidate for definitive multimodality therapy)\n2. Documented ALK rearrangement as detected by: (1) fluorescence in situ hybridization (FISH), (2) immuno-histochemistry (IHC), (3) tissue next-generation sequencing (NGS), or (4) circulating tumor DNA (ctDNA) NGS\n3. Ongoing treatment with crizotinib, ceritinib, alectinib, brigatinib, or lorlatinib with at least stable disease ≥ 4 months\n4. No known presence of the specific ALK acquired resistance alterations targeted by the study vaccine\n5. Eastern Cooperative Oncology Group (ECOG) performance status of 0 to 1\n6. Males or females at least 18 years old\n\nExclusion Criteria:\n\n1. Known additional malignancy that is progressing or has required active treatment within the past 3 years. Adequately resected non-melanoma skin cancer, curatively treated in-situ disease, and other solid tumors treated with potentially curative therapy are allowed.\n2. Cytotoxic chemotherapy within 14 days of first dose of study vaccine or concurrent with study vaccine\n3. Anti-neoplastic immunotherapy within 28 days of first dose of study vaccine or concurrent with study vaccine\n4. Systemic immune suppression:\n\n   1. Use of chronic oral or systemic steroid medication (topical or inhalational steroids are permitted)\n   2. Other clinically relevant systemic immune suppression\n5. Symptomatic central nervous system (CNS) metastasis. Asymptomatic CNS disease requiring increasing dose of corticosteroids within 7 days prior to study enrollment is also not permitted\n6. Current spinal cord compression (symptomatic or asymptomatic and detected by radiographic imaging). Patients with leptomeningeal disease and without cord compression are allowed",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ]
        },
