          "organization": {
            "fullName": "The Hong Kong Polytechnic University",
            "class": "OTHER"
          },
          "briefTitle": "Mindfulness-Oriented Respiratory Distress Symptom Intervention for Lung Cancer",
          "officialTitle": "Mindfulness-Oriented Respiratory Distress Symptom Intervention for Patients With Lung Cancer: A Feasibility Randomized Controlled Trial"
        },
        "statusModule": {
          "statusVerifiedDate": "2025-05",
          "overallStatus": "RECRUITING",
          "expandedAccessInfo": {
