        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Mindfulness-Oriented Respiratory Distress Symptom Intervention (M-RDSI)",
              "type": "EXPERIMENTAL",
              "description": "Patients in the M-RDSI group will receive a 6-week intervention, including 1) mindfulness training, such as mindful breathing and relaxation; 2) controlled breathing techniques, cough suppression techniques, acupressure, and exercise; and 3) using mindful breathing, relaxation, and attitudes to orientate the practice of RDSI.",
              "interventionNames": [
                "Behavioral: Mindfulness-Oriented Respiratory Distress Symptom Intervention (M-RDSI)"
              ]
            },
            {
              "label": "Usual care",
              "type": "ACTIVE_COMPARATOR",
              "description": "Usual care will receive health educational booklets and routine follow-ups offered by the oncology nurse in the cancer center that patients with lung cancer usually receive during the same 6 weeks.",
              "interventionNames": [
                "Other: Usual Care"
              ]
            }
          ],
          "interventions": [
            {
              "type": "BEHAVIORAL",
              "name": "Mindfulness-Oriented Respiratory Distress Symptom Intervention (M-RDSI)",
              "description": "Patients in the M-RDSI group will receive a 6-week intervention and begin with a training session (ideally face-to-face at the cancer center or the research center or an online meeting as backup for around 60 minutes, including 1) mindfulness training, such as mindful breathing and relaxation; 2) controlled breathing techniques, cough suppression techniques, acupressure, and exercise; and 3) using mindful breathing, relaxation, and attitudes to orientate the practice of RDSI. A second group training session will be conducted 3 weeks later to review the intervention and discuss any questions participants may have. The training sessions will be delivered by a well-trained research assistant from experienced clinicians and the research team. Participants will be guided by the M-RDSI web-based educational materials (e.g., text, pictures, and videos) and a detailed intervention manual for their daily home practice.",
              "armGroupLabels": [
                "Mindfulness-Oriented Respiratory Distress Symptom Intervention (M-RDSI)"
              ]
            },
            {
              "type": "OTHER",
              "name": "Usual Care",
              "description": "Usual care will receive health educational booklets, including brief tips for symptom management designed by the research team, and routine follow-ups offered by the oncology nurse in the cancer center that patients with lung cancer usually receive.",
              "armGroupLabels": [
                "Usual care"
              ]
            }
          ]
        },
