          "secondaryOutcomes": [
            {
              "measure": "Breathlessness",
              "description": "This will be measured by the Dyspnoea-12. Participants will be asked to rate 12 items, with each item scored on a scale from 0 to 3. The total score ranges from 0 to 36, with higher scores indicating more severe symptoms of breathlessness.",
              "timeFrame": "Baseline, immediately after intervention, and at 12-weeks follow-up"
            },
            {
              "measure": "Breathlessness expectation",
              "description": "This will be measured by the Breathlessness word cue set. Participants will be asked to rate 23 items using two Visual Analogue Scales: one for breathlessness and the other for breathlessness-anxiety. Each item ranges from 0% to 100%, with higher scores indicating greater levels of breathlessness or breathlessness-anxiety.",
              "timeFrame": "Baseline, immediately after intervention, and at 12-weeks follow-up"
            },
            {
              "measure": "Cough",
              "description": "This will be measured by the Leicester Cough Questionnaire. Participants will be asked to rate 19 items, each scored on a scale from 1 to 7. The total score is calculated by converting the item scores, yielding a possible range from 3 to 21, with higher scores indicating less severe cough symptoms.",
              "timeFrame": "Baseline, immediately after intervention, and at 12-weeks follow-up"
            },
            {
              "measure": "Fatigue",
              "description": "This will be measured by the Functional Assessment of Chronic Illness Therapy-Fatigue. Participants will be asked to rate 13 items, each scored on a five-point Likert scale from 0 to 4. The total score ranges from 0 to 52, with higher scores indicating less severe fatigue symptoms.",
              "timeFrame": "Baseline, immediately after intervention, and at 12-weeks follow-up"
            },
            {
              "measure": "Mindfulness",
              "description": "This will be measured by the Mindful Attention Awareness Scale. Participants will be asked to rate 15 items, each scored on a six-point Likert scale from 1 to 6. The overall score is obtained by averaging the scores of all items, with higher mean scores indicating a greater level of mindfulness.",
              "timeFrame": "Baseline, immediately after intervention, and at 12-weeks follow-up"
            },
            {
              "measure": "Depression",
              "description": "This will be measured by the Center for Epidemiologic Studies Depression Scale. Participants will be asked to rate 20 items, each scored on a four-point Likert scale from 0 to 3. The total score ranges from 0 to 60, with higher scores indicating more severe depressive symptoms.",
              "timeFrame": "Baseline, immediately after intervention, and at 12-weeks follow-up"
            },
            {
              "measure": "Anxiety",
              "description": "This will be measured by the State-Trait Anxiety Inventory, which consists of two subscales: the State Anxiety Scale and the Trait Anxiety Scale. Each subscale contains 20 items, with each item scored on a four-point Likert scale from 1 to 4. The total score for each subscale ranges from 20 to 80, with higher scores indicating greater levels of state or trait anxiety.",
              "timeFrame": "Baseline, immediately after intervention, and at 12-weeks follow-up"
            },
            {
              "measure": "Quality of life (QoL)",
              "description": "This will be measured by the EuroQoL 5-Dimension 5-Level. Participants will be asked to rate five domains-mobility, self-care, usual activities, pain/discomfort, and anxiety/depression. Each on a five-level scale ranging from no problems to extreme problems. Participants will also be asked to provide an overall assessment of their health using a visual analogue scale from 0 to 100, with higher visual analogue scale scores indicating better quality of life.",
              "timeFrame": "Baseline, immediately after intervention, and at 12-weeks follow-up"
            },
            {
              "measure": "Breathlessness expectation-related brain activity",
              "description": "A task-based fMRI technology will be used to measure breathlessness expectation using a breathlessness word cue set.",
              "timeFrame": "Baseline and immediately after intervention."
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* HK patients who can understand Cantonese, aged 18 years or older;\n* A confirmed diagnosis of an intrathoracic malignancy, including small cell lung cancer, non-small cell lung cancer, or mesothelioma; at any stage of cancer treatment or palliative care;\n* Self-reported impact on daily life from at least two of the three symptoms, where one symptom is breathlessness;\n* Stability of COPD, if present;\n* WHO Performance Status of 0-2;\n* fMRI can be conducted;\n* Expected lifespan of more than six months.\n\nExclusion Criteria:\n\n* Cognitive impairments, severe psychotic symptoms, or other medical conditions that might hinder participation;\n* Participating in mindfulness or other psychological support interventions or symptom management interventions.",
          "healthyVolunteers": true,
          "sex": "ALL",
          "minimumAge": "18 Years",
