          "briefTitle": "GPC3/Mesothelin-CAR-γδT Cells Against Cancers",
          "officialTitle": "GPC3/Mesothelin Targeted CAR-γδT for Immunotherapy of Solid Cancer: Phase I Clinical Trial"
        },
        "statusModule": {
          "statusVerifiedDate": "2024-06",
