        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Number of Patients with Dose Limiting Toxicity",
              "description": "A dose limiting toxicity is defined as any toxicity that is considered to be primarily related to the γδT cells, which is irreversible, or life threatening or hematologic or non-hematologic Grade 3-5.",
              "timeFrame": "Six months"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Percent of Patients with best response as either complete remission or partial remission.",
              "description": "Response rates will be estimated as the percent of patients whose best response is either complete remission or partial remission by combining the data from the patients. To compare with historical data, a 95% confidence interval will be calculated for the response rate.",
              "timeFrame": "Six months"
            },
            {
              "measure": "Median γδT cell persistence",
              "description": "Median γδT cell persistence will be measured by quantitative rt-PCR.",
              "timeFrame": "Six years"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n1\\. Patients with advanced cancer that expresses GPC3 or Mesothelin protein; 2. Life expectancy \\>12 weeks; 3. Adequate heart, lung, liver, kidney, and blood function; 4. Available autologous transduced T cells with greater than or equal to 20% expression of GPC3/Mesothelin-CAR determined by flow-cytometry and killing of Mesothelin-positive targets greater than or equal to 20% in cytotoxicity assay; 5. Informed consent explained to, understood by and signed by patient/guardian. Patient/guardian given copy of informed consent.\n\n\\-\n\nExclusion Criteria:\n\n1. Had accepted gene therapy before;\n2. Severe virus infection such as HBV, HCV, HIV, et al;\n3. Known HIV positivity;\n4. Active infectious disease related to bacteria, virus,fungi,et al;\n5. Other severe diseases that the investigators consider not appropriate;\n6. Pregnant or lactating women;\n7. Systemic steroid treatment (greater than or equal to 0.5 mg prednisone equivalent/kg/day);\n8. Other conditions that the investigators consider not appropriate. -",
          "healthyVolunteers": false,
          "sex": "ALL",
