        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "chemotherapy plus TCM 1&ICIs plusTCM2",
              "type": "EXPERIMENTAL",
              "description": "Phase1： Chemotherapy：Proposed platinum-containing two-drug adjuvant chemotherapy, vincristine/paclitaxel/docetaxel/pemetrexed/gemcitabine plus cisplatin/carboplatin within 8 weeks after surgery, according to CSCO guidelines (2022).\n\nTCM1 granules：oral granules, \"HeWeiYangXueFang\" , twice a day, every 21 days for 4 cycles.\n\nPhase 2： One of the following agents may be selected after chemotherapy ：Nivolumab/Pembrolizumab/Durvalumab/Atezolizumab/ Camrelizumab/Dupilumab/Sintilimab/Tislelizumab.A total of 12 cycles will be performed or the patient will discontinue the drug due to intolerable toxic side effects.\n\nTCM2 granules：oral granules, \"FeiPingFang\" , twice a day, every 21 days for 12 cycles.",
              "interventionNames": [
                "Drug: chemotherapy plus TCM 1&ICIs plusTCM2"
              ]
            },
            {
              "label": "chemotherapy plus TCM 1 placebo&ICIs plus TCM2 placebo",
              "type": "PLACEBO_COMPARATOR",
              "description": "Phase1： Chemotherapy：Proposed platinum-containing two-drug adjuvant chemotherapy, vincristine/paclitaxel/docetaxel/pemetrexed/gemcitabine plus cisplatin/carboplatin within 8 weeks after surgery, according to CSCO guidelines (2022).\n\nPlacebo1 granules: oral granules, which the taste and smell are similar to experimental TCM granules and has no therapeutic effect , twice a day, every 21 days for 4 cycles.\n\nPhase 2：One of the following agents may be selected after chemotherapy：Nivolumab/Pembrolizumab/Durvalumab/Atezolizumab/ Camrelizumab/Dupilumab/Sintilimab/Tislelizumab.A total of 12 cycles will be performed or the patient will discontinue the drug due to intolerable toxic side effects.\n\nPlacebo2 granules: oral granules, which the taste and smell are similar to experimental TCM granules and has no therapeutic effect, twice a day, every 21 days for 12 cycles.",
              "interventionNames": [
                "Drug: chemotherapy plus TCM 1placebo &ICIs plus TCM2 placebo"
              ]
            }
          ],
          "interventions": [
            {
              "type": "DRUG",
              "name": "chemotherapy plus TCM 1&ICIs plusTCM2",
              "description": "In China,TCM herbs are given on the basis of the TCM syndrome differentiation as diagnosed by the TCM herbal specialist. Prescriptions formulated into granules origin from Professor Liu Jia-xiang and Xu Ling. Package of granules is made into two types with functions such as tonifying the stomach and nourishing the blood recipe, benefiting Qi Yin and detoxification and resolving masses recipe. The herbal treatment is adapted to the syndromes.\n\nChemotherapy：Vincristine/paclitaxel/docetaxel/pemetrexed/gemcitabine plus cisplatin/carboplatin：administrated for patients with NSCLC requiring post-operative adjuvant therapy.\n\nICIs：Nivolumab/Pembrolizumab/Durvalumab/Atezolizumab/ Camrelizumab/Dupilumab/Sintilimab/Tislelizumab：administrated for patients with NSCLC requiring post-operative adjuvant therapy.",
              "armGroupLabels": [
                "chemotherapy plus TCM 1&ICIs plusTCM2"
              ]
            },
            {
              "type": "DRUG",
              "name": "chemotherapy plus TCM 1placebo &ICIs plus TCM2 placebo",
              "description": "Chemotherapy：Vincristine/paclitaxel/docetaxel/pemetrexed/gemcitabine plus cisplatin/carboplatin：administrated for patients with NSCLC requiring post-operative adjuvant therapy.\n\nICIs：Nivolumab/Pembrolizumab/Durvalumab/Atezolizumab/ Camrelizumab/Dupilumab/Sintilimab/Tislelizumab：administrated for patients with NSCLC requiring post-operative adjuvant therapy.",
              "armGroupLabels": [
                "chemotherapy plus TCM 1 placebo&ICIs plus TCM2 placebo"
              ]
            }
          ]
