            {
              "measure": "Quality of Life Measurement Scale (EORTC QLQ-C30)",
              "description": "EORTC QLQ-C30 is assessed using and developed by the European Organzation for Research and Treatment of Cancer（EORTC）.QOL is evaluated by comparing changes in the quality of life scales before enrollment and every 1 month after treatment.The maximum score of QLQ-C30 scale is 100 and the minimum score is 0.Higher scores in functional areas and overall health represent better quality of life.Higher scores in the symptom area mean poorer quality of life.",
              "timeFrame": "5 years"
            },
            {
              "measure": "Quality of Life Measurement Specific Module Scale for Patients with Lung Cancer (EORTC QLQ-LC13)",
              "description": "QOL is evaluated by comparing changes in the quality of life scales before enrollment and every 1 month after treatment.The maximum score of QLQ-LC13 scale is 100 and the minimum score is 0.Higher scores mean poorer quality of life.",
              "timeFrame": "5 years"
            },
            {
              "measure": "TCM Symptoms Changes",
              "description": "TCM symptoms changes are according to the lung cancer symptom classification quantization table in \"Guiding Principles for Clinical Research of Traditional Chinese Medicine in the Treatment of Lung Cancer (2002 Edition)\".\n\n1. Significant improvement: clinical syndrome scores decreased by≥ 70%.\n2. Partial improvement: clinical syndrome scores decreased b≥30%;\n3. No improvement: clinical syndrome scores no change, or change\\<30%;\n4. Exacerbation: clinical syndrome scores increases by≥30%.",
              "timeFrame": "5 years"
            },
            {
              "measure": "Laboratory Indicator Evaluation Criteria",
              "description": "Refer to the \"Guidelines for Clinical Research of New Drugs in Traditional Chinese Medicine (Trial)\" (China Medical Science and Technology Press, 2002) to develop evaluation criteria:\n\nImprove: Any increase after treatment is ≥10% before treatment, or from abnormal to normal; Decrease: Anyone who falls ≥10% after treatment or changes from normal to abnormal after treatment; Stable: Anyone who rises or falls less than 10% after treatment compared with before treatment.",
              "timeFrame": "5 years"
            },
            {
              "measure": "Circulating Exosome PD-L1",
              "description": "The circulating exosome PD-L1 evaluation will be measured before treatment, during chemotherapy, before immunotherapy, during immunotherapy, after treatment, and every 6 months during the follow-up period.",
              "timeFrame": "5 years"
            },
            {
              "measure": "Molecular Residual Disease Circulating Tumor DNA(ctDNA-MRD)",
              "description": "The ctDNA-MRD evaluation will be measured before treatment, during chemotherapy, before immunotherapy, during immunotherapy, after treatment, and every 6 months during the follow-up period.",
              "timeFrame": "5 years"
            },
