        "descriptionModule": {
          "briefSummary": "This is an open-label, single-arm clinical study designed to evaluate the safety and preliminary efficacy of EphA2-targeted CAR-DC combined with CAR-T cell therapy in patients with non-small cell lung cancer.",
          "detailedDescription": "Main purpose:\n\nTo evaluate the safety of EphA2-targeted CAR-T cells in combination with CAR-DCs in patients with advanced non-small cell lung cancer during the dose-escalation phase.\n\nTo determine the maximum tolerated dose of EphA2-targeted CAR-DCs when administered in combination with CAR-T cells.\n\nSecondary purpose:\n\nTo assess the overall response rate (ORR), including complete response (CR) and partial response (PR), as well as overall survival (OS) and disease-free survival (DFS) in patients receiving the combination therapy.\n\nTo evaluate the in vivo persistence, immunophenotype, and functional activity of CAR-T cells and CAR-DCs following infusion."
        },
        "conditionsModule": {
          "conditions": [
            "Non-Small Cell Lung Cancer"
          ],
          "keywords": [
            "Chimeric Antigen Receptor Dendritic Cells",
            "Chimeric Antigen Receptor T-Cells",
            "Non-Small Cell Lung Cancer"
          ]
        },
        "designModule": {
          "studyType": "INTERVENTIONAL",
          "phases": [
            "PHASE1"
          ],
          "designInfo": {
            "allocation": "NA",
            "interventionModel": "SINGLE_GROUP",
            "primaryPurpose": "TREATMENT",
