        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "CAR-T and CAR-DC Combination Therapy",
              "type": "EXPERIMENTAL",
              "description": "This arm involves the sequential administration of two biological interventions with EphA2-targeted CAR-DCs administered first, followed by EphA2-targeted CAR-T cells.",
              "interventionNames": [
                "Biological: EphA2-targeted CAR-T Cells",
                "Biological: EphA2-targeted CAR-DCs"
              ]
            }
          ],
          "interventions": [
            {
              "type": "BIOLOGICAL",
              "name": "EphA2-targeted CAR-T Cells",
              "description": "Autologous T cells genetically modified to express a chimeric antigen receptor (CAR) targeting EphA2",
              "armGroupLabels": [
                "CAR-T and CAR-DC Combination Therapy"
              ]
            },
            {
              "type": "BIOLOGICAL",
              "name": "EphA2-targeted CAR-DCs",
              "description": "Autologous dendritic cells (DCs) genetically modified to express a chimeric antigen receptor (CAR) targeting EphA2",
              "armGroupLabels": [
                "CAR-T and CAR-DC Combination Therapy"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Safety: Incidence and severity of adverse events",
              "description": "To evaluate adverse events occurring within the first three months following infusion of EphA2-targeted CAR- T cells and CAR-DCs. The assessment includes incidence and severity of treatment-related symptoms such as neurological toxicity, hematological abnormalities, infections, autoimmune reactions, and secondary malignancies.",
              "timeFrame": "First 3 month post CAR-T cells and CAR-DCs infusion"
            },
            {
              "measure": "Efficacy: Remission Rate",
              "description": "To evaluate the proportion of participants who achieve an objective tumor response, including complete remission (CR) and partial remission (PR)",
              "timeFrame": "3 months post CAR-T cells and CAR-DCs infusion"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Progression-Free Survival",
              "timeFrame": "Up to 24 months post CAR-T cells and CAR-DCs infusion"
            },
            {
              "measure": "Overall Survival",
              "timeFrame": "Up to 24 months post CAR-T cells and CAR-DCs infusion"
            },
            {
              "measure": "Relapse Rate",
              "timeFrame": "Up to 24 months post CAR-T cells and CAR-DCs infusion"
            },
            {
              "measure": "Duration of Response",
              "timeFrame": "Up to 24 months post CAR-T cells and CAR-DCs infusion"
            },
            {
              "measure": "In Vivo Persistence of CAR-T cells and CAR-DCs and Cytokine Profile Monitoring",
              "description": "The copy number of CAR-T cells and CAR-DCs in PBMCs will be measured by qPCR to assess in vivo persistence.\n\nSerum cytokine levels, including IL-2, IL-4, IL-6, IFN-γ, TNF-α, IL-10, IL-12, and IL-17A, will be quantified by ELISA to evaluate immune activation following cell infusion.",
              "timeFrame": "First 2 weeks post CAR-T cells and CAR-DCs infusion"
            },
            {
              "measure": "Objective Response Rate in Participants Receiving Different Doses of CAR-DCs",
              "description": "The proportion of participants in each CAR-DCs dose cohort (5x10\\^6, 1x10\\^7, 3x10\\^7, and 9x10\\^7 cells) who achieve an objective tumor response, including completeremission (CR) or partial remission (PR). All participants received a fixed dose of EphA2-targeted CAR-T cells (2x10\\^6 cells/kg) following CAR-DCs infusion.",
              "timeFrame": "Up to 24 months post CAR-T cells and CAR-DCs infusion"
            },
            {
              "measure": "Incidence and Severity of Treatment-Related Adverse Events in Participants Receiving Different Doses of CAR-DCs",
              "description": "To evaluate adverse events occurring following infusion of EphA2-targeted CAR-DCs and CAR-T cells. Participants will receive CAR-DCs at one of four dose levels (5x10\\^6, 1x1 0\\^7, 3x10\\^7, and 9x10\\^7 cells), followed by a fixed dose of EphA2-targeted CAR-T cells(2x10\\^6 cells/kg). The assessment includes the incidence and severity of treatment-related symptoms such as neurological toxicity, hematological abnormalities, infections, autoimmune reactions, and secondary malignancies.",
              "timeFrame": "Up to 24 months post CAR-T cells and CAR-DCs infusion"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n1. Pathologically confirmed stage IV non-small cell lung cancer (NSCLC) with at least one measurable lesion according to RECIST 1.1 criteria (i.e., a lesion with the longest diameter ≥10 mm on spiral CT scan or a lymph node with a short axis ≥15 mm).\n2. Tumor tissue tested positive for EphA2 expression by immunohistochemistry (≥20%).\n3. Disease progression after standard treatment or no available standard treatment (patients must have received at least two prior systemic therapies, including but not limited to chemotherapy and immune checkpoint inhibitors; patients with actionable driver mutations must have failed targeted therapy).\n4. ECOG performance status: 0-1.\n5. Expected survival ≥6 months.\n6. Toxicities related to prior anti-tumor treatments must have resolved to baseline levels or ≤ Grade 1 (excluding residual alopecia); Grade ≤2 neurotoxicity is acceptable. Washout periods: 4 weeks for chemotherapy and immunotherapy, 2 weeks for targeted therapy.\n7. Adequate organ function, including:\n\n   * Adequate hematologic function: Absolute neutrophil count (ANC) ≥1.5×10\\^9/L, platelet count ≥75×10\\^9/L, hemoglobin ≥9 g/dL. No transfusions, granulocyte colony-stimulating factor (G-CSF), thrombopoietin, or erythropoietin allowed within 14 days before blood tests.\n   * Adequate hepatic function: Total bilirubin (TBIL) \\<1.5× upper limit of normal (ULN); AST and ALT \\<2.5×ULN. For patients with Gilbert's syndrome, TBIL \\<2×ULN; if liver metastases are present, AST and ALT \\<5×ULN.\n   * Adequate renal function: Serum creatinine (Cr) ≤1.5×ULN, or if Cr \\>1.5×ULN, creatinine clearance (CrCl) ≥60 mL/min calculated using the Cockcroft-Gault formula.\n   * Adequate coagulation function: Prothrombin time (PT) and activated partial thromboplastin time (APTT) \\<1.5×ULN; international normalized ratio (INR) \\<1.5 or within the target range if on anticoagulant therapy.\n8. Subjects of reproductive potential must be willing to use effective contraception.\n9. Ability to understand and voluntarily sign the informed consent form.\n10. Willingness to comply with scheduled visits, treatment plans, laboratory tests, and other study procedures.\n\nExclusion Criteria:\n\n1. Pathologically confirmed mixed histology, such as adenosquamous carcinoma of the lung.\n2. Tumor-related emergencies requiring urgent treatment, such as malignant pericardial effusion or cardiac tamponade, superior vena cava syndrome, or spinal cord compression.\n3. Significant cardiovascular diseases, including:\n\n   * Documented cardiovascular events within the past 6 months, such as myocardial infarction, angina, heart failure, severe arrhythmia, or having undergone angioplasty, stent implantation, or coronary artery bypass surgery.\n   * Clinically significant QT/QTcF prolongation (QT/QTcF \\> 470 ms in females or \\> 450 ms in males).\n4. Clinically significant bleeding tendency or coagulation disorders, such as hemophilia.\n5. HIV or syphilis infection; active hepatitis B or C:\n\n   * Hepatitis B: HBV-DNA ≥ 1000 IU/mL.\n   * Hepatitis C: Positive HCV RNA with abnormal liver function.\n6. History of involuntary commitment due to psychiatric disorders or other psychological conditions deemed unsuitable for treatment by the investigator.\n7. Presence of other autoimmune diseases, or long-term use of immunosuppressive agents or corticosteroids.\n8. Poor medication compliance.\n9. Any other condition that the investigator considers grounds for exclusion.",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "maximumAge": "70 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ]
