        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Progression Free Survival (PFS1)",
              "description": "Progression Free Survival using investigator assessments according to Response Evaluation Criteria in Solid Tumours (RECIST 1.1) defined as number of months from first dose of chemotherapy until last follow-up, PD, death or withdrawal of consent.",
              "timeFrame": "2 years"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Progression Free Survival (PFS0)",
              "description": "Progression Free Survival using investigator assessments according to Response Evaluation Criteria in Solid Tumours (RECIST 1.1) defined as number of months from first dose of osimertinib until last follow-up, PD, death or withdrawal of consent.",
              "timeFrame": "for a minimum of 24 months from inclusion"
            },
            {
              "measure": "Overall Survival (OS1)",
              "description": "OS1 Survival will be calculated from the first dose of chemotherapy until the date of death from any cause. If no event is observed (e.g. lost to follow-up) OS is censored at the day of last subject contact.",
              "timeFrame": "for a minimum of 24 months from inclusion"
            },
            {
              "measure": "Overall Survival (OS0)",
              "description": "OS0 Survival will be calculated from the date of start of osimertinib until the date of death from any cause. If no event is observed (e.g. lost to follow-up) OS is censored at the day of last subject contact.",
              "timeFrame": "for a minimum of 24 months from inclusion"
            },
            {
              "measure": "Incidence of treatment related Adverse Events (Safety and Tolerability)",
              "description": "Frequency and severity of Adverse Events, grading according to CTCAE V5.0",
              "timeFrame": "up to 16 weeks from start of study treatment"
