        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Chronic Respiratory Questionnaire (CRQ): sub scale mastery",
              "description": "The CRQ is a validated 20-item health-related quality of life questionnaire in which experiences are rated on seven-point scales ranging from 1 (maximum impairment) to 7 (no impairment). The CRQ mastery is a domain of the CRQ which comprises four questions with a range of scores also ranging from 1 to 7",
              "timeFrame": "From enrollment to the end of the intervention at 6 weeks."
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Worst breathlessness on the numerical rating scale (NRS)",
              "description": "The numerical rating scale (NRS) ranges from 0 (no breathlessness) to 10 (worst breathlessness).",
              "timeFrame": "From enrollment (T0) to the end of the intervention at 6 weeks."
            },
            {
              "measure": "Physical and affective component of dyspnea with the Dyspnea-12 scale",
              "description": "The Dyspnea-12 (D-12) scale is a tool to help to assess the dyspnea. Dyspnea is a multidimensional symptom, comprising physical (intensity, location, temporality and sensory quality) and affective (unpleasant) sensations.\n\nThis D-12 questionnaire is a dyspnea assessment tool. It contains 12 items. The first 7 items correspond to the evaluation of the sensory aspect and the next 5 to the evaluation of the affective aspect. The higher is the score the higher is the burden of dyspnea.",
              "timeFrame": "From enrollment (T0) to the end of the intervention at 6 weeks"
            },
            {
              "measure": "Quality of Life with EQ5D5L",
              "description": "The EQ-5D-5L essentially consists of the EQ-5D descriptive system and the EQ visual analogue scale (EQ VAS).\n\nThe descriptive system comprises five dimensions: mobility, self-care, usual activities, pain/discomfort and anxiety/depression. Each dimension has 5 levels. The patient is asked to indicate his/her health state by ticking the box next to the most appropriate statement in each of the five dimensions. This decision results in a 1-digit number that expresses the level selected for that dimension. The digits for the five dimensions can be combined into a 5-digit number that describes the patient's health state.\n\nThe EQ VAS records the patient's self-rated health on a vertical visual analogue scale where the endpoints are labelled 'The best health you can imagine' and 'The worst health you can imagine'. The VAS can be used as a quantitative measure of health outcome that reflects the patient own judgement.",
              "timeFrame": "From enrollment (T0) to the end of the intervention at 6 weeks"
            },
            {
              "measure": "Acceptability",
              "description": "Acceptability will be evaluate at the end of the 3 hypnosis session. with the help of a Lickert scale: completely agree, agree, neutral, don't agree, completely disagree.",
              "timeFrame": "at the end of the intervention at 6 weeks"
            },
            {
              "measure": "Anxiety an Depression (HADS)",
              "description": "Anxiety an Depression wil be evaluated with HADS questionnaire which comprises two sub-cathegories, HADS-D for dépression (0-21) and HADS-A for anxiety (0-21)",
              "timeFrame": "From enrollment (T0) to the end of the intervention at 6 weeks"
            },
            {
              "measure": "Duration of hypnosis sessions",
              "description": "duration in minutes for each hypnosis sessions",
              "timeFrame": "After each hypnosis sessions (at 2, 4 and 6 weeks)"
            }
          ],
          "otherOutcomes": [
            {
              "measure": "Oxygen saturation",
              "description": "Measurement of oxygen saturation through a pulse oximeter in %. It will be measured before and after each session of hypnosis with recording of maximal value",
              "timeFrame": "Before and after hypnosis sessions (which will take place at 2,4 and 6 weeks after enrollement)."
            },
            {
              "measure": "Auto-hypnosis",
              "description": "Patient will record the number of auto-hypnosis realized between the sessions of hypnosis in an agenda given at the enrollement in the study.",
              "timeFrame": "From enrollment (T0) to the end of the intervention at 6 weeks"
            },
            {
              "measure": "Heart rate",
              "description": "Heart rate ( in beat/min) will be recorded with the help of a pulse oximeter at the finger tip. Maximal value will be recorded after a measurement of 30 seconds.",
              "timeFrame": "Before and after hypnosis sessions (which will take place at 2,4 and 6 weeks after enrollement)."
            },
            {
              "measure": "Respiratory rate",
              "description": "Respiratory rate will be recorded counting the number of breathing in 30 seconds and reported in respiration/min.",
              "timeFrame": "Before and after hypnosis sessions (which will take place at 2,4 and 6 weeks after enrollement)."
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Patients aged ≥ 18 years and\n* Primary diagnosis of metastatic cancer, COPD stage at least B or E, ILD, or CHF and\n* Dyspnea stage NYHA ≥ II or mMRC ≥ 2\n\nExclusion Criteria:\n\n* Have had hypnosis treatment in the last 12 months\n* Have an estimated life expectancy of less than 6 months\n* Have participated in pulmonary rehabilitation in the last 6 months\n* Have been hospitalised in the last month (30 days)\n* Are unable to come to the hospital for 3 outpatient consultations (1 every two weeks)\n* Have a condition that would interfere with their ability to respond to the questionnaires (i.e. cognitive impairment, hearing impairment, etc.)\n* Are not eligible for a hypnosis session due to a psychiatric disorder",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
