        "descriptionModule": {
          "briefSummary": "The purpose of this study is to find out whether a Hospital-at-Home (HaH) program is a more efficient way to monitor people's health after receiving tarlatamab than monitoring in the hospital (inpatient)."
        },
        "conditionsModule": {
          "conditions": [
            "Small-cell Lung Cancer",
            "Small Cell Lung Carcinoma"
          ],
