        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Control Arm",
              "type": "NO_INTERVENTION",
              "description": "Participants randomized to the control group will receive tarlatamab administration as per usual care."
            },
            {
              "label": "Hospital-at-Home/HAH Intervention Arm",
              "type": "EXPERIMENTAL",
              "description": "Participants randomized to the intervention group will receive tarlatamab administration through the hospital-at-home care delivery model.",
              "interventionNames": [
                "Other: Hospital-at-Home/HAH"
              ]
            }
          ],
          "interventions": [
            {
              "type": "OTHER",
              "name": "Hospital-at-Home/HAH",
              "description": "After discharge, a SeniorCare community paramedic will provide a home visit to the participant's home or residence",
              "armGroupLabels": [
                "Hospital-at-Home/HAH Intervention Arm"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Number of inpatient hospital days",
              "description": "Evaluate whether HaH in combination with an enhanced oncology specific telemedicine platform is efficient by quantifying inpatient hospital days during the two 7-day periods (14 days total) after the tarlatamab infusions scheduled for C1D1 and C1D8",
              "timeFrame": "14 days"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\nPatient\n\n* Diagnosis of extensive stage small cell lung carcinoma (ES-SCLC)\n* Treatment plan of commercially available tarlatamab monotherapy as standard of care\n* Patients must be 18 years of age or older\n* Eastern Cooperative Oncology Group (ECOG) performance status \\<2\n* Patients must have adequate organ and bone marrow function, defined by the following laboratory results obtained within 28 days prior to the first study treatment:\n\n  * ANC ≥ 1000 cells/μL (without granulocyte colony stimulating factor support within 4 weeks prior to Cycle 1, Day 1)\n  * Platelet count ≥50,000/μL (without transfusion within 4 weeks prior to Cycle 1, Day 1)\n  * Hemoglobin ≥8.0 g/dL (without transfusion within 4 weeks prior to Cycle 1, Day 1)\n  * Alanine aminotransferase (ALT), aspartate aminotransferase (AST) ≤ 3 X upper limit of normal (ULN). Serum bilirubin ≤ 1.5 x ULN. Patients with known Gilbert disease who have serum bilirubin level ≤ 2 x ULN may be enrolled.\n  * Estimated Glomerular Filtration Rate (eGFR) ≥ 30mL/min using the CKD-EPI formula.\n* The patient is willing to give and sign informed consent\n* Appropriate homebound setting as defined by one of the following:\n\n  * Lodging at MSK Residence or hotel\n  * 5 New York City boroughs, lower Westchester County (northern boundary Cross County Parkway) and Nassau County (eastern boundary Wantagh State Parkway). This is based on the community paramedic (SeniorCare) 60-minute response time catchment area. If there is any uncertainty about patient residence eligibility, the Principal Investigator will decide after discussion with SeniorCare.\n* Patients must be accompanied by a caregiver for the period of time the patient is enrolled in the HaH intervention. For cases where there is uncertainty, the Principal Investigator will make the final determination.\n\nCaregiver\n\n* Primary caregiver as identified by patient enrolled on study\n\nPhysician\n\n* Treating physician for patient(s) enrolled on study; managing treatment plan of commercially available tarlatamab as standard of care\n\nExclusion Criteria:\n\nPatient\n\n* Patients with a documented active infection prior to starting tarlatamab. This includes grade 3 or higher viral, bacterial, or fungal infection.\n* Patients with baseline dementia or cognitive barriers\n* Uncontrolled arrhythmias\n\nCaregiver\n\n* Caregiver deemed inappropriate by treating physician\n\nPhysician\n\n* No exclusion criteria",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ]
        },
