    {
      "protocolSection": {
        "identificationModule": {
          "nctId": "NCT06545747",
          "orgStudyIdInfo": {
            "id": "A2024-001"
          },
          "organization": {
            "fullName": "Sun Yat-sen University",
            "class": "OTHER"
          },
          "briefTitle": "Adaptive Hypofractionated Radiotherapy for Locally Advanced NSCLC Based on Dynamic Enhanced MRI",
          "officialTitle": "A Randomized Controlled Phase III Study of Adaptive Hypofractionated Radiotherapy Combined With Concurrent Chemotherapy and Consolidative Immunotherapy in Locally Advanced Non-Small Cell Lung Cancer Based on Dynamic Enhanced Magnetic Resonance Imaging"
        },
        "statusModule": {
          "statusVerifiedDate": "2025-07",
          "overallStatus": "RECRUITING",
          "expandedAccessInfo": {
            "hasExpandedAccess": false
          },
          "startDateStruct": {
            "date": "2024-08-01",
            "type": "ACTUAL"
          },
          "primaryCompletionDateStruct": {
            "date": "2028-07-31",
            "type": "ESTIMATED"
          },
          "completionDateStruct": {
            "date": "2028-07-31",
            "type": "ESTIMATED"
          },
          "studyFirstSubmitDate": "2024-08-04",
          "studyFirstSubmitQcDate": "2024-08-08",
          "studyFirstPostDateStruct": {
            "date": "2024-08-09",
            "type": "ACTUAL"
          },
          "lastUpdateSubmitDate": "2026-04-03",
          "lastUpdatePostDateStruct": {
            "date": "2026-04-06",
            "type": "ACTUAL"
          }
        },
        "sponsorCollaboratorsModule": {
          "responsibleParty": {
            "type": "PRINCIPAL_INVESTIGATOR",
            "investigatorFullName": "Hui Liu",
            "investigatorTitle": "Professor",
            "investigatorAffiliation": "Sun Yat-sen University"
          },
          "leadSponsor": {
            "name": "Sun Yat-sen University",
            "class": "OTHER"
          }
        },
        "oversightModule": {
          "isFdaRegulatedDrug": false,
          "isFdaRegulatedDevice": false
        },
        "descriptionModule": {
          "briefSummary": "This study is a randomized phase III trial that aiming to investigate the role of dynamic contrast-enhanced magnetic resonance imaging (DCE-MRI) guided hypofractionated radiotherapy (hypo-RT) in patients with locally advanced non-small cell lung cancer (LA-NSCLC) who are planned to receive hypo-RT combined with concurrent chemotherapy and consolidative immunotherapy. Patients will be randomized in a 1:1 ratio into two groups:\n\n1. The study group will undergo adaptive dose-painting hypo-RT based on DCE-MRI.\n2. The control group will undergo hypo-RT based on enhanced CT.\n\nThe treatment-related toxicity, local control and long-term survival will be evaluated compared between MRI-guided and CT-guided hypo-RT."
        },
        "conditionsModule": {
          "conditions": [
            "Non-small Cell Lung Cancer"
          ],
          "keywords": [
            "hypo-fractionated radiotherapy",
            "consolidative immunotherapy",
            "MRI-guided"
          ]
        },
        "designModule": {
          "studyType": "INTERVENTIONAL",
          "phases": [
            "PHASE3"
          ],
          "designInfo": {
            "allocation": "RANDOMIZED",
            "interventionModel": "PARALLEL",
            "primaryPurpose": "TREATMENT",
            "maskingInfo": {
              "masking": "NONE"
            }
          },
          "enrollmentInfo": {
            "count": 490,
            "type": "ESTIMATED"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "MRI-based hypo-RT",
              "type": "EXPERIMENTAL",
              "description": "Patients will receive split-course hypo-RT combined with concurrent chemotherapy and consolidative immunotherapy. The experimental arm will undergo adaptive dose-painting hypo-RT based on DCE-MRI.",
              "interventionNames": [
                "Radiation: DCE-MRI based split-course hypo-RT",
                "Drug: Concurrent chemotherapy",
                "Drug: Consolidative immunotherapy"
              ]
            },
            {
              "label": "CT-based hypo-RT",
              "type": "ACTIVE_COMPARATOR",
              "description": "Patients will receive split-course hypo-RT combined with concurrent chemotherapy and consolidative immunotherapy. The control arm will undergo hypo-RT based on CT.",
              "interventionNames": [
                "Radiation: CT based split-course hypo-RT",
                "Drug: Concurrent chemotherapy",
                "Drug: Consolidative immunotherapy"
              ]
            }
          ],
          "interventions": [
            {
              "type": "RADIATION",
              "name": "DCE-MRI based split-course hypo-RT",
              "description": "Tumor delineation will be based on DCE-MRI and CT. MRI help define the tumor boundary. Different radiation doses will be delivered based on the Ktrans value of the tumor area on DCE-MRI.",
              "armGroupLabels": [
                "MRI-based hypo-RT"
              ]
            },
            {
              "type": "RADIATION",
              "name": "CT based split-course hypo-RT",
              "description": "Tumor delineation will be based on CT. The total dose for both the first and boost courses of hypo-RT to the tumor area will be constant.",
              "armGroupLabels": [
                "CT-based hypo-RT"
              ]
            },
            {
              "type": "DRUG",
              "name": "Concurrent chemotherapy",
              "description": "Concurrent Chemotherapy consists of weekly albumin-bound paclitaxel 50mg/m2, d1 plus cisplatin 25mg/m2，d1.",
              "armGroupLabels": [
                "CT-based hypo-RT",
                "MRI-based hypo-RT"
              ]
            },
            {
              "type": "DRUG",
              "name": "Consolidative immunotherapy",
              "description": "Consolidative PD-1/PD-L1 inhibitors",
              "armGroupLabels": [
                "CT-based hypo-RT",
                "MRI-based hypo-RT"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "treatment-related G2+ respiratory toxicity",
              "description": "the percentage of patients who developed G2+ respiratory toxicity, including pneumonitis and proximal bronchial tree toxicity",
              "timeFrame": "Recorded from the enrollment to 1 year after the completion of hypo-RT or 3 months after the completion of consolidative immunotherapy"
            },
            {
              "measure": "progression-free survival rate",
              "timeFrame": "2-year"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "local control rate",
              "timeFrame": "2-year"
            },
            {
              "measure": "overall survival rate",
              "timeFrame": "2-year"
            },
            {
              "measure": "patient reported outcome assessed by QLQ-C30",
              "description": "assessed by QLQ-C30",
              "timeFrame": "2 year"
            },
            {
              "measure": "patient reported outcome",
              "description": "assessed by QLQ-LC13 questionnaires",
              "timeFrame": "2 year"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Male or female aged between 18 and 75 years old.\n* Patients must have histological or cytological confirmation of locally advanced, unresectable (stage III) non-small cell lung cancer (NSCLC).\n* No prior radiation therapy or surgery.\n* Expected life expectancy of at least 12 weeks.\n* World Health Organization (WHO) performance status score of 0 or 1.\n* Able to undergo magnetic resonance imaging (MRI) examination.\n* Organ and bone marrow function meeting the following criteria: Forced expiratory volume in 1 second (FEV1) ≥ 800 ml; Absolute neutrophil count ≥ 1.5 × 10\\^9/L; Platelets ≥ 100 × 10\\^9/L; Hemoglobin ≥ 9.0 g/dL; Serum creatinine clearance rate calculated by the Cockcroft-Gault formula ≥ 50 mL/min (Cockcroft and Gault 1976); Serum bilirubin ≤ 1.5 times the upper limit of normal (ULN); Aspartate transaminase (AST) and alanine transaminase (ALT) ≤ 2.5 times ULN.\n\nExclusion Criteria:\n\n* Contraindications to MRI examination.\n* Concurrent participation in another clinical study, unless it is an observational (non-interventional) clinical study.\n* Histological type of mixed small cell and non-small cell lung cancer.\n* The presence of sensitive EGFR mutations or ALK rearrangements.\n* Major surgery performed within 4 weeks prior to entering the study (excluding vascular access).\n* History or occurrence of autoimmune disease within the past 2 years.\n* Active or history of inflammatory bowel disease (e.g., Crohn's disease, ulcerative colitis).\n* History of primary immunodeficiency.\n* History of organ transplantation requiring immunosuppressive therapy.\n* Average QT interval (QTc) ≥ 470 ms calculated from 3 ECG cycles using Bazett's correction.\n* Uncontrolled comorbidities, including but not limited to persistent or active infection, symptomatic congestive heart failure, poorly controlled hypertension, unstable angina, arrhythmia, active peptic ulcer disease or gastritis, active bleeding disorder, human immunodeficiency virus (HIV), or psychiatric/social situations that would limit compliance with study requirements or impair the ability to provide written informed consent.\n* Active tuberculosis.\n* Receipt of a live attenuated vaccine within 30 days prior to the start of the study.\n* History of another primary malignancy within 5 years, excluding adequately treated basal or squamous cell skin cancer or in situ cervical cancer.\n* Pregnant or breastfeeding women; or males and females of reproductive potential not using effective contraception.",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "maximumAge": "75 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ]
        },
