        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Completion of chest computed tomography (CT) (Aim 1.2)",
              "description": "Will be compared between arms using the Cochran-Mantel-Haenszel (CMH) test, accounting for the stratification variables used during randomization. Completion rates will also be estimated in each arm and 95% confidence intervals for the rates and their difference will be calculated using Wilson's score method. The single primary outcome will be tested using two-sided α = 0.05.",
              "timeFrame": "Up to 6 months"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Completion of low dose computed tomography of the chest (Aim 1.2)",
              "description": "Will be compared between arms using the CMH test. Will be tested using two-sided α = 0.05 without adjustment for multiplicity.",
              "timeFrame": "Up to 21 months"
            },
            {
              "measure": "Lung cancer screening (LCS) knowledge (Aim 1.2)",
              "description": "Will be compared between arms using a stratified Wilcoxon rank-sum test (van Elteren test). Will be tested using two-sided α = 0.05 without adjustment for multiplicity.",
              "timeFrame": "At 21 months"
            },
            {
              "measure": "Health-related quality of life (Aim 1.2)",
              "description": "Will be measured using the Short Form 36 Health Survey questionnaire. Will be compared between arms using a stratified Wilcoxon rank-sum test (van Elteren test). Will be tested using two-sided α = 0.05 without adjustment for multiplicity.",
              "timeFrame": "At 21 months"
            },
            {
              "measure": "Rate of reported 30-day cessation period (Aim 1.2)",
              "description": "The impact of navigation on tobacco cessation will be explored by the rates of a reported 30-day cessation period during the intervention period as measured by self-reported 30-day floating abstinence.",
              "timeFrame": "Up to 6 months"
            },
            {
              "measure": "Completion of chest CT (Aim 2)",
              "description": "Quantitative analyses will use structural equation models (SEM) to understand the relationships between measured and latent variables representing barriers, facilitators and social determinants of health and the outcome of CT completion.",
              "timeFrame": "Up to 6 months"
            },
            {
              "measure": "Navigation care engagement (Aim 2)",
              "description": "Quantitative analyses in this aim will use SEM to understand the relationships between measured and latent variables representing barriers, facilitators and social determinants of health and the outcome of navigation care engagement. Measure of reach will be operationalized as an ordinal scale based on care completion activities along the LCS continuum as documented in the electronic health record.",
              "timeFrame": "Up to 21 months"
            },
            {
              "measure": "Completion of chest CT (Aim 3)",
              "description": "The rate of chest CT completion during the maintenance phase in the control arm (after navigation is offered) will be estimated and compared with the rate during the trial phase (before navigation was offered) using Poisson regression with the log link. The phase (trial versus maintenance) will be modeled using a time varying covariate, where each participant will contribute an outcome for each phase in which they are still \"at risk\" for completing CT (i.e., until first CT completion or end of follow-up). Models will include additional key covariates, including clinical site, smoking status, and prior reported LCS. Generalized estimating equations will be used to account for multiple periods per participant and potential overdispersion.",
              "timeFrame": "Up to 15 months"
            },
            {
              "measure": "Completion of next diagnostic step in LCS follow-up",
              "description": "Adherence to follow-up will be assessed as binary completion of the next step in follow-up among those with a completed chest CT during the randomized controlled trial. Appropriate next step in follow-up is determined through the Lung CT Screening Reporting and Data System (Lung-RADS) system, with most participants having negative initial CT (Lung-RADS 1 or 2) with follow-up assessed at 11-15 months. Adherence rates will be estimated as a proportion with 95% confidence intervals, summarized overall and stratified by Lung-RADS.",
              "timeFrame": "Up to 15 months"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* AIM 1.2 RANDOMIZED CONTROLLED TRIAL: Between ages 50-77\n* AIM 1.2 RANDOMIZED CONTROLLED TRIAL: Self-reported 20-pack year smoking history\n* AIM 1.2 RANDOMIZED CONTROLLED TRIAL: Ongoing commercial tobacco use within the past 15 years\n* AIM 1.2 RANDOMIZED CONTROLLED TRIAL: Seen by a PCP at a participating clinic (South Puget Intertribal Planning Agency \\[SPIPA\\] or Muckleshoot) within the past three years\n\n  * Potential participants who want to establish care at an eligible clinic will be connected to a PCP\n* AIM 2 CLINICAL STAFF SURVEYS AND SEMI-STRUCTURED INTERVIEWS: At least 18 years of age\n* AIM 2 CLINICAL STAFF SURVEYS AND SEMI-STRUCTURED INTERVIEWS: Affiliation with Muckleshoot or SPIPA (one of the 6 community partnering clinics) as a provider, or supportive staff member\n* AIM 2 PATIENT SURVEYS AND SEMI-STRUCTURED INTERVIEWS: Patient participated in the aim 1.2 trial\n* AIM 3 CLINICAL STAFF SURVEYS AND SEMI-STRUCTURED INTERVIEWS: At least 18 years of age\n* AIM 3 CLINICAL STAFF SURVEYS AND SEMI-STRUCTURED INTERVIEWS: Affiliation with Muckleshoot or SPIPA (one of the 6 community partnering clinics) as a provider, or supportive staff member\n* AIM 3 PATIENT SURVEYS AND SEMI-STRUCTURED INTERVIEWS: Patient participated in the aim 1.2 trial\n\nExclusion Criteria:\n\n* AIM 1.2 RANDOMIZED CONTROLLED TRIAL: Has had a documented chest CT within the past one year\n* AIM 1.2 RANDOMIZED CONTROLLED TRIAL: Personal history of lung cancer or symptoms associated with lung cancer",
          "healthyVolunteers": true,
