        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Machine Learning Modelling",
              "description": "Characterise machine learning models for the four disease sites. Developing machine learning algorithms for autosegmentation of normal tissue anatomy, and to extend machine learning algorithms to identify and segment normal tissue structures in cone beam CT images, and to utilise the ML segmentations to evaluate image signatures correlated with treatment toxicity",
              "timeFrame": "8 years from FPFV"
            },
            {
              "measure": "Predictive Modelling",
              "description": "Predict performance matches with published techniques. Combining the machine learning models in outcome 1, with pre-treatment assessment data and on-treatment quantitative assessments in outcome 3 for the construction and evaluation of a predictive mathematical model",
              "timeFrame": "8 years from FPFV"
            },
            {
              "measure": "Clinical Toxicity Evaluation",
              "description": "Evaluation of the clinical toxicity experienced by each patient up to 5 years post radiotherapy to inform the predictive models in outcome 2",
              "timeFrame": "8 years from FPFV"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Participant is willing and able to give informed consent for participation in the study\n* Male or Female\n* Aged 18 years or older\n* Diagnosed with primary prostate cancer, head and neck cancer, lung cancer, or brain tumour\n* Treated with curative intent\n* Suitable for radical image guided radiotherapy\n* WHO ECOG performance status 0 or 1\n* Expected survival of 18 months or more\n\nExclusion Criteria:\n\n* Participant is not willing or able to complete the protocol-stated requirements of the study, e.g. accessing \\& completing web-based long-term follow-up questionnaires.",
