          "briefTitle": "FAP-targeted PET/NIR in Lung Malignant Tumors",
          "officialTitle": "Visualization Study on Tumor Progression Mechanisms and Key Molecular Functions in Neoadjuvant Immunotherapy for Lung Cancer: Preoperative Efficacy Prediction and Intraoperative Fluorescence Navigation"
        },
        "statusModule": {
          "statusVerifiedDate": "2025-05",
          "overallStatus": "RECRUITING",
          "expandedAccessInfo": {
            "hasExpandedAccess": false
          },
          "startDateStruct": {
