          "lastUpdateSubmitDate": "2026-03-26",
          "lastUpdatePostDateStruct": {
            "date": "2026-04-01",
            "type": "ACTUAL"
          }
        },
        "sponsorCollaboratorsModule": {
          "responsibleParty": {
            "type": "PRINCIPAL_INVESTIGATOR",
            "investigatorFullName": "Chen KeZhong",
            "investigatorTitle": "Director of Thoracic Oncology Institute",
            "investigatorAffiliation": "Peking University People's Hospital"
          },
          "leadSponsor": {
            "name": "Peking University People's Hospital",
            "class": "OTHER"
          }
        },
        "oversightModule": {
          "oversightHasDmc": false,
          "isFdaRegulatedDrug": false,
          "isFdaRegulatedDevice": false
        },
        "descriptionModule": {
          "briefSummary": "Single center, prospective, diagnostic study. Patients with stage II-IIIB resectable NSCLC diagnosed by pathology were included. After receiving standard neoadjuvant therapy (chemotherapy/immunotherapy/combination therapy), FAPI-PET/CT and fluorescence imaging were performed one week before surgery. During the surgery, a near-infrared fluorescence navigation system was used to locate the tumor lesion. After surgery, the tumor bed range was determined by pathological gold standards (HE staining+immunohistochemistry), and the predictive efficacy and localization accuracy of FAPI-PET/fluorescence were compared and analyzed.",
          "detailedDescription": "This is a prospective, exploratory clinical study designed to evaluate the role of FAP-targeted imaging in efficacy prediction and tumor bed delineation in patients with NSCLC undergoing surgical resection after neoadjuvant therapy. Following neoadjuvant treatment, enrolled patients will undergo preoperative FAP-targeted PET imaging to assess treatment response and identify metabolically active tumor-associated stromal regions. Surgical resection will be performed according to standard clinical practice. Immediately after tumor resection, ex vivo fluorescence imaging of the surgical specimen will be conducted using a EB-FAPI fluorescence probe. Based on fluorescence signal distribution, systematic multipoint sampling will be performed across tumor center, tumor margin, and adjacent normal tissues. Routine pathological sampling will be conducted in parallel according to standard protocols. Additional fluorescence-guided sampling will be performed in regions with persistent fluorescence signals. Histopathological analysis will be used as the reference standard to evaluate tumor bed distribution, residual tumor presence, and pathological response. The concordance between fluorescence imaging, PET imaging, and pathological findings will be analyzed. The study will also evaluate whether fluorescence-guided sampling can improve detection of residual tumor and reduce false-negative pathological assessments. This study aims to establish a multimodal imaging approach integrating preoperative molecular imaging and intraoperative fluorescence guidance to enhance tumor bed visualization and improve the accuracy of pathological response assessment after neoadjuvant therapy in NSCLC."
        },
        "conditionsModule": {
          "conditions": [
            "Non-Small Cell Lung Cancer",
            "PET/CT",
            "Neoadjuvant Therapy"
          ],
          "keywords": [
            "PET Imaging",
            "NIR Imaging",
            "Neoadjuvant Therapy",
            "Non-Small Cell Lung Cancer"
          ]
        },
        "designModule": {
          "studyType": "OBSERVATIONAL",
          "patientRegistry": false,
          "designInfo": {
            "observationalModel": "COHORT",
            "timePerspective": "PROSPECTIVE"
          },
          "bioSpec": {
            "retention": "SAMPLES_WITHOUT_DNA",
            "description": "tissue"
          },
          "enrollmentInfo": {
            "count": 200,
            "type": "ESTIMATED"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "FAP-targeted PET in lung malignant tumors",
              "description": "Participant who conforms to the inclusion criteria will undergo 68Ga-FAPI/EB-FAPI PET/CT scans within 1 week.",
              "interventionNames": [
                "Diagnostic Test: PET/CT scans"
              ]
            }
          ],
          "interventions": [
            {
              "type": "DIAGNOSTIC_TEST",
              "name": "PET/CT scans",
              "description": "PET Dynamic Data: The tracer is administered based on the patient's body weight at approximately 0.06-0.12 mCi/kg. PET scanning is initiated simultaneously with tracer injection, followed by a flush with 10 ml of normal saline. The image acquisition matrix is 192 × 192. Reconstruction is performed using the OSEM algorithm with 4 iterations and 20 subsets, incorporating time-of-flight attenuation correction, scatter correction, and random correction. The total duration of PET dynamic data acquisition is 60 minutes. Processing of PET dynamic scan data: Dynamic PET images are divided into 2-minute intervals to obtain time-activity curves by extracting the radioactivity within regions of interest at different time points, reflecting tracer uptake and enabling calculation of the time to peak. Multi-modality imaging data are analyzed by radiologists with over 10 years of experience in diagnosing respiratory diseases.",
              "armGroupLabels": [
                "FAP-targeted PET in lung malignant tumors"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Accuracy of EB-FAPI fluorescence imaging for tumor bed delineation after neoadjuvant therapy",
              "description": "To evaluate the accuracy of intraoperative FAP-targeted fluorescence imaging in identifying the tumor bed after neoadjuvant therapy in NSCLC patients, using histopathological assessment as the reference standard. Tumor bed regions identified by fluorescence will be compared with pathological mapping of tumor, regression bed, and residual tumor distribution.",
              "timeFrame": "From surgery to completion of postoperative pathological evaluation (within 2 weeks after surgery)"
            },
            {
              "measure": "Diagnostic performance of preoperative FAPI PET for treatment response assessment",
              "description": "To evaluate the ability of preoperative FAPI PET imaging to predict pathological response after neoadjuvant therapy, using pathological response (pCR/MPR/non-MPR) as the reference standard.",
              "timeFrame": "From preoperative imaging to postoperative pathological assessment (within 4 weeks)"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Correlation between fluorescence signal intensity and pathological features",
              "description": "To evaluate the correlation between fluorescence signal intensity and pathological parameters, including tumor cell density, regression bed, and FAP expression (e.g., immunohistochemistry), across tumor (T), margin (M), and normal (N) regions.",
              "timeFrame": "Postoperative specimen analysis (within 2-3 weeks after surgery)"
            },
            {
              "measure": "Tumor-to-background ratio (TBR) of fluorescence imaging in surgical specimens",
              "description": "To quantify fluorescence signal contrast between tumor, tumor margin, and normal tissues, and determine optimal thresholds for tumor bed delineation.",
              "timeFrame": "Postoperative specimen analysis (within 2-3 weeks after surgery)"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Age between 18 and 70 years old;\n* Have complete clinical and imaging data;\n* Prior to neoadjuvant therapy, the biopsy pathology showed lung cancer;\n* Able to retain sufficient tumor tissue for testing and research;\n* Sign informed consent.\n\nExclusion Criteria:\n\n* Previously combined with other malignant tumors or received other anti-tumor treatments;\n* Failure to collect sufficient tumor tissue for testing and research;\n* The duration of neoadjuvant therapy is less than 3 cycles;\n* The dynamic scanning image quality of multimodal probe PET cannot meet the analysis standards or is missing;\n* Lack of clinical and imaging data;\n* There are situations where other researchers consider it inappropriate to participate in this study",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "maximumAge": "70 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ],
          "studyPopulation": "patients with lung cancer who plan to receive neoadjuvant immunotherapy combined with chemotherapy",
          "samplingMethod": "NON_PROBABILITY_SAMPLE"
        },
