          "briefTitle": "Acupuncture Combined With PD-1/PD-L1 Inhibitors for Advanced Lung Cancer",
          "officialTitle": "Effectiveness of Acupuncture Combined With PD-1/PD-L1 Inhibitors for Advanced Lung Cancer：A Randomized Controlled Clinical Study"
        },
        "statusModule": {
