          "interventions": [
            {
              "type": "DEVICE",
              "name": "Acupuncture",
              "description": "Both groups have a standard anti-tumor Western medical treatment regimen (PD-1/PD-L1 inhibitor combined with chemotherapy); the acupuncture group is combined with acupuncture treatment. The day of starting antitumor treatment for each cycle was D1; D1-D5 was performed by the investigator on the patient for 2 times of acupuncture treatment, once a day; D8-D13 and D15-D20 were operated by patients or family members, and the investigator remotely assisted via video to complete the press needle treatment 4 times each, once a day, for four consecutive synergistic cycles, for a total of 24 times. The main acupuncture points are Guanyuan (Ren Mai 4), Shangyintang (EX-HN3), Taiyang (EX-HN5), Taichong (Liv-3), Zusanli (ST-36), and Xin (CO-15).",
              "armGroupLabels": [
                "Acupuncture"
              ]
            },
            {
              "type": "DEVICE",
              "name": "Sham Comparator",
              "description": "Both groups have a standard anti-tumor Western medical treatment regimen (PD-1/PD-L1 inhibitor combined with chemotherapy); the sham acupuncture group is combined with sham acupuncture treatment. The day of starting antitumor treatment for each cycle was D1; D1-D5 was performed by the investigator on the patient for 2 times of sham acupuncture treatment, once a day; D8-D13 and D15-D20 were operated by patients or family members, and the investigator remotely assisted via video to complete the sham press needle treatment 4 times each, once a day, for four consecutive synergistic cycles, for a total of 24 times. The main acupuncture points are Guanyuan (Ren Mai 4), Shangyintang (EX-HN3), Taiyang (EX-HN5), Taichong (Liv-3), Zusanli (ST-36), and Xin (CO-15).",
              "armGroupLabels": [
                "sham acupuncture"
              ],
              "otherNames": [
                "sham acupuncture"
              ]
            }
          ]
        },
