        "sponsorCollaboratorsModule": {
          "responsibleParty": {
            "type": "PRINCIPAL_INVESTIGATOR",
            "investigatorFullName": "BO CHEN",
            "investigatorTitle": "Associate Professor",
            "investigatorAffiliation": "Cancer Institute and Hospital, Chinese Academy of Medical Sciences"
          },
          "leadSponsor": {
