          "briefTitle": "Hyperbaric Oxygen in the Prevention of Radiation Pneumonitis",
          "officialTitle": "Study on the Effectiveness and Safety of Hyperbaric Oxygen Therapy for Preventing Radiation Pneumonitis Caused by Radiotherapy and Chemotherapy of Breast Cancer"
        },
        "statusModule": {
          "statusVerifiedDate": "2025-02",
