          "briefTitle": "A Study to Evaluate the Efficacy and Safety of Clear Skin Formula on Mitigating Mild to Moderate Non-cystic Acne",
          "officialTitle": "A 12-week, Randomized, Double-blind, Placebo Controlled Study Evaluating the Efficacy and Safety of Clear Skin Formula on Mitigating Mild to Moderate Non-cystic Acne in Young Healthy Adults"
        },
        "statusModule": {
          "statusVerifiedDate": "2023-05",
          "overallStatus": "COMPLETED",
          "expandedAccessInfo": {
            "hasExpandedAccess": false
          },
          "startDateStruct": {
