        "sponsorCollaboratorsModule": {
          "responsibleParty": {
            "type": "PRINCIPAL_INVESTIGATOR",
            "investigatorFullName": "Martha Shrubsole",
            "investigatorTitle": "Research rofessor",
            "investigatorAffiliation": "Vanderbilt University Medical Center"
