        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Comparisons of the Changes of Blood 25-Hydroxyvitamin D3 (25(OH)D3) Between Magnesium Treatment and Placebo Arm, Stratified by the Baseline 25-hydroxyvitamin D (25(OH)D) Levels",
              "description": "25(OH)D3 was extracted from plasma by liquid extraction and measured by using a novel liquid chromatography-mass spectrometry (LC-MS) method.\n\nThe baseline 25(OH)D were measured by: the baseline value of 25(OH)D2 + the baseline value of 25(OH)D3.\n\nThe changes of 25(OH)D3 were measured as: the post-treatment value of 25(OH)D3 (at Week 12) - the pre-treatment value of 25(OH)D3 (at baseline).",
              "timeFrame": "12 weeks"
            },
            {
              "measure": "Comparisons of the Changes of Blood 25-Hydroxyvitamin D2 (25(OH)D2) Between Magnesium Treatment and Placebo Arm, Stratified by the Baseline 25-hydroxyvitamin D (25(OH)D) Levels",
              "description": "25(OH)D2 was extracted from plasma by liquid extraction and measured by using a novel liquid chromatography-mass spectrometry (LC-MS) method.\n\nThe baseline 25(OH)D were measured by: the baseline value of 25(OH)D2 + the baseline value of 25(OH)D3.\n\nThe changes of 25(OH)D2 were measured as: the post-treatment value of 25(OH)D2 (at Week 12) - the pre-treatment value of 25(OH)D2 (at baseline).",
              "timeFrame": "12 weeks"
            },
            {
              "measure": "Comparisons of the Changes of Blood 24,25-dihydroxyvitamin D3 (24,25(OH)2D3) Between Magnesium Treatment and Placebo Arm, Stratified by the Baseline 25-hydroxyvitamin D (25(OH)D) Levels",
              "description": "24,25(OH)2D3 was extracted from plasma by liquid extraction and detected by using a novel liquid chromatography-mass spectrometry (LC-MS) method.\n\nThe baseline 25(OH)D were measured by: the baseline value of 25(OH)D2 + the baseline value of 25(OH)D3.\n\nThe changes of 24,25(OH)2D3 were measured as: the post-treatment value of 24,25(OH)2D3 (at Week 12) - the pre-treatment value of 24,25(OH)2D3 (at baseline).",
              "timeFrame": "12 weeks"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n1. Participants from our parent study (Personalized Prevention of Colorectal Cancer Trial, NCT#01105169, IRB#100106);\n2. Participants who had completed the above study before the time of the sample selection (October 2015);\n3. Participants consent to store/share samples for future research in colorectal tumors.\n\nExclusion Criteria:\n\n1\\. Participants cannot provide their blood samples in the parent study.",
          "healthyVolunteers": true,
          "sex": "ALL",
          "minimumAge": "40 Years",
