        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "TRPM7 Expression Level in Colorectal Mucosa by Mg Treatment Compared With Placebo",
              "description": "Transient Receptor Potential Melastatin 7 (TRPM7) levels were evaluated quantitatively using a computer-based imaging system composed of an Olympus BX40 Microscope and BioQuant NOVA Prime imaging software (BioQuant). The staining score was computed as \"positive cell percentage x reciprocal staining intensity (RSI)\", yielding values from 0 to 255, where higher score denoted stronger staining. .\n\nChanges (posttreatment-baseline) of TRPM7=log(value at 12 weeks) minus log(value at baseline).",
              "timeFrame": "Baseline to 12 weeks"
            },
            {
              "measure": "COX2 Expression Level in Colorectal Mucosa by Mg Treatment Compared With Placebo",
              "description": "Cyclooxygenase (COX2) levels were evaluated quantitatively using a computer-based imaging system composed of an Olympus BX40 Microscope and BioQuant NOVA Prime imaging software (BioQuant). The staining score was computed as \"positive cell percentage x reciprocal staining intensity (RSI)\", yielding values from 0 to 255, where higher score denoted stronger staining. .\n\nChanges (posttreatment-baseline) of COX2=log(value at 12 weeks) minus log(value at baseline).",
              "timeFrame": "Baseline to 12 week"
            },
            {
              "measure": "TUNEL Expression in Colorectal Mucosa by Mg Treatment Compared With Placebo",
              "description": "Terminal Deoxynucleotidyl Transferase dUTP Nick End Labeling (TUNEL) levels were evaluated quantitatively using a computer-based imaging system composed of an Olympus BX40 Microscope and BioQuant NOVA Prime imaging software (BioQuant) and computed as count of apoptotic cells/mm2 of epithelial cell nuclei area (cells/mm²).\n\nChanges (posttreatment-baseline) of TUNEL =log(value at 12 weeks) minus log(value at baseline).",
              "timeFrame": "Baseline to 12 week"
            },
            {
              "measure": "BAX Expression in Colorectal Mucosa by Mg Treatment Compared With Placebo",
              "description": "BCL2-associated X (BAX) levels were evaluated quantitatively using a computer-based imaging system composed of an Olympus BX40 Microscope and BioQuant NOVA Prime imaging software (BioQuant). The staining score was computed as \"positive cell percentage x reciprocal staining intensity (RSI)\", yielding values from 0 to 255, where higher score denoted stronger staining.\n\nChanges (posttreatment-baseline) of BAX=log(value at 12 weeks) minus log(value at baseline).",
              "timeFrame": "Baseline to 12 week"
            },
            {
              "measure": "pMLKL Expression in Colorectal Mucosa by Mg Treatment Compared With Placebo",
              "description": "Phosphorylated Mixed Lineage Kinase Like (pMLKL) levels were evaluated quantitatively using a computer-based imaging system composed of an Olympus BX40 Microscope and BioQuant NOVA Prime imaging software (BioQuant). The staining score was computed as \"positive cell percentage x reciprocal staining intensity (RSI)\", yielding values from 0 to 255, where higher score denoted stronger staining.\n\nChanges (posttreatment-baseline) of pMLKL=log(value at 12 weeks) minus log(value at baseline).",
              "timeFrame": "Baseline to 12 week"
            },
            {
              "measure": "Ki67 Expression in Colorectal Mucosa by Mg Treatment Compared With Placebo",
              "description": "Ki67 levels were evaluated quantitatively using a computer-based imaging system composed of an Olympus BX40 Microscope and BioQuant NOVA Prime imaging software (BioQuant) and calculated as positive nuclei area / epithelial cell nuclei area \\* 100 (%).\n\nChanges (posttreatment-baseline) of Ki67=log(value at 12 weeks) minus log(value at baseline).",
              "timeFrame": "Baseline to 12 week"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Serum Magnesium by Mg Treatment Compared With Placebo",
              "description": "Changes (posttreatment-baseline) of serum magnesium (measured continuously using 7D70 Magnesium Reagent Kit from Abbot Laboratories (Abbott Park, IL) )",
              "timeFrame": "Baseline to 12 week"
            },
            {
              "measure": "Post Treatment Body Magnesium Status by Mg Treatment and Placebo",
              "description": "Post treatment body magnesium status obtained using magnesium tolerance test (MTT)\n\nMg retention rate (%)=\\[1-(post-infusion Mg excretion - pre-infusion Mg excretion) / total Mg infused\\]\\*100.",
              "timeFrame": "At week 12"
            },
            {
              "measure": "Serum C-reactive Protein (CRP) by Mg Treatment Compared With Placebo",
              "description": "Changes (posttreatment-baseline) of CRP (measured continuously using turbidimetric immunoassay (Pointe Scientific, Inc, Canton, MI)",
              "timeFrame": "Baseline to 12 week"
            },
            {
              "measure": "Urine Prostaglandin E2 Metabolite (PGE-M) by Mg Treatment Compared With Placebo",
              "description": "Changes (posttreatment-baseline) of PGE-M (measured continuously using a liquid chromatography/tandem mass spectrometric method).",
              "timeFrame": "Baseline to 12 week"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Hyperplastic polyp or/and Adenoma cases\n* Polyps free participants with any of the following high risk of colorectal polyps or cancer: (1) family history of colorectal cancer or polyps; (2) current cigarette smoker; (3) obesity (BMI≥30 kg/m2); (4) low intake of fiber (lowest fiber intake quartile: daily intake \\<16.6g); (5) high intake of red meat and well-done or processed meat (mutageneity index ≥5852).\n* Participants from the TCPS (IRB # 090235), the TIARS (IRB # 090235), from Vanderbilt University Hospital or from other resources\n* Consent to be contacted for future studies in TCPS (IRB # 020462), TIARS (IRB#090235)\n* Participants with a calcium intake ≥ 700 mg/day measuring with 24 hour dietary recalls\n* Participants with a calcium intake \\< 2000 mg/day measuring with 24 hour dietary recalls\n* Participants with a calcium/magnesium intake ratio \\> 2.6\n* Participants with known genotype for Thr1482Ile polymorphism in TRPM7\n* Will live in Nashville or surrounding area in the next 6 months\n\nExclusion Criteria:\n\n* Intolerance to magnesium glycinate or microcrystalline cellulose (placebo)\n* Chronic renal diseases and hepatic cirrhosis\n* Chronic ischemic heart disease with unstable angina, chronic heart failure at class III or IV and acute myocardial infarction in the last 6 months\n* Chronic diarrhea\n* Current breastfeeding\n* Current or planned pregnancy\n* Type I diabetes mellitus\n* Pituitary dwarfism\n* Use of digoxin and licorice\n* Current use of blood anticoagulant drugs such as Dicumarol(Warfarin), Clopidogrel (Plavix), Prasugrel HCl (Efficent), Ticlopidine (Ticlid), Lovenox (Enoxaparin), Fragmin (Dalteparin), Innohep (Tinzaparin), Eptifibatide (Integrilin), Tyrofiban (Aggrastat), and Abciximab (Reopro)\n* Current use of lithium carbonate therapy (Eskalith, Lithobid, Lithonate, Lithotabs, Apo-Lithium carbonate, Apo-Lithium carbonate SR, Carbolth, Duralith, PMS-Lithium carbonate, PMS-Lithium citrate)\n* Individuals with a history of colon resection or colectomy due to any reason\n* Individuals with any history of cancer other than non-melanoma skin cancer\n* Individual with history of any organ transplantation\n* Individual with a history of gastric bypass due to any reason\n* Individuals with Inflammatory bowel disease\n* Individuals if creatinine clearance is \\< 50\n* Currently institutionalized\n* Homeless individual (address, telephone etc.)\n* Unable to provide informed consent\n* Any condition that in the opinion of the investigator raises concerns about protocol compliance",
          "healthyVolunteers": true,
          "sex": "ALL",
          "minimumAge": "40 Years",
          "maximumAge": "85 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ]
        },
