      "resultsSection": {
        "participantFlowModule": {
          "recruitmentDetails": "Participants, aged 40-85 y, with colorectal polyp or polyp-free individuals with high risk of colorectal cancer and had a calcium intake of ≥700 and \\<2000 mg/d, and their calcium-to-magnesium intake ratio was \\>2.6 (based on baseline two 24-hour dietary recalls) were recruited from Vanderbilt Vanderbilt University Medical Center (VUMC), Nashville, Tennessee from 2011 to 2024.",
          "groups": [
            {
              "id": "FG000",
              "title": "GG Participants in Magnesium Treatment",
              "description": "Participants with GG genotype were assigned to magnesium glycinate.\n\nOral administration of magnesium glycinate daily for 12 weeks. The dose is personalized based on the baseline assessment of dietary intakes."
            },
            {
              "id": "FG001",
              "title": "GG Participants in Placebo",
              "description": "Participants with GG genotype were assigned to placebo group\n\nOral administration of identical-appearing placebo daily for 12 weeks."
