            },
            {
              "measure": "CK",
              "description": "Creatine kinase is an enzyme that's responsible for healthy muscle function. When muscles break down, they release CK, elevating the protein levels in your blood.",
              "timeFrame": "Every 30 days, begining the first day physical activity, during the three monts of intervention."
            },
            {
              "measure": "LDH",
              "description": "LDH is an enzyme found in many body tissues such as the heart, liver, kidney, skeletal muscle, brain, blood cells, and lungs. When body tissue is damaged, LDH is released into the blood.",
              "timeFrame": "Every 30 days, begining the first day physical activity, during the three monts of intervention."
            },
            {
              "measure": "Urea",
              "description": "Urea and creatinine levels are used to evaluate kidney function.",
              "timeFrame": "Every 30 days, begining the first day physical activity, during the three monts of intervention."
            },
            {
              "measure": "SOD",
              "description": "Superoxide dismutase (SOD) is an enzyme found in all living cells. An enzyme is a substance that speeds up certain chemical reactions in the body. Superoxide dismutase helps break down potentially harmful oxygen molecules in cells.",
              "timeFrame": "Every 30 days, begining the first day physical activity, during the three monts of intervention."
            }
          ]
