        "designModule": {
          "studyType": "INTERVENTIONAL",
          "phases": [
            "NA"
          ],
          "designInfo": {
            "allocation": "RANDOMIZED",
            "interventionModel": "PARALLEL",
            "interventionModelDescription": "This study is a three-arm randomized controlled trial with a parallel-group design. Participants will be randomly allocated to one out of three groups: an aerobic exercise active break, a strength-based active break, or a non exercise group (control condition). Outcomes will be assessed at 3 time points (baseline, post-cognitive fatigue, and post-intervention) to evaluate the acute effects of the intervention.",
            "primaryPurpose": "TREATMENT",
            "maskingInfo": {
              "masking": "DOUBLE",
              "maskingDescription": "Researchers responsible for outcomes assessment, data processing, and statistical analyses will remain blinded throughout the study",
              "whoMasked": [
                "INVESTIGATOR",
                "OUTCOMES_ASSESSOR"
              ]
            }
          },
          "enrollmentInfo": {
            "count": 114,
            "type": "ESTIMATED"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Rest Break",
              "type": "NO_INTERVENTION",
              "description": "Participants in the control group will remain seated while watching a silent video with low cognitive load and without verbal interaction for 10 min."
            },
            {
              "label": "Strength Active Break",
              "type": "EXPERIMENTAL",
              "description": "Participants assigned to the exercise strength group will perform a vigorous-intensity neuromuscular protocol based on a Tabata structure (20 s work / 10 s rest). The session includes two blocks of four exercises targeting upper body, lower body, and core musculature in alternating sequences designed to ensure balanced neuromuscular stimulation while limiting localized fatigue",
              "interventionNames": [
                "Other: Active Break"
              ]
            },
            {
              "label": "Aerobic Active Break",
              "type": "EXPERIMENTAL",
              "description": "Participants assigned to the aerobic exercise group will perform continuous cardiovascular exercises at moderate intensity. The main phase will consist of two exercise blocks repeated twice, including four aerobic movements performed for 30 s. Exercise sequencing alternates upper- and lower-body movements to promote whole-body involvement and progressive cardiovascular demand. Within each block, the first minute was performed at a low-to-moderate intensity, whereas the second minute was performed at a slightly higher intensity. This intensity pattern was maintained consistently across block repetitions.",
              "interventionNames": [
                "Other: Active Break"
              ]
            }
          ],
          "interventions": [
            {
              "type": "OTHER",
              "name": "Active Break",
              "description": "A 10-min active break format was selected to maximize feasibility within school settings. All conditions followed an identical temporal structure consisting of a 1-min warm-up, an 8-min main activity phase, and a 1-min cool-down delivered through standardized instructional videos that guided students in reproducing and observing the correct technique and execution of the exercises.",
              "armGroupLabels": [
                "Aerobic Active Break",
                "Strength Active Break"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Self-perceived emotional state",
              "description": "Assessed using a paper-based measure following the Russell's circumplex model of affect, which conceptualizes emotions according to two primary dimensions: activation level (0 = low to 10 = high) and well-being or happiness level (0 = low to 10 = high).",
              "timeFrame": "Example assessment timeline: baseline assessment (9:00 a.m.); pre-intervention assessment (following cognitively demanding tasks; 10:00 a.m.); and post-intervention assessment (immediately after the active break protocol; 10:25 a.m.)."
            },
            {
              "measure": "Executive Function",
              "description": "The Eriksen Flanker Task and forward and backward digit span tests will be administered online and in paper format, respectively.",
              "timeFrame": "Example assessment timeline: baseline assessment (9:00 a.m.); pre-intervention assessment (following cognitively demanding tasks; 10:00 a.m.); and post-intervention assessment (immediately after the active break protocol; 10:25 a.m.)."
            },
            {
              "measure": "Creativity",
              "description": "Guilford's divergent thinking test will be administered in paper format.",
              "timeFrame": "Example assessment timeline: baseline assessment (9:00 a.m.); pre-intervention assessment (following cognitively demanding tasks; 10:00 a.m.); and post-intervention assessment (immediately after the active break protocol; 10:25 a.m.)."
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Socioeconomic status",
              "description": "Socioeconomic status will be assessed using the Family Affluence Scale III (FAS III), a self-reported questionnaire with higher scores indicating higher family affluence.",
              "timeFrame": "Measured once (one-week before the intervention)"
            },
            {
              "measure": "Sleep Pattern",
              "description": "Sleep quality will be assessed using the Pittsburgh Sleep Quality Index (PSQI), a self-reported questionnaire with a global score ranging from 0 to 21, where higher scores indicate poorer sleep quality.",
              "timeFrame": "Measured once (one-week before the intervention)"
            },
            {
              "measure": "Self-reported Physical Fitness",
              "description": "Self-reported physical fitness will be assessed using the International Fitness Scale (IFIS), which evaluates overall fitness, cardiorespiratory fitness, muscular strength, speed-agility, and flexibility using a 5-point Likert scale (1 = very poor to 5 = very good), where higher scores indicate better perceived physical fitness.",
              "timeFrame": "Measured once (one-week before the intervention)"
            },
            {
              "measure": "Diet Pattern",
              "description": "Adherence to the Mediterranean diet will be assessed using the Mediterranean Diet Quality Index for children and adolescents (KIDMED), with scores ranging from -4 to 12, where higher scores indicate better adherence to the Mediterranean diet.",
              "timeFrame": "Measured once (one-week before the intervention)"
            },
            {
              "measure": "Physical Activity Enjoyment",
              "description": "Enjoyment of physical activity will be assessed using the Physical Activity Enjoyment Scale (PACES), consisting of 16 items rated on a 5-point Likert scale (1 to 5), with total scores ranging from 16 to 80, where higher scores indicate greater enjoyment of physical activity.",
              "timeFrame": "Measured once (one-week before the intervention)"
            },
            {
              "measure": "Affective State",
              "description": "Negative affect will be assessed using the Negative Affect subscale of the Positive and Negative Affect Schedule (PANAS), which consists of 10 items rated on a 5-point Likert scale (1 = very slightly or not at all to 5 = extremely), with total scores ranging from 10 to 50, where higher scores indicate greater negative affect.",
              "timeFrame": "Measured once (one-week before the intervention)"
            },
            {
              "measure": "Sedentary Behavior",
              "description": "Sedentary behavior will be assessed using the Children and Adolescents Physical Activity and Sedentary Questionnaire (CAPAS-Q), which estimates daily time spent in sedentary activities. Results are expressed in minutes per day, where higher values indicate greater sedentary behavior.",
              "timeFrame": "Measured once (one-week before the intervention)"
            },
            {
              "measure": "Resting Heart Rate",
              "description": "Resting heart rate will be assessed using a heart rate monitor, expressed in beats per minute (bpm), with lower values indicating better cardiovascular fitness.",
              "timeFrame": "Measured once (one-week before the intervention)"
            },
            {
              "measure": "Systolic Blood Pressure",
              "description": "Systolic blood pressure will be measured using an automated sphygmomanometer and expressed in millimeters of mercury (mmHg).",
              "timeFrame": "Measured once (one-week before the intervention)"
            },
            {
              "measure": "Diastolic Blood Pressure",
              "description": "Diastolic blood pressure will be measured using an automated sphygmomanometer and expressed in millimeters of mercury (mmHg).",
              "timeFrame": "Measured once (one-week before the intervention)"
            },
            {
              "measure": "Daily physical activity",
              "description": "Students will wear an accelerometer (GENEActiv; Activinsights Ltd, Kimbolton, UK) during one week.",
              "timeFrame": "During one week before the intervention procedure."
            },
            {
              "measure": "Handgrip Strength Test",
              "description": "Upper-body muscular strength will be assessed using the handgrip strength test with a dynamometer, expressed in kilograms (kg), where higher values indicate greater muscular strength.",
              "timeFrame": "Measured once (one-week before the intervention)"
            },
            {
              "measure": "20-m Shuttle Run Test",
              "description": "Cardiorespiratory fitness will be assessed using the 20-m shuttle run test, with performance expressed as the number of completed stages or laps, where higher values indicate better cardiorespiratory fitness.",
              "timeFrame": "Measured once (one-week before the intervention)"
            },
            {
              "measure": "Standing Long Jump Test",
              "description": "Lower-body muscular power will be assessed using the standing long jump test, expressed in centimeters (cm), where greater distances indicate higher muscular power.",
              "timeFrame": "Measured once (one-week before the intervention)"
            },
            {
              "measure": "4x10-m Shuttle Run Test",
              "description": "Speed and agility will be assessed using the 4 × 10-m shuttle run test, with performance expressed in seconds (s), where lower times indicate better performance.",
              "timeFrame": "Measured once (one-week before the intervention)"
            },
            {
              "measure": "Body Weight",
              "description": "Body weight will be measured using electrical bioimpedance (Tanita DC-360 portable S) and expressed in kilograms (kg).",
              "timeFrame": "Measured once (one-week before the intervention)"
            },
            {
              "measure": "Height",
              "description": "Height will be measured using a stadiometer (SECA 213) and expressed in centimeters (cm).",
              "timeFrame": "Measured once (one-week before the intervention)"
            },
            {
              "measure": "Body Mass Index (BMI)",
              "description": "Body mass index (BMI) will be calculated from weight and height measurements and expressed in kilograms per square meter (kg/m²).",
              "timeFrame": "Measured once (one-week before the intervention)"
            },
            {
              "measure": "Body Fat Percentage",
              "description": "Body fat percentage will be assessed using electrical bioimpedance (Tanita DC-360 portable S) and expressed as a percentage (%), where higher values indicate higher adiposity.",
              "timeFrame": "Measured once (one-week before the intervention)"
            }
          ],
          "otherOutcomes": [
            {
              "measure": "Heart Rate",
              "description": "Monitored second-by-second during all three conditions using a Polar H10 monitor, which includes a chest strap.",
              "timeFrame": "During the experimental condition, which will last 10 minutes."
            },
            {
              "measure": "Rating of Perceived Exertion",
              "description": "Perceived exertion will be assessed using a child-adapted Rating of Perceived Exertion (RPE) scale ranging from 0 to 10, where 0 indicates no exertion and 10 indicates maximal exertion, with higher scores reflecting greater perceived effort.",
              "timeFrame": "During the experimental condition, which will last 10 minutes."
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Students enrolled in the 5th and 6th grades of primary education in the city of Castellón, with continuous academic progression and no history of grade retention.\n* Students without diagnosed physical, neurological, or cognitive disorders.\n\nExclusion Criteria:\n\n* Students with a history of grade retention.\n* Students with diagnosed learning difficulties or neurodevelopmental disorders.\n* Students presenting any medical or psychiatric disease.\n* Students undergoing chronic pharmacological treatment.",
