          },
          "briefTitle": "Effects of an Exercise Program in Patients With Hypertensive Chronic Kidney Disease",
          "officialTitle": "Effects of an Exercise Program in Patients With Hypertensive Chronic Kidney Disease: a Randomized Clinical Trial"
        },
        "statusModule": {
          "statusVerifiedDate": "2012-03",
          "overallStatus": "UNKNOWN",
          "lastKnownStatus": "ENROLLING_BY_INVITATION",
          "expandedAccessInfo": {
            "hasExpandedAccess": false
