            {
              "label": "Lifestyle interventions",
              "type": "EXPERIMENTAL",
              "description": "After recruitment of the participants and consented to participate those deemed eligible for inclusion completed baseline surveys will be randomly assigned to an intervention group and another control group that will receive the usual care",
              "interventionNames": [
                "Behavioral: exercise aerobic"
              ]
            },
            {
              "label": "lifestyle interventions",
              "type": "PLACEBO_COMPARATOR",
              "description": "After recruitment of the participants and consented to participate those deemed eligible for inclusion completed baseline surveys will be randomly assigned to an intervention group and another control group that will receive the usual care",
              "interventionNames": [
                "Behavioral: exercise aerobic"
              ]
            }
          ],
          "interventions": [
            {
              "type": "BEHAVIORAL",
              "name": "exercise aerobic",
              "description": "The intervention will consist of physical exercise sessions for approximately 60 minutes and two weekly sessions. The classes will consist of an initial part to exercises heating joint flexibility and lasting 10 minutes, a major part consists of aerobic exercise, lasting 20-30 minutes, and a piece of muscular endurance with exercises upper and lower limbs and abdomen, lasting 10-20 minutes. The intensity will be controlled through the Subjective Perception Scale Borg",
              "armGroupLabels": [
                "Lifestyle interventions",
                "lifestyle interventions"
              ],
              "otherNames": [
                "aerobic exercise",
                "exercício físico"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Progression of renal disease",
              "description": "randomized clinicals trials efficacy exercise in patients with chronic renal disease",
              "timeFrame": "30 th weeks"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "quality of life",
              "description": "assessing quality of life in patients with chronic kidney disease receiving conservative treatment: a randomized clinical trial",
              "timeFrame": "30th weeks"
            },
            {
              "measure": "efficacy of physical exercise on blood pressure",
              "description": "same, patients pré-dialysis, randomized clinical trial",
              "timeFrame": "30 weeks"
            },
            {
              "measure": "Effects of exercise on endothelial progenitor cells in pre-dialysis patients",
              "description": "same, endothelial progenitor cells in whole blood using flow cytometry (number)in pre-dialysis patients: randomized clinical trial",
              "timeFrame": "30 weeks"
            },
            {
              "measure": "Ankle Brachial Pressure Index",
              "description": "same, association of Chronic Kidney Disease With the Spectrum of Ankle Brachial Index in patients pré-dialysis, randomized clinical trial",
              "timeFrame": "30 weeks"
            },
            {
              "measure": "blood lipids",
              "description": "same, in patients pré-dialysis, randomized clinical tria",
              "timeFrame": "30 weeks"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Individuals who have hypertension diagnosed with Glomerular Filtration Rate from 15 to 59 ml/min./1.73m2 characterized, therefore, in stages 3 or 4 chronic kidney disease enrolled in Basic Health Units (BHU) in the urban area of Pelotas , RS.\n\nExclusion Criteria:\n\n* Ia) Subjects diagnosed with diabetes mellitus; b) Patients with severe physical disability (lower limb amputation without prosthesis, orthopedic diseases that worsen with exercise); c) Individuals who have had acute myocardial infarction in the last six months; d) Subjects with hypertension at rest uncontrolled (systolic\\> 180 mmHg and / or diastolic pressure\\> 110 mmHg); e) Patients with angina at rest (unstable) or triggered by exercise; f) Individuals with congestive heart failure (\\> class II New York Heart Association; Table X); g) Patients with cardiac arrhythmias (\\> Lown class II,\\> 30 premature beats per minute); h) Individuals with peripheral vascular disease or moderate to severe; i) Subjects with prior renal transplant or dialysis.",
