          }
        },
        "sponsorCollaboratorsModule": {
          "responsibleParty": {
            "type": "PRINCIPAL_INVESTIGATOR",
            "investigatorFullName": "Robert Buchanan",
            "investigatorTitle": "Chief, Maryland Psychiatric Research Center, Outpatient Research Program",
            "investigatorAffiliation": "University of Maryland, Baltimore"
          },
          "leadSponsor": {
            "name": "University of Maryland, Baltimore",
