        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Group commitment contracts",
              "type": "EXPERIMENTAL",
              "description": "In addition to education and counseling, the intervention includes the following components:\n\n1. Each participant is encouraged to deposit his \"cigarette money\" on a weekly basis, to be returned only if the smoker quits successfully within three months.\n2. The project gives a series of two matching contributions of 150 baht each to participants who meet certain deposit requirements.\n3. Each participant is paired with another study participant. If both quit, each receives a cash bonus of 1,200 baht. At enrollment, pairs receive brief counseling on ways to support each other during the quit attempt.",
              "interventionNames": [
                "Behavioral: Group commitment contract",
                "Behavioral: Smoking cessation education and counseling"
              ]
            },
            {
              "label": "Education and counseling",
              "type": "ACTIVE_COMPARATOR",
              "description": "Participants in this group receive educational pamphlets about quitting smoking and one-time, group counseling from a nurse trained in smoking cessation counseling.",
              "interventionNames": [
                "Behavioral: Smoking cessation education and counseling"
              ]
            }
          ],
          "interventions": [
            {
              "type": "BEHAVIORAL",
              "name": "Group commitment contract",
              "description": "1. Each participant is required to deposit at least 50 baht at enrollment. A deposit collector visits each participant on a weekly basis and collects additional deposits on a voluntary basis. All deposits are returned only if the smoker quits successfully within three months.\n2. The project gives a matching contribution of 150 baht for the initial deposit of at least 50 baht. All participants in the treatment group are further randomized to a one-month group and a three-month group. The one-month group receives an additional 150 baht of project funds if they deposit 100 baht of their money within one month of enrollment. The three-month group receives 150 baht for depositing 100 baht within three months of enrollment.\n3. Each participant is paired with another study participant. If both quit, each receives a cash bonus of 1,200 baht. At enrollment, pairs receive brief counseling on ways to support each other during the quit attempt.",
              "armGroupLabels": [
                "Group commitment contracts"
              ],
              "otherNames": [
                "Commitment contract",
                "Deposit contract",
                "Contingency contract",
                "Buddy intervention",
                "Partner intervention"
              ]
            },
            {
              "type": "BEHAVIORAL",
              "name": "Smoking cessation education and counseling",
              "description": "Participants receive educational pamphlets on reasons to quit smoking and strategies for quitting smoking. They also receive one-time, group counseling on quitting smoking from a nurse trained in smoking cessation counseling.",
              "armGroupLabels": [
                "Education and counseling",
                "Group commitment contracts"
              ],
              "otherNames": [
                "Smoking cessation counseling"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Smoking Status at 6 Months",
              "description": "7-day point prevalence of smoking abstinence measured 6 months after enrollment, using a NicCheck urine cotinine test. Participants who self-report having smoked in the last 7 days, as part of the follow-up survey, are considered to be continuing smokers.",
              "timeFrame": "6 months after enrollment"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Concordance of Smoking Status Between Partners at 6 Months",
              "description": "The concordance of smoking status among randomly assigned pairs: both abstain, both smoke, or one abstains and one smokes, measured using 7-day point-prevalence abstinence at 6 months after enrollment, measured using self-reported abstinence and urine cotinine testing. Participants in the control condition are assigned to a pair, but their partner's identity is never revealed during the study.",
              "timeFrame": "6 months after enrollment"
            },
            {
              "measure": "Smoking Status at 3 Months",
              "description": "7-day point prevalence of smoking abstinence measured 3 months after enrollment, using a NicCheck urine cotinine test. Participants who self-report having smoked in the last 7 days, as part of the follow-up survey, are considered to be continuing smokers.",
              "timeFrame": "3 months after enrollment"
            },
            {
              "measure": "Concordance of Smoking Status Between Partners at 3 Months",
              "description": "The concordance of smoking status among randomly assigned pairs: both abstain, both smoke, or one abstains and one smokes, measured using 7-day point-prevalence abstinence at 3 months after enrollment, measured using self-reported abstinence and urine cotinine testing. Participants in the control condition are assigned to a pair, but their partner's identity is never revealed during the study.",
              "timeFrame": "3 months after enrollment"
            },
            {
              "measure": "Smoking Status at 14 Months",
              "description": "7-day point prevalence of smoking abstinence measured 6 months after enrollment, using a NicCheck urine cotinine test. Participants who self-report having smoked in the last 7 days, as part of the follow-up survey, are considered to be continuing smokers.",
              "timeFrame": "14 months after enrollment"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Current smoker of at least 10 cigarettes per week and at least 100 cigarettes over the course of a lifetime\n* Residents of the study area in Nakhon Nayok province, which includes the six subdistricts of Klong Yai, Chumpon, Bueng San, Pak Phli, Khao Phoem, or Ongkharak\n\nExclusion Criteria:\n\n* Pregnant\n* Plans to leave the study area within the next 12 months",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "20 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ]
        },
