        "oversightModule": {
          "isFdaRegulatedDrug": false,
          "isFdaRegulatedDevice": false
        },
        "descriptionModule": {
          "briefSummary": "The aim of present study was to evaluate how the 2018 classification reflects the severity, extent and progression of the disease, taking into account the risk factors for periodontal disease, smoking and diabetes, when compared with the 1999 classification."
        },
        "conditionsModule": {
          "conditions": [
            "Diabetes Mellitus",
            "Smoking",
            "Periodontal Diseases"
          ]
        },
        "designModule": {
          "studyType": "OBSERVATIONAL",
          "patientRegistry": false,
          "designInfo": {
            "observationalModel": "ECOLOGIC_OR_COMMUNITY",
            "timePerspective": "RETROSPECTIVE"
          },
          "enrollmentInfo": {
            "count": 202,
            "type": "ACTUAL"
          }
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "The advantages of including the effect of diabetes and smoking on periodontal disease in the 2018 classification compared to the 1999 classification",
              "description": "In our study, both classifications reflected the severity of periodontal disease differently. The 2018 classification outperformed the 1999 classification for staging and grading of periodontitis severity and progression. Consideration of the risk factors listed in the 2018 classification has been useful approach for correct diagnosis, evidence-based clinical decisions, prognosis of treatment, and periodontal disease prevention. The 2018 periodontal disease classification is more detailed and comprehensive than the 1999 classification, and this classification is thought to revise the criticisms of the 1999 classification.",
              "timeFrame": "The present retrospective study included individuals who were examined and had periodontal measurements made and recorded at the Istanbul Okan University Periodontology Department between 09/01/2018 and 12/01/2019."
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Patients with a complete periodontal chart and full mouth radiographic series at baseline\n* Diabetes Mellitus:Patients who consulted by an internist/endocrinologist and underwent HbA1c measurements in the last three months.\n* Smoking status:All current smokers who had smoked more than 100 cigarettes in their lifetimes and used cigarettes for more than five years\n* Patients meeting the case definition of periodontitis\n* Relative radiographic bone loss(in %) was assessed on peri-apical radiograph films\n\nExclusion Criteria:\n\n* individuals with a systemic disease other than diabetes\n* Smokers not reporting the number of cigarette/days or patient(s) with diabetes that do not report Hemoglobin A1c (HbA1c) test results for diabetes.\n* individuals who do not suffer from periodontitis\n* Patients with inaccessible files because of bad debt, destroyed record, or deceased.",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ],
          "studyPopulation": "The individuals with periodontitis who participated in the study were evaluated in three categories:\n\n* individuals who do not smoke and do not have any illnesses\n* non-smoking individuals with diabetes\n* individuals who smoke and have no systemic disease",
          "samplingMethod": "NON_PROBABILITY_SAMPLE"
