        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Vascular vasomotor function",
              "description": "Forearm venous occlusion plethysmography to measure forearm blood flow during unilateral intrabrachial infusion of endothelial-dependent and -independent vasodilators. Assessment is shown in ml/100ml tissue/min.",
              "timeFrame": "3 hours"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Arterial Stiffness",
