          "briefTitle": "Enhanced Smoking Cessation Intervention for Smokers Exposed to the World Trade Center (WTC) Disaster",
          "officialTitle": "Enhanced Smoking Cessation Intervention for Smokers Exposed to the WTC Disaster"
        },
        "statusModule": {
          "statusVerifiedDate": "2015-09",
          "overallStatus": "COMPLETED",
