        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "CBT-A",
              "type": "EXPERIMENTAL",
              "description": "An 8-session, CBT-based group smoking cessation program (CBT-A) enhanced with transdiagnostic skills for the management of anxiety and fear-based avoidance behaviors.",
              "interventionNames": [
                "Behavioral: CBT-A"
              ]
            },
            {
              "label": "CBT-S",
              "type": "ACTIVE_COMPARATOR",
              "description": "An 8-session, CBT-based, traditional group CBT based smoking cessation program.",
              "interventionNames": [
                "Behavioral: CBT-S"
              ]
            }
          ],
          "interventions": [
            {
              "type": "BEHAVIORAL",
              "name": "CBT-A",
              "description": "CBT-A was an 8-session (1.5 hours/session) group treatment for quitting smoking comprised of an optimized protocol that incorporated all elements of the CBT-S treatment plus skills for reducing PTSD/anxiety symptoms and improving tolerance to withdrawal. The CBT-A intervention included skills based on a transdiagnostic approach: (1) repeated interoceptive exposures to feared bodily sensations (e.g., dizziness, racing heart); (2) corrective information about anxiety and cognitive restructuring of catastrophic misinterpretations of somatic sensations (e.g., \"I will lose control.\"); and (3) use of graduated in-vivo exposure to feared and avoided situational experiences related to anxiety, WTC-related PTSD triggers, and smoking (e.g., going to lower Manhattan; driving without smoking).",
              "armGroupLabels": [
                "CBT-A"
              ]
            },
            {
              "type": "BEHAVIORAL",
              "name": "CBT-S",
              "description": "CBT-S was an adapted group-based CBT smoking cessation treatment delivered in 8 sessions (1.5 hours/session) based on the most recent clinical practice guidelines from the United States Department of Health and Human Services (USDHHS), Treating Tobacco Use and Dependence. Standard cessation elements included psychoeducation on reasons for smoking and barriers to quitting, enlisting social support, monitoring and tapering cigarette use, and counseling regarding high-risk smoking situations and unhelpful ways of thinking about smoking and abstinence. The treatment was similar to protocols used in other smoking cessation research.",
              "armGroupLabels": [
                "CBT-S"
              ]
            }
          ]
        },
