            {
              "label": "Best Practice (BP) Control",
              "type": "ACTIVE_COMPARATOR",
              "description": "Best Practice (BP) Control Condition consists of two 10-15 min, on-site intervention sessions (session 1 and 3), one brochure pick-up (session 2), and receipt of a newsletter by mail (booster session).",
