          "interventions": [
            {
              "type": "DRUG",
              "name": "CBD",
              "description": "Each subject in the study was tested on eight days, each day receiving a different combination of active/inactive cannabis cigarettes plus 0, 200, 400 or 800 mg of CBD in random order. Cigarettes contained either 0.01 or 5.30% THC. At each visit, participants were given four gelatin capsules containing lactose and 0 or 200 mg of CBD in combinations to achieve scheduled dose level.",
              "armGroupLabels": [
                "Active MJ with 200 mg CBD",
                "Active MJ with 400 mg CBD",
                "Active MJ with 800 mg CBD",
                "Active marijuana (MJ) with 0 mg CBD",
                "Inactive MJ with 0 mg CBD",
                "Inactive MJ with 200 mg CBD",
                "Inactive MJ with 400 mg CBD",
                "Inactive MJ with 800 mg CBD"
              ],
              "otherNames": [
                "cannabidiol is abbreviated CBD"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Mood Scale - Subscale 'Feeling High'",
              "description": "Participants rated how much they felt having a \"high\" feeling from smoked marijuana using a visual analog scale 1-100 mm, 1 (Not at all) - 100 (extremely).",
              "timeFrame": "two hours before and after marijuana cigarette smoking"
            }
          ],
          "otherOutcomes": [
            {
              "measure": "Marijuana Rating Form - Like",
              "description": "Participants rated how much they liked the effects of smoked marijuana using a visual analog scale 1-100 mm, 1=least, 100= most",
              "timeFrame": "15 - 120 minutes after marijuana cigarette smoking"
            },
            {
              "measure": "Marijuana Rating Form - Strength",
              "description": "Participants rated the strength effects of smoked marijuana using a visual analog scale 1-100 mm, 1=least, 100= most",
              "timeFrame": "15 - 120 minutes after marijuana cigarette smoking"
            },
            {
              "measure": "Optional Additional Puffs of MJ Cigarette",
              "description": "Participants were allowed to choose to take or reject additional puffs of the same type of MJ cigarette they smoked earlier in the day. Counts of participants choosing to take additional puffs are reported.",
              "timeFrame": "150 to 250 minutes after first marijuana cigarette was smoked earlier in the day"
            },
            {
              "measure": "Number of Optional Puffs of MJ Cigarette Taken",
              "description": "Mean number of puffs taken by those participants who chose to take additional puffs.",
              "timeFrame": "150 to 160 minutes after first marijuana cigarette was smoked earlier in the day"
            },
            {
              "measure": "Heart Rate",
              "description": "Heart rate measured at 10 time points, 4 before and 6 after smoking cannabis.",
              "timeFrame": "120 minutes before and 150 minutes after marijuana cigarette smoking"
            },
            {
              "measure": "Plasma Concentration of CBD",
              "description": "Plasma concentrations of cannabidiol were measured at six time points after oral administration of four 200 mg capsules of CBD.",
              "timeFrame": "6 hours"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Adults between the ages of 18 and 50.\n* Current marijuana use: Minimum of four times per week, 0.5 joints per occasion during the preceding 4 weeks.\n* Able to perform study procedures\n* Women practicing an effective form of birth control\n\nExclusion Criteria:\n\n* Female subjects who are currently pregnant or breastfeeding.\n* Current, repeated illicit drug use other than marijuana\n* Presence of significant medical illness\n* History of heart disease\n* Request for drug treatment\n* Current parole or probation\n* Recent history of significant violent behavior\n* Major psychiatric disorder",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "maximumAge": "50 Years",
          "stdAges": [
            "ADULT"
          ]
        },
