        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Break the Chain",
              "type": "EXPERIMENTAL",
              "description": "Access during the evaluation study period to an Internet smoking cessation intervention that included digital coaching messages sent at prescribed times during the participant's quit process and as needed in response to participant questions or comments.",
              "interventionNames": [
                "Behavioral: Break the Chain"
              ]
            },
            {
              "label": "Clearing the Air PDF",
              "type": "ACTIVE_COMPARATOR",
              "description": "Control users were e-mailed a copy of the National Cancer Institute's PDF smoking cessation booklet, \"Clearing the Air.\"",
              "interventionNames": [
                "Behavioral: Clearing the Air"
              ]
            }
          ],
          "interventions": [
            {
              "type": "BEHAVIORAL",
              "name": "Break the Chain",
              "description": "Internet-based smoking cessation intervention designed for general population smokers with targeted materials for pregnant women. The program included a digital coaching component delivered via email at specific points as the user progresses through his/her quit process. Program content is based on Department of Health and Human Services Clinical Practice Guidelines for Treating Tobacco Use and Dependence.",
              "armGroupLabels": [
                "Break the Chain"
              ]
            },
            {
              "type": "BEHAVIORAL",
              "name": "Clearing the Air",
              "description": "PDF version of smoking cessation booklet from National Cancer Institute.",
              "armGroupLabels": [
                "Clearing the Air PDF"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Change from baseline in number of cigarettes smoked in the last 7 days",
              "description": "Smoking cessation as measured by number of cigarettes smoked in the last 7 days. We will use an intent-to-treat statistical analysis, a conservative approach that classifies all non-responders as smokers.",
              "timeFrame": "10 months"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Change from baseline in knowledge of impact of smoking cessation",
              "description": "Pregnant smokers only: Eight knowledge items assess post-natal impact (e.g., Smoking during pregnancy increases chances of having a child who develops asthma); seven items assess infant impact (e.g., Exposing an infant to smoke in the home increases the chances the baby will wake up at night more than usual); eight items assessed infant health risk (e.g., Babies exposed to secondhand smoke have increased chances of having learning disabilities). Response options were a \"true\" and \"false\" format scored to reflect the proportion of items answered correct in each domain. The seriousness of infant health issues related to smoking was assessed with five items (e.g., A baby born with lower than normal weight - low birth weight baby) with a five-point response option (1=not at all serious, 5=extremely serious). A mean score was computed and it showed good reliability (alpha = .82).",
              "timeFrame": "10 months"
            },
            {
              "measure": "Change from baseline in self-efficacy to quit smoking",
              "description": "Six self-efficacy items (e.g., How confident are you that you could quit and stay quit) were assessed of all smokers. Each item had a five-point response option (1=not at all confident, 5=extremely confident) and showed good reliability (alpha=.86).",
              "timeFrame": "10 months"
            },
            {
              "measure": "Change from baseline in attitudes about smoking cessation",
              "description": "Five attitude items (e.g., Knowing the right way to ask for help from family and friends when I'm quitting is important) were assessed of all smokers. Each item had a five-point response option (1=not at all important, 5=extremely important) and showed adequate reliability (alpha=.77).",
              "timeFrame": "10 months"
            },
            {
              "measure": "Change from baseline in behavioral intentions about smoking cessation",
              "description": "Five intention items (e.g., How likely is it that you will avoid every situation where you will be tempted to smoke) were assessed of all smokers. Each item had a five-point response option (1=not at all likely, 5=extremely likely) and showed adequate reliability (alpha = .79).",
              "timeFrame": "10 months"
            },
            {
              "measure": "Program satisfaction",
              "description": "Seven program satisfaction items were assessed of as rated by the treatment participants at the T2 assessment. Treatment participants were also asked how likely they would be to recommend the program to a friend and/or family member.",
              "timeFrame": "4-week posttest"
            },
            {
              "measure": "User rating of system usability",
              "description": "All treatment participants were asked how much they agreed or disagreed with program usability statements (see Table 3) with response options on a 5- point scale (1 = strongly disagree, 2 = disagree, 3 = neither disagree or agree, 4 = agree 5 = strongly agree). The SUS is a tool designed for assessing the usability of a product and has been normed across numerous platforms (e.g., Web sites, cell phones, TV applications). Scores range from 0 to 100. (SUS; Bangor, Kortum, \\& Miller, 2009)",
              "timeFrame": "4-week posttest"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion criteria for pregnant:\n\n* 18 years or older\n* Between 8 and 32 weeks pregnant\n* Currently smoking, trying to quit, or quit smoking within last 2 months\n* Able to speak and read English\n* Have access to high-speed or DSL Internet and email for the duration of the study.\n\nInclusion criteria for general population participants:\n\n* Male or female not pregnant\n* 18 years or older\n* Currently smoking, trying to quit, or quit smoking within last 2 months\n* Able to speak and read English\n* Have access to high-speed or DSL Internet and email for the duration of the study\n\nExclusion critieria:\n\n* Men and women under age 18 were excluded.\n* Women who were pregnant but whose pregnancy did not fit within the specified time frame were excluded.",
