          "briefTitle": "Efficacy of the Use of Genetic Markers in the Choice of the Pharmacological Treatment of Smoking (GENTSMOKING)",
          "officialTitle": "Efficacy of Genetic Markers in Choosing Pharmacological Treatment for Smoking Cessation With Bupropion and Varenicline and Its Implications for Combining Drugs: Randomized Control Study.",
          "acronym": "GENTSMOKING"
        },
        "statusModule": {
          "statusVerifiedDate": "2022-12",
          "overallStatus": "COMPLETED",
          "expandedAccessInfo": {
            "hasExpandedAccess": false
          },
          "startDateStruct": {
