          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Group Varenicline",
              "type": "NO_INTERVENTION",
              "description": "Patients randomized to this group will collect polymorphisms at time zero and will receive varenicline for smoking cessation. The polymorphism result will only be known at the end of the protocol. Varenicline dosage 0,5 mg once a day for 3 days, after this 0,5 mg twice a day until seven day .At day eight 1 mg twice a day until complete week twelve."
            },
            {
              "label": "Group Genetic",
              "type": "ACTIVE_COMPARATOR",
              "description": "The patients randomized to this arm will collect polymorphisms and could receive varenicline or bupropion or both depending on genetic polymorphisms for each one these drugs.\n\nBupropiona dosage 150 mg once a day seven days, after twice a day until complete week twelve. Varenicline dosage 0,5 mg once a day for 3 days, after this 0,5 mg twice a day until seven day .At day eight 1 mg twice a day until complete week twelve.",
              "interventionNames": [
                "Drug: Varenicline Tartrate or bupropion"
              ]
            }
          ],
          "interventions": [
            {
              "type": "DRUG",
              "name": "Varenicline Tartrate or bupropion",
              "description": "the drug treatment will be chosen related to the polymorphism. If the polymorphism is favorable to varenicline the patient will receive varenicline, If it is favorable to bupropion the patient will receive bupropion, if not favorable to varenicline and bupropion the patient will receive bupropion + varenicline. If the patient has both favorable polymorphisms he will receive bupropion. Bupropiona dosage 150 mg once a day seven days, after twice a day until complete week twelve. Varenicline dosage 0,5 mg once a day for 3 days, after this 0,5 mg twice a day until seven day .At day eight 1 mg twice a day until complete week twelve.",
              "armGroupLabels": [
                "Group Genetic"
              ],
              "otherNames": [
                "Varenicline Tartrate and bupropion"
              ]
            }
          ]
