        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Usual Care",
              "type": "ACTIVE_COMPARATOR",
              "description": "Participants will be offered free smoking cessation programs, and be provided web-based education regarding the health and economic benefits of smoking cessation. Participants will also have the opportunity to submit weekly reports on their smoking habits. They will be informed that they will receive reimbursements for completing the surveys that are part of the Way To Quit program and for submitting saliva or urine samples at 14 days, 30 days, 6 months, and 12 months (among those eligible).",
              "interventionNames": [
                "Behavioral: Usual Care"
              ]
            },
            {
              "label": "Individual Rewards",
              "type": "EXPERIMENTAL",
              "description": "Same as USUAL CARE arm, plus financial incentive as follows: if participants quit smoking by their target quit date, and that is confirmed by cotinine or anabasine tests, they will receive a monetary award from the study investigators.",
              "interventionNames": [
                "Behavioral: Individual Rewards"
              ]
            },
            {
              "label": "Fixed Deposits",
              "type": "EXPERIMENTAL",
              "description": "Same as USUAL CARE arm, plus financial incentive as follows: participants will have to deposit a certain monetary amount of their own money as an incentive to quit smoking. If they quit smoking by their target quit date, and that is confirmed by cotinine or anabasine tests, participants will receive their deposit back. If participants do not quit, their money will be used to support future research studies designed to help people stop smoking. As a motivation to quit smoking, the participant's deposit will be matched by the study investigators in a rate of 3:1.",
              "interventionNames": [
                "Behavioral: Fixed Deposits"
              ]
            },
            {
              "label": "Competitive Deposits (Pari-Mutuel)",
              "type": "EXPERIMENTAL",
              "description": "Same as USUAL CARE, plus financial incentive as follows: groups (or \"cohorts\") of 6 smokers each will be formed on a rolling basis, linking individuals with target quit dates (day \"0's\") near each other. Participants will deposit a certain monetary amount (Y) in an account, which will be matched on a rate of 3:1 by the study investigators (M), and the payout for quitting on this arm will be (Y+M) x 6/Q , where Q is the number of quits in the cohort. Again, success will be confirmed by cotinine or anabasine tests, and if participants do not quit, their money will be used to support future research studies designed to help people stop smoking.",
              "interventionNames": [
                "Behavioral: Competitive Deposits (Pari-Mutuel)"
              ]
            },
            {
              "label": "Collaborative Rewards",
              "type": "EXPERIMENTAL",
              "description": "Same as USUAL CARE arm, plus financial incentive as follows: groups (or \"cohorts\") of 6 smokers each will be formed on a rolling basis, linking individuals with target quit dates (day \"0's\") near each other. If participants quit smoking by their target quit date, and that is confirmed by cotinine or anabasine tests, they will receive a monetary award from the study investigators. On top of that, participants will receive an additional monetary amount for each member of their group who also quits smoking. These participants will interact through a chat room, which will help motivate them to quit smoking.",
              "interventionNames": [
                "Behavioral: Collaborative Rewards"
              ]
            }
          ],
