        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Standard treatment (ST) arm",
              "type": "EXPERIMENTAL",
              "description": "Participants will receive a brief smoking cessation intervention based on the \"5A\" and \"5R\" models proposed by the World Health Organization. The \"STAR\" method as quitting skills will also be provided. The \"5A\" model includes five steps to identify participants who are ready to quit smoking. For those who are ready to quit, a research assistant will assist them to quit using the \"STAR\" method: Set a quit date within 1 week, Tell the surrounding people that they have planned to quit and solicited their support, Anticipate challenges to quit attempt, and Remove all tobacco products. Otherwise, the \"5R\" model will be applied to those not yet ready to quit. After \"5R\" is applied, the research assistant will repeat the assessment of their willingness to quit. The booster interventions will be delivered by the research assistant through follow-ups arranged with the participants via phone.",
              "interventionNames": [
                "Behavioral: Standard treatment (ST) arm"
              ]
            },
            {
              "label": "Integrated Intervention (II) arm",
              "type": "EXPERIMENTAL",
              "description": "In addition to the brief smoking cessation intervention based on the \"5A\" and \"5R\" models, participants in this arm received brief advice on alcohol use based on the \"FRAMES\" model. The booster interventions will be delivered by the research assistant through follow-ups arranged with the participants via phone.",
              "interventionNames": [
                "Behavioral: Integrated Intervention (II) arm"
              ]
            },
            {
              "label": "Control arm",
              "type": "NO_INTERVENTION",
              "description": "Participants will be provided with two leaflets designed by Department of health: one for smoking cessation and another for alcohol abstinence."
            }
          ],
          "interventions": [
            {
              "type": "BEHAVIORAL",
              "name": "Standard treatment (ST) arm",
              "description": "participants who are ready to quit smoking: a brief smoking cessation intervention based on the \"5A\" models and \"STAR\" method as quitting skills.\n\nparticipants who are not yet ready to quit smoking: a brief smoking cessation intervention based on the \"5R\" models.",
              "armGroupLabels": [
                "Standard treatment (ST) arm"
              ]
            },
            {
              "type": "BEHAVIORAL",
              "name": "Integrated Intervention (II) arm",
              "description": "brief advice on alcohol use based on the \"FRAMES\" model and the brief smoking cessation intervention based on the \"5A\" and \"5R\" models.",
              "armGroupLabels": [
                "Integrated Intervention (II) arm"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "screening rate",
              "description": "the number of smokers screened divided by the number of smokers available for screening",
              "timeFrame": "From screening to the end of treatment after 6 months"
            },
            {
              "measure": "eligibility rate",
              "description": "the number of eligible smokers divided by the number of screened people",
              "timeFrame": "From screening to the end of treatment after 6 months"
            },
            {
              "measure": "consent rate",
              "description": "the number of eligible smokers who agree to participate divided by the number of eligible smokers",
              "timeFrame": "From screening to the end of treatment after 6 months"
            },
            {
              "measure": "randomization rate",
              "description": "the number of participants who are randomized divided by the number of eligible smokers who consent to participate",
              "timeFrame": "From screening to the end of treatment after 6 months"
            },
            {
              "measure": "attendance rate",
              "description": "the number of participants who complete the intervention divided by the number of participants who are randomized into the treatment arms (ST and II)",
              "timeFrame": "From screening to the end of treatment after 6 months"
            },
            {
              "measure": "adherence to intervention",
              "description": "the number of participants in the two treatment arms who practice the skills learned during the intervention divided by the number of participants in the two treatment arms",
              "timeFrame": "From screening to the end of treatment after 6 months"
            },
            {
              "measure": "retention rate",
              "description": "the number of participants who remain in the study divided by the number of participants randomized",
              "timeFrame": "From screening to the end of treatment after 6 months"
            },
            {
              "measure": "completion rate",
              "description": "the number of participants who complete the questionnaire divided by the number of questionnaires distributed",
              "timeFrame": "From screening to the end of treatment after 6 months"
            },
            {
              "measure": "missing data",
              "description": "the percentage of missing data",
              "timeFrame": "From screening to the end of treatment after 6 months"
            },
            {
              "measure": "adverse events",
              "description": "unfavorable or unintended events during the study period that were not present at baseline or appear to have worsened since baseline",
              "timeFrame": "From screening to the end of treatment after 6 months"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Smoking quit rate",
              "description": "the effect size of II on self-reported and biochemically validated quit rates for smoking at 6 months relative to ST and Control.",
              "timeFrame": "From screening to the end of treatment after 6 months"
            },
            {
              "measure": "alcohol quit rate",
              "description": "the effect size of II on self-reported quit rate for alcohol at 6 months relative to ST and Control",
              "timeFrame": "From screening to the end of treatment after 6 months"
            }
          ]
        },
        "eligibilityModule": {
