          "briefTitle": "Smoking Cessation Via Text Messaging: Feasibility Testing of Stop My Smoking USA",
          "officialTitle": "Smoking Cessation Via Text Messaging: Feasibility Testing of SMS USA",
          "acronym": "SMS USA"
        },
        "statusModule": {
