          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "SMS USA",
              "type": "EXPERIMENTAL",
              "description": "The 6-week smoking cessation intervention",
              "interventionNames": [
                "Behavioral: SMS USA"
              ]
            },
            {
              "label": "Attention matched control",
              "type": "NO_INTERVENTION",
              "description": "Messages aimed at improving one's sleep and increasing one's fitness, along with general messages about the most well known health dangers of smoking. Messages sent on the same schedule as the intervention group."
            }
          ],
          "interventions": [
            {
              "type": "BEHAVIORAL",
              "name": "SMS USA",
              "description": "Intervention participants receive text messages daily pre-and post-quit. Everyone receives messages 14 days prior to the Quit day, and through the day after Quit. Then, participants are 'pathed' to particular messages based upon their self-reported smoking status at Day 2 and Day 7 post quit, respectively. Those who are successful at quitting receive messages aimed at relapse prevention whereas those who have slipped receive messages aimed at getting the person to recommit to quitting and trying again.",
              "armGroupLabels": [
                "SMS USA"
              ],
              "otherNames": [
                "Stop My Smoking USA"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Continuous Abstinence at 3-months Assessed in Accordance With the NIH Behavior Change Consortium's Recommendations",
              "description": "Continuous abstinence is defined as 5 or fewer cigarettes smoked since one's quit date. The question was asked based upon West et al., 2005: \"Have you smoked at all, even just a puff, since \\[insert quit date\\]?\" If yes, the respondent will be probed for how many cigarettes were smoked. Responses will be categorized into one of three options: A) No, not a puff; B) 1-5 cigarettes; C) More than 5 cigarettes.\n\nSelf-reported cessation is confirmed by a significant other.",
              "timeFrame": "3-months post-quit"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Point Prevalence",
              "description": "A cigarette, even just a puff, within the last 7 days (yes/no).",
              "timeFrame": "4-weeks post-quit"
            },
            {
              "measure": "Continuous Abstinence at 4-weeks Post-quit",
              "description": "Smoking five or fewer cigarettes since quit day at 4 weeks post-quit as verified by a significant other",
              "timeFrame": "4 weeks post-quit"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* 28 cigarettes or more per week (at least 4/day) and on at least 6 days/week.\n* Owning a text-capable cell phone and cognizant of how to send and receive text messages\n* Currently enrolled or intending to enroll in an unlimited text messaging plan\n* Enrolled with a cell phone carrier that was compatible with the program software\n* Agree to verification of smoking cessation status by a significant other\n* Able to read and write in English\n* Informed consent\n\nExclusion Criteria:\n\nNone",
          "healthyVolunteers": true,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "maximumAge": "25 Years",
          "stdAges": [
            "ADULT"
          ]
        },
        "contactsLocationsModule": {
          "overallOfficials": [
            {
              "name": "Michele Ybarra, MPH PhD",
              "affiliation": "Center for Innovative Public Health Research",
              "role": "PRINCIPAL_INVESTIGATOR"
            }
          ],
