        "outcomeMeasuresModule": {
          "outcomeMeasures": [
            {
              "type": "PRIMARY",
              "title": "Annualized Relapse Rate (ARR) at 1 Year",
              "description": "A relapse is defined as new or recurrent neurologic symptoms not associated with fever or infection, lasting for at least 24 hours, and accompanied by new objective neurologic findings. Only relapses confirmed by an independent neurology evaluation committee (INEC) are included in the analysis. Data after participants switched to alternative multiple sclerosis (MS) medications are excluded. Data were analyzed using negative binomial regression, adjusted for baseline Expanded Disability Status Scale (EDSS) score (\\< 4 versus ≥ 4), baseline age (\\< 40 versus ≥ 40 years), and baseline relapse rate (number of relapses in 3 years prior to study entry divided by 3).",
              "populationDescription": "Intent-to-treat (ITT) population: participants who were randomized and received at least 1 dose of study treatment (peginterferon beta-1a or placebo).",
              "reportingStatus": "POSTED",
              "paramType": "NUMBER",
              "dispersionType": "95% Confidence Interval",
              "unitOfMeasure": "relapses per person-years",
              "timeFrame": "1 Year",
