            "type": "ACTUAL"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Participants with Tuberous Sclerosis Complex (TSC)",
              "description": "Üarticipants diagnosed with Tuberous Sclerosis Complex (TSC) aged between 2 months and 50 years."
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Identification of TSC biomarker/s",
              "description": "All samples will be analyzed for the identification of biomarker/s via Liquid Chromatography Multiple Reaction-monitoring Mass Spectrometry (LC/MRM-MS) and compared to merged control, in order to establish the disease-specific biomarker/s. The LC/MRM-MS is performed on an ABSciex 6500 triple quadrupole mass spectrometer, coupled with a Waters Acquity UPLC.",
              "timeFrame": "36 months"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Exploring the clinical robustness, specificity, and longterm variability of TSC biomarker/s",
              "description": "Samples will be analyzed for the candidate biomarker/s via Liquid Chromatography Multiple Reaction-monitoring Mass Spectrometry (LC/MRM-MS) and compared to merged control, in order to establish the disease-specific biomarker/s. The LC/MRM-MS is performed on an ABSciex 6500 triple quadrupole mass spectrometer, coupled with a Waters Acquity UPLC.",
              "timeFrame": "36 months"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "INCLUSION CRITERIA\n\n* Informed consent is obtained from the participant or from the parent / legal guardian\n* Participant is aged between 2 and 50 years\n* Diagnosis of TSC is genetically confirmed by CENTOGENE\n\nEXCLUSION CRITERIA\n\n* Inability to provide informed consent\n* Participant is younger than 2 or older than 50 years\n* Diagnosis of TSC is not genetically confirmed by CENTOGENE",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "2 Years",
          "maximumAge": "50 Years",
          "stdAges": [
            "CHILD",
            "ADULT"
