        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Number of Participants Experiencing Adverse Events (AEs) Serious AEs, and Discontinuations Due to AEs",
              "description": "AE: any untoward medical occurrence that did not necessarily have a causal relationship with study treatment. SAE: any untoward medical occurrence that at any dose: resulted in death; in the view of the Investigator, placed the participant at immediate risk of death (a life threatening event); required inpatient hospitalization or prolongation of existing hospitalization; resulted in persistent or significant disability/incapacity; resulted in a congenital anomaly/birth defect; any other medically important event that, in the opinion of the Investigator, could have jeopardized the participant or may have required intervention to prevent one of the other outcomes listed in the definition above. Data collected after Amendment 3 took effect were excluded for participants enrolled into study 105MS302 on every 4 week dosing, but not excluded for participants enrolled on every 2 week dosing.",
              "timeFrame": "up to 4 years"
            },
            {
              "measure": "Number of Participants With Potentially Clinically Significant Hematology Laboratory Abnormalities",
              "description": "Data collected after Amendment 3 took effect were excluded for participants enrolled into study 105MS302 on every 4 week dosing, but not excluded for participants enrolled on every 2 week dosing.",
              "timeFrame": "up to 4 years"
            },
            {
              "measure": "Number of Participants With Shifts From Baseline: Liver Function Laboratory Values",
              "description": "Shift to low includes normal to low, high to low, and unknown to low. Shift to high includes normal to high, low to high, and unknown to high. For participants who switched to alternative MS medications, data after switch and 14 days after last dose of study treatment are excluded. Data collected after Amendment 3 took effect were excluded for participants enrolled into study 105MS302 on every 4 week dosing, but not excluded for participants enrolled on every 2 week dosing. ALT=alanine aminotransferase; AST=aspartate aminotransferase; GGT=gamma-glutamyl transferase.",
              "timeFrame": "Baseline (BIIB017 Treatment Baseline from Study 105MS301) up to 4 years"
            },
            {
              "measure": "Number of Participants With Shifts From Baseline: Kidney Function and Other Blood Chemistry",
              "description": "Shift to low includes normal to low, high to low, and unknown to low. Shift to high includes normal to high, low to high, and unknown to high. For participants who switched to alternative MS medications, data after switch and 14 days after last dose of study treatment are excluded. Data collected after Amendment 3 took effect were excluded for participants enrolled into study 105MS302 on every 4 week dosing, but not excluded for participants enrolled on every 2 week dosing. TSH=thyroid stimulating hormone.",
              "timeFrame": "Baseline (BIIB017 Treatment Baseline from Study 105MS301) up to 4 years"
            },
            {
              "measure": "Number of Participants With Shifts From Baseline: Urinalysis",
              "description": "Shift to low includes normal to low, high to low, and unknown to low. Shift to high/positive includes normal to high/positive, low to high/positive, negative to high/positive, and unknown to high/positive. For participants who switched to alternative MS medications, data after switch and 14 days after last dose of study treatment are excluded. Data collected after Amendment 3 took effect were excluded for participants enrolled into study 105MS302 on every 4 week dosing, but not excluded for participants enrolled on every 2 week dosing. Pos=positive; RBC=red blood cells; WBC=white blood cells.",
              "timeFrame": "Baseline (BIIB017 Treatment Baseline from Study 105MS301) up to 4 years"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Annualized Relapse Rate (ARR)",
              "description": "Relapses are defined as new or recurrent neurologic symptoms not associated with fever or infection, lasting at least 24 hours, and accompanied by new objective neurological findings upon examination by the examining neurologist. The annualized relapse rate is calculated as the total number of relapses occurred during the period for all participants, divided by the total number of person-years followed in the period.",
              "timeFrame": "up to 4 years"
            },
            {
              "measure": "Percentage of Participants Who Relapsed",
              "description": "Relapses are defined as new or recurrent neurologic symptoms not associated with fever or infection, lasting at least 24 hours, and accompanied by new objective neurological findings upon examination by the examining neurologist. New or recurrent neurologic symptoms that occur less than 30 days following the onset of a relapse were considered part of the same relapse. Participants who did not experience a relapse prior to switching to alternative MS medications, withdrew from study, or Amendment 3 (A3) took effect were censored at the time of switch/withdrawal/A3 effective date.",
              "timeFrame": "Up to 4 years"
            },
            {
              "measure": "Number of New or Newly Enlarging T2 Hyperintense Lesions",
              "description": "The total number of new or newly enlarging T2 hyperintense lesions (from Study 105MS302 Baseline) as assessed by magnetic resonance imaging (MRI). Observed data after participants switched to alternative MS medications or after Amendment 3 took effect are excluded.",
              "timeFrame": "Week 48, Week 96"
            },
            {
              "measure": "Number of New Active Lesions",
              "description": "The number of new active lesions as assessed by MRI. Observed data after participants switched to alternative MS medications or after Amendment 3 took effect are excluded.",
              "timeFrame": "Week 48, Week 96"
            },
            {
              "measure": "Number of New T1 Hypointense Lesions",
              "description": "The total number of new T1 hypointense lesions as assessed by MRI.",
              "timeFrame": "Week 48, Week 96"
            },
            {
              "measure": "Number of Gd-Enhancing Lesions",
              "description": "The number of Gd-enhancing lesions as assessed by MRI. Observed data after participants switched to alternative MS medications or after Amendment 3 took effect are excluded.",
              "timeFrame": "Baseline (start of 105MS302), Week 48, Week 96"
            },
            {
              "measure": "Volume of T2 Hyperintense Lesions",
              "description": "The volume of T2 hyperintense lesions as assessed by MRI. Observed data after participants switched to alternative MS medications or after Amendment 3 took effect are excluded.",
              "timeFrame": "Baseline (start of 105MS302), Week 48, Week 96"
            },
            {
              "measure": "Volume of T1 Hypointense Lesions",
              "description": "The volume of T1 hypointense lesions as assessed by MRI. Observed data after participants switched to alternative MS medications or after Amendment 3 took effect are excluded.",
              "timeFrame": "Baseline (start of 105MS302), Week 48, Week 96"
            },
            {
              "measure": "Volume of Gd-Enhancing Lesions",
              "description": "The volume of Gd-enhancing lesions as assessed by MRI. Observed data after participants switched to alternative MS medications or after Amendment 3 took effect are excluded.",
              "timeFrame": "Baseline (start of 105MS302), Week 48, Week 96"
            },
            {
              "measure": "Percentage Change of Whole Brain Volume",
              "description": "Percentage change of whole brain volume as assessed by MRI. Observed data after participants switched to alternative MS medications or after Amendment 3 took effect are excluded.",
              "timeFrame": "Baseline (start of 105MS302), Week 48, Week 96"
            },
            {
              "measure": "Change From Baseline in Expanded Disability Status Scale (EDSS)",
              "description": "Change from Baseline in disability as measured by the Expanded Disability Status Scale (EDSS). The EDSS measures the disability status of people with multiple sclerosis on a scale that ranges from 0 to 10. The range of main categories include (0) = normal neurologic exam; to (5) = ambulatory without aid or rest for 200 meters; disability severe enough to impair full daily activities; to (10) = death due to MS. Data after participants switched to alternative MS medications or after Amendment 3 took effect are excluded.",
              "timeFrame": "Baseline (start of 105MS302), Weeks 12, 24, 48, 72, 96, 120, 144, 168"
            },
            {
              "measure": "Time to Sustained Disability Progression",
              "description": "Estimated proportion of participants with progression and time to progression based on the Kaplan-Meier product limit method. Sustained disability progression is defined as: at least a 1.0 point increase on the EDSS from 105MS302 baseline EDSS ≥ 1.0 that is sustained for 24 weeks, or at least a 1.5 point increase on the EDSS from 105MS302 baseline EDSS = 0 that is sustained for 24 weeks. The EDSS measures the disability status of people with multiple sclerosis on a scale that ranges from 0 to 10. The range of main categories include (0) = normal neurologic exam; to (5) = ambulatory without aid or rest for 200 meters; disability severe enough to impair full daily activities; to (10) = death due to MS. Participants were censored at the time of withdrawal/switch/A3 effective date if they withdrew from study, switched to alternative MS medication, or Amendment 3 took effect without a progression.",
              "timeFrame": "Weeks 12, 24, 28, 72, 96, 120, 144, 168"
            },
            {
              "measure": "Change From Baseline in Symbol Digit Modalities Test (SDMT)",
              "description": "SDMT is a screening test for cognitive impairment. Participants are given 90 seconds in which to pair specific numbers with given geometric figures using a key. Scores range from 0 (worst) to 110 (best).",
              "timeFrame": "Baseline (start of 105MS302), Weeks 24, 48, 72, 96, 120, 144, 168"
            },
            {
              "measure": "Change From Baseline in Multiple Sclerosis Impact Scale (MSIS)-29 Physical Score",
              "description": "The 29-item MSIS-29 is a disease-specific participant-reported outcome measure that has been developed and validated to examine the physical and psychological impact of MS from a patient's perspective; it measures 20 physical items and 9 psychological items. Responses use a 5-point Likert scale ranging from 1 to 5. All questions are to be answered. The physical well being assessment portion of the MSIS-29 consists of 20 questions in which participants rate the impact of MS on their day-to-day life during the past two weeks from 1=no impact to 5=extreme impact for a total score of 20-100. A lower total score indicates less physically-related impact while a higher total score indicates greater physically-related impact on a participant's functioning. Observed data after participants switched to alternative MS medications or after Amendment 3 took effect are excluded.",
              "timeFrame": "Baseline (start of 105MS302), Weeks 24, 48, 72, 96, 120, 144, 168"
            },
            {
              "measure": "Change From Baseline in 12-Item Short Form Health Survey (SF-12) Mental Component Score (MCS)",
              "description": "The SF-12 is a multipurpose short form survey with 12 questions, all selected from the SF-36 Health Survey. The questions were combined, scored, and weighted to create two scales that provide glimpses into mental and physical functioning and overall health-related-quality of life. MCS computed using the scores of 12 questions and range from 0 to 100, where a 0 score indicates the lowest level of health and 100 indicates the highest level of health. Observed data after participants switched to alternative MS medications or after Amendment 3 took effect are excluded.",
              "timeFrame": "Baseline (start of 105MS302), Weeks 24, 48, 72, 96, 120, 144, 168"
            },
            {
              "measure": "Change From Baseline in SF-12 Physical Component Score (PCS)",
              "description": "The SF-12 is a multipurpose short form survey with 12 questions, all selected from the SF-36 Health Survey. The questions were combined, scored, and weighted to create two scales that provide glimpses into mental and physical functioning and overall health-related-quality of life. PCS was computed using the scores of 12 questions and range from 0 to 100, where a 0 score indicates the lowest level of health and 100 indicates the highest level of health. Observed data after participants switched to alternative MS medications or after Amendment 3 took effect are excluded.",
              "timeFrame": "Baseline (start of 105MS302), Weeks 24, 48, 72, 96, 120, 144, 168"
            },
            {
              "measure": "Change From Baseline in Euro Quality of Life (EQ-5D) Index Score",
              "description": "The EQ-5D is a participant-answered questionnaire scoring 5 dimensions: mobility, self-care, usual activities, pain/discomfort and anxiety/depression. Scores of 1, 2, or 3 are possible responses for each of 5 questions (1=no problems, 2=some problems, 3=severe problems). A scoring formula developed by the EuroQol Group is then used to assign utility values for each participant's Health State Profile. A summary index score (EQ-5D index score) is derived from the 5 questions by conversion with this scoring formula and a table of scores. EQ-5D Summary Index values ranged from -0.6 (worst health state) to 1.00 (perfect health state). Observed data after participants switched to alternative MS medications or after Amendment 3 took effect are excluded.",
              "timeFrame": "Baseline (start of 105MS302), Weeks 24, 48, 72, 96, 120, 144, 168"
            },
            {
              "measure": "Change From Baseline in EQ-5D Visual Analogue Scale (VAS)",
              "description": "The EQ-5D VAS records the participant's self-rated health on a scale from 0-100 where 100 is the 'best imaginable health state' and 0 is the 'worst imaginable health state.' The scale was normalized to a scale of 0 to 1, with higher values indicating a better health state. Observed data after participants switched to alternative MS medications or after Amendment 3 took effect are excluded.",
              "timeFrame": "Baseline (start of 105MS302), Weeks 24, 48, 72, 96, 120, 144, 168"
            },
            {
              "measure": "Number of Relapses Requiring IV Steroid Use",
              "description": "Observed data after participants switched to alternative MS medications or after Amendment 3 took effect are excluded.",
              "timeFrame": "up to 4 years"
            },
            {
              "measure": "Number of MS-Related Hospitalizations",
              "description": "Observed data after participants switched to alternative MS medications or after Amendment 3 took effect are excluded.",
              "timeFrame": "up to 4 years"
            },
            {
              "measure": "Summary of Participant-Reported Treatment Satisfaction: How Tolerable or Intolerable Do You Find the Medication?",
              "description": "Participants completed a Treatment Satisfaction Questionnaire composed of a range of 14 questions regarding the participant's perception of treatment satisfaction at the end of each year of treatment. For the question \"How tolerable or intolerable do you find the medication?\" answers were numerically rated from 1 (extremely intolerable) to 10 (extremely tolerable). Data after Amendment 3 took effect are excluded.",
              "timeFrame": "Year 1, Year 2, Year 3"
            },
            {
              "measure": "Summary of Participant-Reported Treatment Satisfaction: How Convenient or Inconvenient Is It to Take Your Medication as Instructed?",
              "description": "Participants completed a Treatment Satisfaction Questionnaire composed of a range of 14 questions regarding the participant's perception of treatment satisfaction at the end of each year of treatment. For the question \"How convenient or inconvenient is it to take your medication as instructed?\" answers were numerically rated from 1 (extremely inconvenient) to 10 (extremely convenient). Data after Amendment 3 took effect are excluded.",
              "timeFrame": "Year 1, Year 2, Year 3"
            },
            {
              "measure": "Summary of Participant-Reported Treatment Satisfaction: How Convenient or Inconvenient Is It to Take Your Medication Every 2 Weeks?",
              "description": "Participants completed a Treatment Satisfaction Questionnaire composed of a range of 14 questions regarding the participant's perception of treatment satisfaction at the end of each year of treatment. For the question \"How convenient or inconvenient is it to take your medication every 2 weeks?\" answers were numerically rated from 1 (extremely inconvenient) to 10 (extremely convenient). Data after Amendment 3 took effect are excluded.",
              "timeFrame": "Year 1, Year 2, Year 3"
            },
            {
              "measure": "Summary of Participant-Reported Treatment Satisfaction: Overall, How Satisfied or Dissatisfied Are You With This Medication?",
              "description": "Participants completed a Treatment Satisfaction Questionnaire composed of a range of 14 questions regarding the participant's perception of treatment satisfaction at the end of each year of treatment. For the question \"Overall, how satisfied or dissatisfied are you with this medication?\" answers were numerically rated from 1 (extremely dissatisfied) to 10 (extremely satisfied). Data after Amendment 3 took effect are excluded.",
              "timeFrame": "Year 1, Year 2, Year 3"
            },
            {
              "measure": "Summary of Participant-Reported Treatment Satisfaction: How Satisfied or Dissatisfied Are You With the Injection Frequency (Every 2 Weeks)?",
              "description": "Participants completed a Treatment Satisfaction Questionnaire composed of a range of 14 questions regarding the participant's perception of treatment satisfaction at the end of each year of treatment. For the question \"How satisfied or dissatisfied are you with the injection frequency (every 2 weeks)?\" answers were numerically rated from 1 (extremely dissatisfied) to 10 (extremely satisfied). Data after Amendment 3 took effect are excluded.",
              "timeFrame": "Year 1, Year 2, Year 3"
            },
            {
              "measure": "Summary of Participant-Reported Treatment Satisfaction: How Likely Would You Be to Continue to Use This Medication?",
              "description": "Participants completed a Treatment Satisfaction Questionnaire composed of a range of 14 questions regarding the participant's perception of treatment satisfaction at the end of each year of treatment. For the question \"How likely would you be to continue to use this medication?\" answers were numerically rated from 1 (extremely unlikely) to 10 (extremely likely). Data after Amendment 3 took effect are excluded.",
              "timeFrame": "Year 1, Year 2, Year 3"
            },
            {
              "measure": "Summary of Participant-Reported Treatment Satisfaction: This Medication Enables Me to Focus More on Myself and My Family Rather Than My MS.",
              "description": "Participants completed a Treatment Satisfaction Questionnaire composed of a range of 14 questions regarding the participant's perception of treatment satisfaction at the end of each year of treatment. For the statement \"This Medication Enables Me to Focus More on Myself and My Family Rather Than My MS,\" answers were numerically rated from 1 (strongly disagree) to 10 (strongly agree). Data after Amendment 3 took effect are excluded.",
              "timeFrame": "Year 1, Year 2, Year 3"
            },
            {
              "measure": "Summary of Participant-Reported Treatment Satisfaction: This Medication Makes It Easy For Me to Carry Out My Daily Responsibilities.",
              "description": "Participants completed a Treatment Satisfaction Questionnaire composed of a range of 14 questions regarding the participant's perception of treatment satisfaction at the end of each year of treatment. For the statement \"This medication makes it easy for me to carry out my daily responsibilities (ie, going to work, doing household chores or caring for my family),\" answers were numerically rated from 1 (strongly disagree) to 10 (strongly agree). Data after Amendment 3 took effect are excluded.",
              "timeFrame": "Year 1, Year 2, Year 3"
            },
            {
              "measure": "Summary of Participant-Reported Treatment Satisfaction: The Twice a Month Dosing Makes It More Convenient for Me to Travel/Vacation.",
              "description": "Participants completed a Treatment Satisfaction Questionnaire composed of a range of 14 questions regarding the participant's perception of treatment satisfaction at the end of each year of treatment. For the statement \"The twice a month dosing makes it more convenient for me to travel/vacation,\" answers were numerically rated from 1 (strongly disagree) to 10 (strongly agree). Data after Amendment 3 took effect are excluded.",
              "timeFrame": "Year 1, Year 2, Year 3"
            },
            {
              "measure": "Summary of Participant-Reported Treatment Satisfaction: The Twice a Month Dosing Enables Me to Be More Spontaneous and Flexible.",
              "description": "Participants completed a Treatment Satisfaction Questionnaire composed of a range of 14 questions regarding the participant's perception of treatment satisfaction at the end of each year of treatment. For the statement \"The twice a month dosing enables me to be more spontaneous and flexible,\" answers were numerically rated from 1 (strongly disagree) to 10 (strongly agree). Data after Amendment 3 took effect are excluded.",
              "timeFrame": "Year 1, Year 2, Year 3"
            },
            {
              "measure": "Summary of Participant-Reported Treatment Satisfaction: This Medication Improves My Self-Confidence and Self-Reliance.",
              "description": "Participants completed a Treatment Satisfaction Questionnaire composed of a range of 14 questions regarding the participant's perception of treatment satisfaction at the end of each year of treatment. For the statement \"This medication improves my self-confidence and self-reliance,\" answers were numerically rated from 1 (strongly disagree) to 10 (strongly agree). Data after Amendment 3 took effect are excluded.",
              "timeFrame": "Year 1, Year 2, Year 3"
            },
            {
              "measure": "Summary of Participant-Reported Treatment Satisfaction: I Am Satisfied With the Dosing Frequency of This Medication.",
              "description": "Participants completed a Treatment Satisfaction Questionnaire composed of a range of 14 questions regarding the participant's perception of treatment satisfaction at the end of each year of treatment. For the statement \"I am satisfied with the dosing frequency (2 times per month) of this medication\" answers were numerically rated from 1 (strongly disagree) to 10 (strongly agree). Data after Amendment 3 took effect are excluded.",
              "timeFrame": "Year 1, Year 2, Year 3"
            },
            {
              "measure": "Summary of Participant-Reported Treatment Satisfaction: Over the Past 4 Weeks, Did You Miss Any of Your Injections?",
              "description": "Participants completed a Treatment Satisfaction Questionnaire composed of a range of 14 questions regarding the participant's perception of treatment satisfaction at the end of each year of treatment. For the question \"Over the past 4 weeks, did you miss any of your injections?\" answer choices were given as \"none missed,\" \"miss 1 injection,\" or \"miss 2 injections.\" Data after Amendment 3 took effect are excluded.",
              "timeFrame": "Year 1, Year 2, Year 3"
            },
            {
              "measure": "Summary of Participant-Reported Treatment Satisfaction: Main Reason for Missed Injections",
              "description": "Participants completed a Treatment Satisfaction Questionnaire composed of a range of 14 questions regarding the participant's perception of treatment satisfaction at the end of each year of treatment. For the question \"Main reason for missed injections?\" answer choices were given as \"medication side effects,\" \"injection pain,\" \"forget to take medication,\" \"tired of taking injections,\" \"don't think medication is working,\" or \"other.\" Data after Amendment 3 took effect are excluded.",
              "timeFrame": "Year 1, Year 2, Year 3"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Key Inclusion Criteria:\n\n* Must have completed the study treatment and visit schedule through Week 96 in Study 105MS301 (NCT00906399).\n\nKey Exclusion Criteria:\n\n* Subjects exceeding more than 6 weeks since completion of the Week 96 visit of Study 105MS301 (NCT00906399).\n* Subjects with any clinically significant laboratory abnormalities, malignancies, cardiac, endocrinologic, hematologic, hepatic, immunologic, metabolic, urologic, pulmonary, neurologic, dermatologic, psychiatric, renal, or other major disease\n* Pregnant or nursing women.\n\nNOTE: Other protocol-defined Inclusion/Exclusion criteria may apply.",
