      "resultsSection": {
        "participantFlowModule": {
          "preAssignmentDetails": "Participants continued BIIB017 at the same dosage regimen they were following during treatment year 2 of Study 105MS301: BIIB017 125 μg subcutaneously (SC) every 2 weeks (Q2W) or every 4 weeks (Q4W). A major change in study design was introduced in Amendment 3 of the protocol, which switched all ongoing subjects dosing Q4W to dosing Q2W.",
          "recruitmentDetails": "Study 105MS302 (NCT01332019) is an extension study and includes participants previously randomized to Study 105MS301 (NCT00906399). Only participants in Study 105MS301 who completed the study treatment and visit schedule through Week 96 were eligible for entry into this study.",
          "groups": [
            {
              "id": "FG000",
              "title": "BIIB017 Q4W",
              "description": "125 µg BIIB017 administered by SC injection Q4W for at least 2 years and up to 4 years."
