        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Annualized relapse rate (ARR) of confirmed relapses [Core Part]",
              "description": "ARR is the average number of confirmed MS relapses in a year",
              "timeFrame": "From Baseline, up to 30 months"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Time to 3-month confirmed disability progression (3mCDP) on Expanded Disability Status Scale (EDSS) [Core Part] (pooled data)",
              "description": "Time to 3-month confirmed disability progression (3mCDP) is defined as an increase in Expanded Disability Status Scale (EDSS) which is sustained for at least 3 months",
              "timeFrame": "Baseline up to 30 months"
            },
            {
              "measure": "Time to 6-month confirmed disability progression (6mCDP) on EDSS [Core Part] (pooled data)",
              "description": "Time to 6-month confirmed disability progression (6mCDP) is defined as an increase in Expanded Disability Status Scale (EDSS) which is sustained for at least 6 months",
              "timeFrame": "Baseline up to 30 months"
            },
            {
              "measure": "Annualized rate of new or enlarging T2 lesion [Core Part]",
              "description": "Number of new/newly enlarged T2 lesions per year",
              "timeFrame": "Baseline up to 30 months"
            },
            {
              "measure": "Neurofilament light chain (Nfl) [Core Part]",
              "description": "Neurofilament light chain (NfL) concentration in serum",
              "timeFrame": "Baseline up to 30 months"
            },
            {
              "measure": "Number of Gd-enhancing T1 lesions per MRI scan [Core Part]",
              "description": "Average number of Gd-enhancing T1 lesions per scan",
              "timeFrame": "Baseline up to 30 months"
            },
            {
              "measure": "Percentage of participants with No Evidence of Disease Activity-3 (NEDA-3) [Core Part] (pooled data)",
              "description": "Percentage of participants with No Evidence of Disease Activity-3 (NEDA-3), as assessed by absence of confirmed MS relapses, 6mCDP and new/enlarging T2 lesions on MRI",
              "timeFrame": "Baseline up to 30 months"
            },
            {
              "measure": "Time to first confirmed relapse [Core Part]",
              "description": "Change in the Expanded Disability Status Scale (EDSS), an increase of at least 0.5 points on the EDSS (total) score, or an increase of at least 1 point on at least two functional scores (FSs), or an increase of at least 2 points on at least one FS, excluding changes involving bowel/bladder or cerebral FS, compared to the previous available rating.",
              "timeFrame": "Baseline up to 30 months"
            },
            {
              "measure": "Time to 6-month confirmed disability improvement (6mCDI) on EDSS [Core Part] (pooled data)",
              "description": "Decrease in Expanded Disability Status Scale Score (EDSS) which is sustained for at least 6 months",
              "timeFrame": "Baseline up to 30 months"
            },
            {
              "measure": "Time to 3-months confirmed disability progression (3mCDP) and 6-month confirmed disability progression (6mCDP) independent of relapse activity (PIRA) [Core Part] (pooled data)",
              "description": "Time to 3-month confirmed disability progression (3mCDP) and 6-month confirmed disability progression (6mCDP) is defined as an increase in Expanded Disability Status Scale (EDSS) which is sustained for at least 3 months or 6 months, respectively, without an on-study relapse before or on the day of a progression eve",
              "timeFrame": "Baseline up to 30 months"
            },
            {
              "measure": "Change from baseline in the Symbol Digit Modalities Test (SDMT) [Core Part] (pooled data)",
              "description": "Symbol Digit Modalities Test (SDMT), an array of symbols paired with empty spaces, measures processing in speed; participants verbally match the number for each symbol as rapidly as possible. The score is the number of correctly coded items in 90 seconds. Higher scores indicate improvement. Lower scores indicate worsening",
              "timeFrame": "Baseline up to 30 months"
            },
            {
              "measure": "Time to 6-month confirmed worsening by at least 20% in the Timed 25-foot walk test (T25FW) [Core Part] (pooled data)",
              "description": "The patient walking speed to cover 25-foot distance is recorded in seconds. Longer time indicates poorer lower limb function. 20% worsening is defined as 20% increase from baseline T25FW score",
              "timeFrame": "Baseline, up to 30 months"
            },
            {
              "measure": "Time to 6-month confirmed worsening by at least 20% in the Timed 9-hole peg test (9HPT) (pooled data) [Core Part] (pooled data)",
              "description": "The patient's right and left arm function to peg 9 holes measured in seconds. Longer time indicates poorer upper limb function. 20% worsening is defined as 20% increase from baseline 9HPT score in at least one hand (average of two trials per hand)",
              "timeFrame": "Baseline up to 30 months"
            },
            {
              "measure": "Time to composite 6-month confirmed disability Progression (CDP) [Core Part] (pooled data)",
              "description": "The composite involves CDP and worsening by at least 20% in T25FW and 9HPT",
              "timeFrame": "Baseline up to 30 months"
            },
            {
              "measure": "Change from Baseline in T2 lesion volume [Core Part]",
              "description": "Change from baseline in total T2 lesion volume.",
              "timeFrame": "Baseline up to 30 months"
            },
            {
              "measure": "Change from baseline in Multiple Sclerosis Impact Scale (MSIS-29) [Core Part]",
              "description": "29-item, self-administered questionnaire that includes 2 domains, physical and psychological. Responses are captured on a 4-point scale ranging from \"not at all\" (1) to \"extremely\" (4), where higher scores reflect greater impact on day to day life",
              "timeFrame": "Baseline up to 30 months"
            },
            {
              "measure": "Number of participants with Adverse events and Serious adverse events(SAE) [Core Part]",
              "description": "Adverse events and SAEs including clinically significant, laboratory data, vital signs, electrocardiogram (ECG), Columbia Suicide Severity Rating",
              "timeFrame": "Baseline up to 30 months"
            },
            {
              "measure": "Pharmacokinetics of remibrutinib [Core Part]",
              "description": "Blood concentrations of remibrutinib",
              "timeFrame": "Month 1, Month 6"
            },
            {
              "measure": "Number of participants with Adverse events and Serious adverse events (SAE) [Extension Part]",
              "description": "Adverse events and SAEs including clinically significant, laboratory data, vital signs, electrocardiogram (ECG), Columbia Suicide Severity Rating",
              "timeFrame": "Day 1 Extension up to 5 years"
            },
            {
              "measure": "Annualized relapse rate (ARR) of confirmed relapses [Extension Part]",
              "description": "ARR is the average number of confirmed MS relapses in a year",
              "timeFrame": "Day 1 Extension up to 5 years"
            },
            {
              "measure": "Annualized rate of new or enlarging T2 lesion [Extension Part]",
              "description": "Number of new/newly enlarged T2 lesions per year",
              "timeFrame": "Day 1 Extension up to 5 years"
            },
            {
              "measure": "Time to 6-month confirmed disability progression (6mCDP) on EDSS [Extension Part]",
              "description": "Time to 6-month confirmed disability progression (6mCDP) is defined as an increase in Expanded Disability Status Scale (EDSS) which is sustained for at least 6 months",
              "timeFrame": "Day 1 Extension up to 5 years"
            },
            {
              "measure": "Change from baseline in the Symbol Digit Modalities Test (SDMT) [Extension Part]",
              "description": "Symbol Digit Modalities Test (SDMT), an array of symbols paired with empty spaces, measures processing in speed; participants verbally match the number for each symbol as rapidly as possible. The score is the number of correctly coded items in 90 seconds. Higher scores indicate improvement. Lower scores indicate worsening",
              "timeFrame": "Day 1 Extension up to 5 years"
