          },
          "briefTitle": "The Efficacy of Tele Rehabilitation- Based Task-Specific Training for Cognitive Function Improvement",
          "officialTitle": "The Efficacy of Tele Rehabilitation- Based Task-Specific Training for Cognitive Function Improvement in Multiple Sclerosis (MS) Patients"
        },
        "statusModule": {
          "statusVerifiedDate": "2024-05",
          "overallStatus": "UNKNOWN",
