        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "(Balance Training + Cognitive Rehabilitation)",
              "type": "EXPERIMENTAL",
              "description": "Group A will receive both balance training and cognitive rehabilitation twice a week for 12 weeks and each session will last for 1 hour.",
              "interventionNames": [
                "Other: Balance training",
