            "class": "OTHER"
          },
          "briefTitle": "Evaluating the Ottawa Malaria Decision Aid",
          "officialTitle": "Incorporation of the 'Ottawa Malaria Decision Aid' Into the Pre-travel Consultation Process: Assessment of Travelers' Knowledge, Decisional Conflict, Preparation for Decision-making and Medication Adherence Compared to Standard Care",
          "acronym": "OMDA"
        },
        "statusModule": {
          "statusVerifiedDate": "2015-04",
          "overallStatus": "UNKNOWN",
          "lastKnownStatus": "RECRUITING",
          "expandedAccessInfo": {
