          ],
          "interventions": [
            {
              "type": "OTHER",
              "name": "Ottawa Malaria Decision Aid",
              "description": "The Ottawa Malaria Decision Aid is a tool that helps patients become involved in decision making about which malaria prophylaxis pill is right for them to take. The decision aid provides information about the options for malaria chemoprophylaxis, information about the financial costs and time required to adhere to the course of preventative medication, and clarifies personal values. The decision aid is designed to complement counseling from a health practitioner.",
              "armGroupLabels": [
                "Decision Aid + Standard Care"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Travellers' Knowledge Score",
              "description": "The traveller's knowledge score will be calculated based on participant's answers to questions from the Ottawa Malaria Knowledge Scale (2007) and the Realistic Expectations Scale (O'Connor 1996). For each multiple choice question, every possible response contains a predetermined scoring scheme. The traveller's knowledge score is calculated by adding points from each question answered. The sum of points forms the traveller's knowledge score.",
              "timeFrame": "One year"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Decisional Conflict Score",
              "description": "The decisional conflict score will be measured based on responses in the questionnaire using specific questions from the Decisional Conflict Scale (O'Connor, 1993, revised 2005), the Medical Decision Making Scale (Adapted from Strull, 1984), the Values Scale (Adapted from O'Connor 1999), and the Decision Regret Scale (O'Connor, 1996). For each scaled question, every possible response contains a predetermined scoring scheme. The score is calculated by adding points from each question answered. The sum of points forms the score.",
              "timeFrame": "One year"
            },
            {
              "measure": "Preparation for Decision-making Score",
              "description": "The preparation for decision making score will be measured based on responses in the questionnaire using specific questions from the Preparation for Decision Making Scale (Graham, O'Connor 1996, revised 2005), and the Choice Predisposition Scale (O'Connor 2000). For each scaled question, every possible response contains a predetermined scoring scheme. The score is calculated by adding points from each question answered. The sum of points forms the score.",
              "timeFrame": "One year"
            },
            {
              "measure": "Medication Adherence Score",
              "description": "Medication adherence will be measured based on responses in the after-travel questionnaire using specific questions from the adapted ACTG Adherence questionnaire, and the Malaria Adherence Prophylactic Scale (MAPS). For each multiple choice and scaled question, every possible response contains a predetermined scoring scheme. The score is calculated by adding points from each question answered. The sum of points forms the score.",
              "timeFrame": "One year"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* An Adult 18 years of age or older\n* Individuals who have contacted the travel clinic at The Ottawa Hospital, General Campus, the National Capital Region Occupational Health Clinic or received study information from IAMAT before they travel\n* Travelling for less than one year\n* Departing for the trip in more than one week\n* Travelling to an area with known chloroquine-resistant malaria\n\nExclusion Criteria:\n\n* The travellers not visiting areas with chloroquine resistant malaria\n* Those travelling longer than one year\n* Departing for the trip in less than one week\n* Individuals younger than 18 years of age\n* Those who are pregnant or intend to become pregnant during their travel\n* Those who have severe kidney disease, severe liver disease, heart rhythm problems, or a history of seizures\n* Those who have a history of mental problems\n* Those who have an allergy to Atovaquone-proguanil, Doxycycline or Mefloquine\n* Those who are unable to understand written or spoken English or French due to deafness, blindness, cognitive impairment or language barrier",
          "healthyVolunteers": true,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ]
        },
