          "briefTitle": "Trial to Evaluate the Safety and Efficacy of Keppra After Conversion to Mono-therapy in Subjects With Partial Epilepsy",
          "officialTitle": "A Phase IV, Open-label, Multi-center Trial to Evaluate the Safety and Efficacy of Keppra® After Conversion to Mono-therapy in Adult Subjects With Partial Epilepsy"
        },
        "statusModule": {
          "statusVerifiedDate": "2009-09",
