        "descriptionModule": {
          "briefSummary": "A cohort of patients who became seizure-free during add-on treatment to one standard AED with Keppra in a previous trial (N01031) were followed to assess whether seizure freedom was maintained. Tolerability was documented."
        },
        "conditionsModule": {
          "conditions": [
            "Epilepsy"
          ],
          "keywords": [
            "Levetiracetam",
            "Keppra"
          ]
