            "count": 14,
            "type": "ACTUAL"
          }
        },
        "armsInterventionsModule": {
          "interventions": [
            {
              "type": "DRUG",
              "name": "Levetiracetam (Keppra)"
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Investigate seizure freedom with Keppra flexible dose."
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Tolerability and safety."
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Diagnosis of epilepsy with partial seizures;\n* having completed the trial N01031 of Keppra as adjunctive therapy (SKATE);\n* seizure-free over the last 3 months prior to protocol Visit 1;\n* 1 concomitant marketed AED at the time of trial entry and throughout the previous trial N01031;\n* on the clinical judgment of the Investigator, progressive withdrawal of the concomitant AED and conversion to monotherapy with Keppra can be attempted.\n\nExclusion Criteria:\n\n* History of suicide attempt, current suicidal ideation, or other serious psychiatric disorders requiring or having required hospitalization or medication within the previous 5 years;\n* presence of known pseudoseizures within the last year;\n* presence or history of allergy to the components of Keppra (levetiracetam, lactose, cornstarch, and excipients) or other pyrrolidine derivatives;\n* felbamate with less than 18 months exposure;\n* vigabatrin, without visual field assessment as per recommendation of the manufacturer, i.e., every 6 months;\n* uncountable seizures (clusters) or history of convulsive status epilepticus within the last 5 years.",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "16 Years",
          "stdAges": [
