          },
          "briefTitle": "A Retrospective Real-World Study on the Efficacy and Safety of Anlotinib Hydrochloride Combined With Immunotherapy Maintenance Therapy Following Standard Chemoimmunotherapy for ES-SCLC (ALTER-L059)",
          "officialTitle": "A Retrospective Real-World Study on the Efficacy and Safety of Anlotinib Hydrochloride Combined With Immunotherapy as Maintenance Therapy Following First-Line Chemoimmunotherapy in Treatment-Naïve Patients With Extensive-Stage Small Cell Lung Cancer (ES-SCLC) (ALTER-L059)"
        },
        "statusModule": {
          "statusVerifiedDate": "2025-07",
          "overallStatus": "NOT_YET_RECRUITING",
          "expandedAccessInfo": {
            "hasExpandedAccess": false
          },
          "startDateStruct": {
