        "sponsorCollaboratorsModule": {
          "responsibleParty": {
            "type": "SPONSOR_INVESTIGATOR",
            "investigatorFullName": "Yong Fang",
            "investigatorTitle": "professor",
            "investigatorAffiliation": "Sir Run Run Shaw Hospital"
          },
          "leadSponsor": {
            "name": "Yong Fang",
            "class": "OTHER"
          }
        },
        "oversightModule": {
          "oversightHasDmc": true,
          "isFdaRegulatedDrug": false,
          "isFdaRegulatedDevice": false
        },
        "descriptionModule": {
          "briefSummary": "This retrospective real-world study aims to evaluate the efficacy and safety of anlotinib hydrochloride combined with immunotherapy as maintenance therapy following standard chemoimmunotherapy in extensive-stage small cell lung cancer (ES-SCLC).The study population consists of treatment-naïve ES-SCLC patients who did not progress after induction chemoimmunotherapy and subsequently received maintenance therapy with anlotinib plus immunotherapy. The primary objectives are progression-free survival (PFS)，overall survival (OS)\n\n, and safety.",
          "detailedDescription": "This multicenter study seeks to retrospectively analyze medical records (January 2022-December 2024) of extensive-stage small cell lung cancer (ES-SCLC) patients treated with anlotinib hydrochloride (12/10/8 mg doses) alongside immune maintenance therapy after first-line chemoimmunotherapy in real-world clinical settings. Key data points will encompass demographics, baseline disease characteristics, treatment regimens, efficacy outcomes (e.g., objective response rate, progression-free survival), and adverse event profiles. Eligible patients must have received anlotinib for ≥6 weeks and possess evaluable radiographic assessments. The primary objectives are to assess the clinical effectiveness and safety of this combination strategy in ES-SCLC."
        },
        "conditionsModule": {
          "conditions": [
            "Small Cell Lung Cancer Extensive Stage"
          ]
        },
        "designModule": {
          "studyType": "OBSERVATIONAL",
          "patientRegistry": false,
          "designInfo": {
            "observationalModel": "COHORT",
            "timePerspective": "RETROSPECTIVE"
          },
          "enrollmentInfo": {
            "count": 100,
            "type": "ESTIMATED"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Experimental Group",
              "description": "patients treated with anlotinib Hydrochloride combined with immunotherapy maintenance therapy following standard chemoimmunotherapy."
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "PFS2",
              "description": "Progression-free survival from the initiation of anlotinib combined with immunotherapy maintenance treatment.",
              "timeFrame": "up to 12 months"
            }
          ],
          "secondaryOutcomes": [
