        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Percentage Change From the Combined Baseline in the Generalized Tonic-clonic Seizure Frequency Per Week Over the 28-week Treatment Period (Dose Adjustment + Evaluation Periods)",
              "description": "Percentage change in generalized tonic-clonic (GTC) seizure frequency per week from Combined Baseline B over the Treatment Period A is calculated using the equation:\n\nPercentage change from Baseline = ((A-B)/B)\\*100. Percentage change from baseline is not defined for subjects whose baseline information is missing / unknown or equal to zero, or whose seizure frequency per week is missing / unknown. A negative value in change in generalized tonic-clonic (GTC) seizure frequency indicates a reduction of generalized tonic-clonic (GTC) seizure frequency over the 28-week treatment Period.\n\nCombined Baseline means: a 4-week Retrospective Baseline + 4-week Prospective Baseline or 8-week Prospective Baseline",
              "timeFrame": "From Baseline to Week 28"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "The Percentage Change in Generalized Tonic-clonic Seizure Frequency Per Week From the Combined Baseline Over the Evaluation Period",
              "description": "Percentage change in generalized tonic-clonic (GTC) seizure frequency per week from combined baseline B over the Evaluation Period A is calculated using the equation:\n\nPercentage change from Baseline = ((A-B)/B)\\*100. Percentage change from baseline is not defined for subjects whose baseline Information is missing / unknown or equal to zero, or whose seizure frequency per week is missing / unknown. A negative value in change in generalized tonic-clonic (GTC) seizure frequency indicates a reduction of generalized tonic-clonic (GTC) seizure frequency.\n\nCombined Baseline means: a 4-week Retrospective Baseline + 4-week Prospective Baseline or 8-week Prospective Baseline.",
              "timeFrame": "From Baseline to Evaluation Period (Week 12 to Week 28)"
            },
            {
              "measure": "Generalized Tonic-clonic Seizures 50 % Responder Rate (the Proportion of Subjects With 50 % or More Reduction From the Combined Baseline in the Frequency of Generalized Tonic-clonic Seizures) During the Treatment Period",
              "description": "A subject with an at least 50 % reduction in weekly generalized tonic-clonic (GTC) seizure frequency from Combined Baseline Period to the Treatment Period is considered a GTC 50 % responder.\n\nCombined Baseline means: a 4-week Retrospective Baseline + 4-week Prospective Baseline or 8-week Prospective Baseline",
              "timeFrame": "From Baseline to Week 28"
            },
            {
              "measure": "Generalized Tonic-clonic Seizures 50 % Responder Rate (the Proportion of Subjects With 50 % or More Reduction From the Combined Baseline in the Frequency of Generalized Tonic-clonic Seizures) During the Evaluation Period",
              "description": "A subject with an at least 50 % reduction in weekly generalized tonic-clonic (GTC) seizure frequency from Combined Baseline Period to the Evaluation Period is considered a GTC 50 % responder.\n\nCombined Baseline means: a 4-week Retrospective Baseline + 4-week Prospective Baseline or 8-week Prospective Baseline",
              "timeFrame": "From Baseline to Evaluation Period (Week 12 to Week 28)"
            },
            {
              "measure": "Generalized Tonic-clonic Seizure Freedom Over the Evaluation Period",
              "description": "A subject with a non-missing weekly generalized tonic-clonic (GTC) baseline seizure frequency and a weekly GTC seizure frequency of zero throughout the Evaluation Period, is considered as a GTC seizure-free subject on the Evaluation Period.",
              "timeFrame": "Evaluation Period (Week 12 to Week 28)"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* An epilepsy patient with generalized tonic-clonic seizures that are classifiable according to the ILAE classification of epileptic seizures (Epilepsia, 1981)\n* A patient on a stable dose of 1 or 2 anti-epileptic drugs for the last 4 weeks (potassium bromide and sodium bromide for the last 12 weeks) prior to and during the combined baseline period\n\nExclusion Criteria:\n\n* Presence of any sign (clinical or imaging procedures) suggesting a progressive brain lesion/disease, in particular, progressive disorder with epileptic seizures\n* Diagnosis of Lennox-Gastaut Syndrome\n* Confirmed focal epilepsy based on clinical signs (seizure types), with consistent electroencephalogram and magnetic resonance imagining features\n* A history of convulsive or non-convulsive status epilepticus while taking concomitant anti-epileptic drugs for the last 3 months prior to Visit 1",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "16 Years",
          "stdAges": [
            "CHILD",
            "ADULT",
            "OLDER_ADULT"
          ]
