        "outcomeMeasuresModule": {
          "outcomeMeasures": [
            {
              "type": "PRIMARY",
              "title": "Percentage Change From the Combined Baseline in the Generalized Tonic-clonic Seizure Frequency Per Week Over the 28-week Treatment Period (Dose Adjustment + Evaluation Periods)",
              "description": "Percentage change in generalized tonic-clonic (GTC) seizure frequency per week from Combined Baseline B over the Treatment Period A is calculated using the equation:\n\nPercentage change from Baseline = ((A-B)/B)\\*100. Percentage change from baseline is not defined for subjects whose baseline information is missing / unknown or equal to zero, or whose seizure frequency per week is missing / unknown. A negative value in change in generalized tonic-clonic (GTC) seizure frequency indicates a reduction of generalized tonic-clonic (GTC) seizure frequency over the 28-week treatment Period.\n\nCombined Baseline means: a 4-week Retrospective Baseline + 4-week Prospective Baseline or 8-week Prospective Baseline",
              "populationDescription": "Full Analysis Set consisted of all subjects in the SS who had an evaluable Baseline and at least 1 post-Baseline GTC seizure count data point for the primary efficacy analysis excluding those who had seriously violated GCP. Evaluable Baseline for the primary efficacy analysis: at least 1 GTC seizure was documented for the Combined Baseline.",
              "reportingStatus": "POSTED",
              "paramType": "MEAN",
              "dispersionType": "Standard Deviation",
              "unitOfMeasure": "Percentage Change",
              "timeFrame": "From Baseline to Week 28",
              "groups": [
                {
                  "id": "OG000",
                  "title": "Placebo",
                  "description": "Matching placebo for 28 weeks\n\nPlacebo: Matching oral placebo tablets twice daily for 28 weeks"
                },
                {
                  "id": "OG001",
                  "title": "Levetiracetam",
                  "description": "Levetiracetam treatment with dosing of 1000 mg/day or 2000 mg/day or 3000 mg/day for 28 weeks\n\nLevetiracetam: Oral dose tablets, twice daily"
                }
              ],
              "denoms": [
                {
                  "units": "Participants",
                  "counts": [
                    {
                      "groupId": "OG000",
                      "value": "109"
                    },
                    {
                      "groupId": "OG001",
                      "value": "117"
                    }
                  ]
                }
              ],
              "classes": [
                {
                  "categories": [
                    {
                      "measurements": [
                        {
                          "groupId": "OG000",
                          "value": "-13.19",
                          "spread": "55.54"
                        },
                        {
                          "groupId": "OG001",
                          "value": "-68.22",
