          "organization": {
            "fullName": "Odense University Hospital",
            "class": "OTHER"
          },
          "briefTitle": "The Effect of Levetiracetam on the Postmastectomy Pain Syndrome",
          "officialTitle": "The Effect of Levetiracetam on the Postmastectomy Pain Syndrome"
        },
        "statusModule": {
          "statusVerifiedDate": "2007-11",
          "overallStatus": "COMPLETED",
          "expandedAccessInfo": {
            "hasExpandedAccess": false
          },
          "startDateStruct": {
            "date": "2004-03"
          },
          "completionDateStruct": {
            "date": "2006-09",
            "type": "ACTUAL"
          },
          "studyFirstSubmitDate": "2005-12-05",
          "studyFirstSubmitQcDate": "2005-12-05",
          "studyFirstPostDateStruct": {
            "date": "2005-12-06",
            "type": "ESTIMATED"
          },
          "lastUpdateSubmitDate": "2007-11-21",
          "lastUpdatePostDateStruct": {
            "date": "2007-11-26",
            "type": "ESTIMATED"
          }
        },
        "sponsorCollaboratorsModule": {
          "leadSponsor": {
            "name": "Odense University Hospital",
            "class": "OTHER"
          }
        },
        "oversightModule": {
          "oversightHasDmc": false
        },
        "descriptionModule": {
          "briefSummary": "The aim of this study is determine whether or not the antiepileptic drug Levetiracetam is an effective treatment of the postmastectomy pain syndrome.",
          "detailedDescription": "This study is a randomised, placebocontrolled, doubleblind study on the effect of the antiepileptic drug, levetiracetam, in patients suffering from PMPS. The treatment periods are 1 month each and the periods are separated by a 1-week washout period. The daily dose of levetiracetam is increased over a 2-week period to 3.000 mg/day. The primary effect variable is pain relief by the use of numeric rating scale. Secondary parameters are daily registration of pain performed by the patients during the treatment periods and the amount of escape medicine used (paracetamol and tramadol). Sensory testing is performed at baseline and after each treatment period."
        },
        "conditionsModule": {
          "conditions": [
            "Postoperative Pain"
          ]
        },
        "designModule": {
          "studyType": "INTERVENTIONAL",
          "phases": [
            "NA"
          ],
          "designInfo": {
            "allocation": "RANDOMIZED",
            "interventionModel": "CROSSOVER",
            "primaryPurpose": "TREATMENT",
            "maskingInfo": {
              "masking": "QUADRUPLE",
              "whoMasked": [
                "PARTICIPANT",
                "CARE_PROVIDER",
                "INVESTIGATOR",
                "OUTCOMES_ASSESSOR"
              ]
            }
          },
          "enrollmentInfo": {
            "count": 25,
            "type": "ACTUAL"
          }
        },
        "armsInterventionsModule": {
          "interventions": [
            {
              "type": "DRUG",
              "name": "Levetiracetam (drug)",
              "description": "The starting dose of levetiracetam was 500 mg/day and the dose was increased with 500 mg every other day to 6 tablets of 500 mg (Keppra, UCB, Belgium), divided into two doses daily corresponding to 3000 mg/day. The dose was kept at this level throughout the remaining treatment period - 4 weeks total. Six placebo tablets with identical appearance were dosed similarly to levetiracetam in the placebo phase.",
              "otherNames": [
                "Keppra, Levetiracetam"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Pain relief",
              "timeFrame": "After 1 month treatment"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Pain intensity measured daily on numeric rating scales",
              "timeFrame": "During treatment periods"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Symptoms characteristic for postmastectomy pain syndrome with a duration of more than 3 months and at least 6 months after the operation.\n* Neuropathic pain diagnose confirmed by abnormities in the neurological investigation and/or psychophysical sensory testing\n* Average (1 week) pain score minimum 4 on a 11 points numerical rating scale for total pain.\n* Pain present minimum 4 out of 7 days.\n* Fertile women must use anticonception.\n\nExclusion Criteria:\n\n* Verified og suspected other reason than mastectomy/lumpectomy for the pain.\n* Known allergic effects to levetiracetam.\n* Known sideeffects to treatment with levetiracetam.\n* Pregnancy or breast-feeding.\n* Severe disease (terminal cancer, heart failure, kidney insufficiency, severe respiratory problems)\n* Compliance problems",
          "healthyVolunteers": false,
          "sex": "FEMALE",
          "minimumAge": "18 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ]
        },
