        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Study Drug group",
              "type": "ACTIVE_COMPARATOR",
              "description": "Participants in this group will receive 500 mg of levetiracetam twice daily for 12 weeks. After 12 weeks, levetiracetam will be gradually decreased and stopped over the next 9 days. Questionnaires will be administered at each visit to examine how participants are responding to the treatment. In addition, a brain scan and cognitive testing will be performed when feasible at the beginning and the end of the study.",
              "interventionNames": [
                "Drug: Levetiracetam Pill"
              ]
            },
            {
              "label": "Placebo Group",
              "type": "PLACEBO_COMPARATOR",
              "description": "Participants in this group will receive a placebo that looks like the levetiracetam pill twice daily for 12 weeks. After 12 weeks, the levetiracetam dose will be tapered for the next 9 days. Questionnaires will be administered at each visit to examine how participants are responding to the treatment. In addition, a brain scan and cognitive testing will be performed when feasible at the beginning and the end of the study.",
              "interventionNames": [
                "Other: Placebo"
              ]
            }
          ],
          "interventions": [
            {
              "type": "DRUG",
              "name": "Levetiracetam Pill",
              "description": "Levetiracetam is an anticonvulsant that is frequently used to treat epilepsy in children and adults due to its superior tolerability, ease of use and excellent safety profile. It is rapidly absorbed and rapidly crosses the blood-brain barrier. Levetiracetam does not affect metabolism of antipsychotic drugs and may normalize hippocampal hyperactivity by decreasing excessive glutamatergic and dopaminergic transmission, thereby making it an ideal agent to test the hypothesis that reducing excessive hippocampal activity may enhance treatment of early psychosis and prevent antipsychotic toxicity. Levetiracetam will be administered in 500 mg capsules twice a day.",
              "armGroupLabels": [
                "Study Drug group"
              ],
              "otherNames": [
                "Keppra"
              ]
            },
            {
              "type": "OTHER",
              "name": "Placebo",
              "description": "The placebo pill (sugar pill) will look just like the levetiracetam pill but does not contain levetiracetam. Placebo will be taken along with optimal antipsychotic medication selected by either the outpatient provider or the hospital staff responsible for the participant's care. Participants will be instructed to take the placebo pill twice daily for 12 weeks.",
              "armGroupLabels": [
                "Placebo Group"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Change in BPRS total score",
              "description": "The efficacy of levetiracetam 500 mg bid vs. placebo on symptoms will be measured by the BPRS total score. Brief Psychiatric Rating Scale (BPRS) is an 18-item scale that measures positive symptoms, negative symptoms, general psychopathology and affective symptoms. Individual items are scored on a seven point likert scale. The total score is the sum of responses and ranges from 18 to 126; a higher score on the BPRS items indicates increased severity of symptoms.",
              "timeFrame": "Baseline visit (week 0), Week 12 visit"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Change in BPRS Psychosis Subscale",
              "description": "Brief Psychiatric Rating Scale (BPRS) is an 18-item scale that measures positive symptoms, negative symptoms, general psychopathology and affective symptoms. Individual items are scored on a seven point likert scale. The Psychosis subscale comprises 4 items of the BPRS. The total subscale score is the sum of responses and ranges from 4 to 42; a higher score indicates increased severity of symptoms.",
              "timeFrame": "Baseline visit (week 0), Week 12 visit"
            },
            {
              "measure": "Change in SANS Total Score",
              "description": "The Scale for Assessment of Negative Symptoms (SANS) will be the instrument for measurement of negative symptoms. SANS is a 19-tiem assessment; each item is rated on a scale from 0-5. The total score is the sum of the 19 individual item ratings and ranges from 0-95; higher scores indicate greater presence of negative symptoms.",
              "timeFrame": "Baseline visit (week 0), Week 12 visit"
            },
            {
              "measure": "Change in MATRICS Total Score",
              "description": "Measurement and Treatment Research to Improve Cognition in Schizophrenia (MATRICS) Consensus Cognitive Battery is the standard tool for assessing cognitive change in trials of cognitive-enhancing agents in schizophrenia. The assessment comprises ten individual tests to produce; the scores are converted into a standardized overall composite score, with a mean of 50 and a standard deviation of 10; higher scores indicate better cognitive performance.",
              "timeFrame": "Baseline visit (week 0), Week 12 visit"
            },
            {
              "measure": "Change in Hippocampal Volumetric Integrity",
              "description": "Assessed via MRI scan.",
              "timeFrame": "Baseline visit (week 0), Week 12 visit"
            },
            {
              "measure": "Change in Hippocampal Cerebral Blood Flow (CBF)",
              "description": "CBF measured using arterial spin labeling (ASL).",
              "timeFrame": "Baseline visit (week 0), Week 12 visit"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria\n\n* Males and females 16 to 40 years of age, inclusive, at time of informed consent\n* Must have experienced a first episode of nonaffective psychosis within 5 years and exhibit current psychosis, as defined by a score of ≥ 4 on one of the following psychosis items on the BPRS: conceptual disorganization, suspiciousness, hallucinations, unusual thought content, or grandiosity, for at least 4 days per week for at least 4 weeks\n* Must have a diagnosis of either schizophrenia, schizoaffective disorder or schizophreniform disorder as established by a Structured Clinical Interview for DSM-V (SCID)\n* Must have taken antipsychotic medication for a minimum of 8 weeks and at a stable dose for at least 4 weeks prior to randomization\n* If assigned female at birth and of childbearing potential, patients must:\n\n  * Have a negative urine pregnancy test (all participants assigned female at birth regardless of childbearing potential will be required to submit a pregnancy test) and\n  * Not be nursing or planning a pregnancy for the duration of the study through 30 days after the last dosing visit and\n  * Be abstinent or willing to use a reliable method of birth control from the screening visit and continue with the same method until termination from the study\n\nExclusion Criteria\n\n* Current substance abuse or dependence for substances other than nicotine and THC (i.e. alcohol, amphetamines, barbiturates)\n\n  * A positive urine toxic screen (excluding THC, tricyclic antidepressants, or benzodiazepines (if prescribed))\n  * Moderate or severe cannabis use disorder\n* Diagnosis of major mood disorder or other Axis I disorder other than Schizophrenia, Schizoaffective Disorder or Schizophreniform Disorder\n* Current suicidal ideation. Suicidal ideation with intent or plan (indicated by affirmative answers to items 4 or 5 of the suicidal ideation section of the baseline C-SSRS) in the 6 months prior to screening or subjects who represent a significant risk of suicide in the opinion of the Principal Investigator\n* Pregnant, nursing or positive urine pregnancy test\n* Significant medical or neurological illness by history or physical exam including seizure disorder, history of loss of consciousness related to head trauma or developmental disorder including mental retardation\n* Renal insufficiency (if serum creatinine is greater than laboratory limits for normal, estimated creatinine clearance must be greater than 80)\n* Contraindications to MRI: metal implants, pacemaker, or other metal in the body, or claustrophobia. Individuals with tattoos will be excluded from imaging if tattoos cover more than 5% of the body surface, if a tattoo is greater than 20 cm, or if the tattoo is located on the face, neck or genitals. (Individuals with a contraindication to MRI may participate in the trial but will be excluded from the elective MRI component)\n* Significant history of serious violence\n\n  * For both inpatient and outpatient subjects, a history of serious violence as assessed by the Buss-Perry Aggression Questionnaire\n  * For outpatient subjects only, a score of 5 (moderately severe) or higher on the BPRS hostility item at screening or baseline",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "16 Years",
          "maximumAge": "40 Years",
          "stdAges": [
            "CHILD",
            "ADULT"
          ]
