            {
              "label": "Phenobarbital Arm ( Group A )",
              "type": "ACTIVE_COMPARATOR",
              "description": "Patients in Group A will receive PHENobarbital at a loading dose of 20 mg/kg within a 20-minute time frame from the start of treatment. If the seizure dose is not stopped after 20 minutes, another 20 mg/kg of the same medication will be added, and if the seizure dose is not stopped within the total time frame of 40 minutes, this will be considered a treatment failure. If seizures are controlled, patients will receive a maintenance dose of PHENobarbital 3-5 mg/kg/day IV/PO, in 1-2 divided doses, starting 12 hours after the loading dose.",
              "interventionNames": [
                "Drug: Phenobarbital"
              ]
            },
            {
              "label": "Levetiracetam Standard Dose Arm ( Group B )",
              "type": "ACTIVE_COMPARATOR",
              "description": "Patients in Group B will receive levETIRAcetam at a loading dose of 30 mg/kg within a timeframe of 20 minutes from the start of seizures if the seizures don't stop. The same beginning dose will be repeated, in case the seizures don't stop within the 40-minute time frame, which leads to the treatment being considered a failure and a need to move to the second line of treatment. If seizures are controlled, patients will receive maintenance dose of levETIRAcetam 30 mg/kg/day IV or orally, divided into three daily doses.",
