            "primaryPurpose": "PREVENTION",
            "maskingInfo": {
              "masking": "DOUBLE"
            }
          },
          "enrollmentInfo": {
            "count": 30
          }
        },
        "armsInterventionsModule": {
          "interventions": [
            {
              "type": "DRUG",
              "name": "Levetiracetam, Keppra"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Age 18-65 years\n* Scheduled to receive a corticosteroid \"burst\" of at least 10 mg of prednisone equivalents and for at least 5 days duration\n* English- or Spanish-speaking\n\nExclusion Criteria:\n\n* History of allergic reaction or other contraindication to levetiracetam therapy\n* Other unstable medical conditions (e.g. recent myocardial infarction, renal failure, diabetes with poor glycemic control)\n* Pregnant or nursing women\n* History of mental retardation, dementia or other severe cognitive disorders",
          "healthyVolunteers": false,
          "sex": "ALL",
