          "briefTitle": "Levetiracetam Treatment of Neonatal Seizures: Safety and Efficacy Phase II Study",
          "officialTitle": "Levetiracetam Efficacy and Safety as First-line Treatment of Neonatal Seizures Occuring in Hypoxic-ischemic Encephalopathy Context",
          "acronym": "LEVNEONAT-1"
        },
        "statusModule": {
          "statusVerifiedDate": "2025-12",
          "overallStatus": "COMPLETED",
          "expandedAccessInfo": {
            "hasExpandedAccess": false
          },
          "startDateStruct": {
            "date": "2018-02-27",
            "type": "ACTUAL"
          },
          "primaryCompletionDateStruct": {
            "date": "2022-02-23",
            "type": "ACTUAL"
          },
