          "isUsExport": false
        },
        "descriptionModule": {
          "briefSummary": "This study evaluates the pharmacokinetic profile of levetiracetam in critically ill patients who have suffered a subarachnoid hemorrhage. The patients will be evaluated for development of augmented renal clearance and the effects and duration of effects this may have on levetiracetam clearance."
        },
        "conditionsModule": {
          "conditions": [
            "Subarachnoid Hemorrhage"
          ],
          "keywords": [
            "augmented renal clearance"
          ]
        },
        "designModule": {
          "studyType": "OBSERVATIONAL",
          "patientRegistry": false,
          "designInfo": {
            "observationalModel": "COHORT",
            "timePerspective": "PROSPECTIVE"
          },
          "enrollmentInfo": {
            "count": 15,
            "type": "ACTUAL"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Subarachnoid Hemorrhage",
              "interventionNames": [
                "Other: Pharmacokinetic modeling"
              ]
            }
          ],
          "interventions": [
            {
              "type": "OTHER",
              "name": "Pharmacokinetic modeling",
              "description": "Timed blood draws and urine collections to model drug clearance",
              "armGroupLabels": [
                "Subarachnoid Hemorrhage"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Change in systemic levetiracetam clearance over time",
              "description": "calculated systemic levetiracetam clearance (based on plasma concentrations) within 48 hours of initial presentation to the neurointensive care unit and every 5 days thereafter up to 20 days",
              "timeFrame": "0-20 days"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Change in urinary clearance of levetiracetam and creatinine",
              "description": "12-hour urine collections on day 0, 5, 10, 15, and 20, calculated creatinine based on 12-hour urine collections daily for 7 days following diagnosis of vasospasm, and calculation of direct renal clearance of levetiracitam based on urine collection",
              "timeFrame": "0-20 days"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Patients diagnosed with non-traumatic subarachnoid hemorrhage requiring levetiracetam for seizure prophylaxis or treatment\n* Presentation to University of Colorado Hospital within 48 hours of subarachnoid hemorrhage\n* Adults ages 18 to 89 years\n* Anticipated length of stay ≥ 48 hours\n* Informed consent provided by the patient or patient's designated medical proxy\n\nExclusion Criteria:\n\n* Pregnancy\n* Patients receiving renal replacement therapy\n* Brain death or imminent brain death expected ≤48 hours\n* Patient with history of nephrectomy or renal transplant",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "maximumAge": "89 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ],
          "studyPopulation": "Patients who have suffered a non-traumatic subarachnoid hemorrhage requiring strict intake and output monitoring and admission to the neuro-intensive care unit",
          "samplingMethod": "NON_PROBABILITY_SAMPLE"
        },
