          "briefTitle": "Comparison of Intravenous Brivaracetam Versus Levetiracetam in the Management of Status Epilepticus",
          "officialTitle": "Safety and Efficacy of Intravenous Brivaracetam Versus Levetiracetam in the Management of Status Epilepticus in Children"
        },
        "statusModule": {
          "statusVerifiedDate": "2025-08",
          "overallStatus": "COMPLETED",
          "expandedAccessInfo": {
