        "oversightModule": {
          "oversightHasDmc": false,
          "isFdaRegulatedDrug": false,
          "isFdaRegulatedDevice": false
        },
        "descriptionModule": {
          "briefSummary": "Brivaracetam is increasingly being studied in adult status epilepticus populations, evidence in pediatric patients remains sparse, with only limited case series and observational studies reporting favorable outcomes. This study aims at direct comparison between intravenous brivaracetam and levetiracetam in the acute management of pediatric status epilepticus.",
          "detailedDescription": "Given the urgent need for safe and effective alternatives in pediatric status epilepticus and the limited head-to-head data comparing intravenous brivaracetam with levetiracetam, especially in children, this study has been designed to evaluate their relative safety and efficacy. The research seeks to generate evidence that may help guide clinical decision-making and optimize outcomes in this vulnerable population."
        },
        "conditionsModule": {
          "conditions": [
            "Status Epilepticus"
          ]
        },
