              "label": "Brivaracetam group",
              "type": "EXPERIMENTAL",
              "description": "Patients received brivaracetam as a loading dose of 2 mg/kg (maximum 100 mg) diluted in 100 ml of normal saline infused over 10 minutes.",
              "interventionNames": [
                "Drug: Intravenous brivaracetam"
              ]
            },
            {
              "label": "Levetiracetam group",
              "type": "EXPERIMENTAL",
              "description": "Patients received levetiracetam as a loading dose of 40 mg/kg (maximum 3000 mg) diluted in 100 ml of normal saline infused over 10 minutes.",
              "interventionNames": [
                "Drug: Intravenous levetiracetam"
              ]
            }
          ],
          "interventions": [
            {
              "type": "DRUG",
              "name": "Intravenous brivaracetam",
              "description": "Patients received intravenous brivaracetam as a loading dose of 2 mg/kg (maximum 100 mg) diluted in 100 ml of normal saline infused over 10 minutes.",
