              "description": "Patients received intravenous levetiracetam as a loading dose of 40 mg/kg (maximum 3000 mg) diluted in 100 ml of normal saline infused over 10 minutes.",
              "armGroupLabels": [
                "Levetiracetam group"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Cessation of seizures",
              "description": "Cessation of seizures was labeled \"yes\" if cessation of clinical seizures occurred within 20-30 minutes of infusion without the need for additional antiseizure medication.",
              "timeFrame": "30 minutes"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Adverse Events",
              "description": "Labeled \"yes\" if any treatment-related adverse event reported 30 minutes post-infusion.",
              "timeFrame": "40 minutes"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Either gender\n* Aged one month to 16 years\n* Presenting with status epilepticus\n\nExclusion Criteria:\n\n* Previously received intravenous antiseizure medication for the current episode prior to presentation\n* Known hypersensitivity to study drugs\n* Hemodynamically unstable, requiring inotropic support before administration",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "1 Month",
          "maximumAge": "16 Years",
