        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Neuropsychological Test Battery (NTB)",
              "description": "Our primary cognitive outcome measure will be the mean z-score change relative to baseline on the NTB",
              "timeFrame": "From enrollment until the end of the treatment periods at 5 months"
            },
            {
              "measure": "Transcranial magnetic stimulation (TMS) resting motor threshold",
              "description": "Our primary TMS electrophysiological outcome measure of cerebral cortical excitability will be the change in the TMS resting input-output curve inflection point",
              "timeFrame": "From enrollment until the end of the treatment periods at 5 months"
            },
            {
              "measure": "Transcranial magnetic stimulation (TMS)-evoked electroencephalogram (EEG) hypersynchrony",
              "description": "Our primary electrophysiological measure of cerebral network excitability will be TMS-evoked EEG hypersynchrony with stimulation of parietal cortex",
              "timeFrame": "From enrollment until the end of the treatment periods at 5 months"
            },
            {
              "measure": "Resting-state electroencephalogram (EEG) beta band power",
              "description": "Our primary electrophysiological measure of local network function will be resting-state EEG power in the beta band",
              "timeFrame": "From enrollment until the end of the treatment periods at 5 months"
            },
            {
              "measure": "Resting-state electroencephalogram (EEG) beta band connectivity",
              "description": "Our primary electrophysiological measure of brain network interactions will be resting-state EEG functional connectivity in the beta band",
              "timeFrame": "From enrollment until the end of the treatment periods at 5 months"
            },
            {
              "measure": "Default-mode network resting-state functional magnetic resonance imaging (fMRI) functional connectivity",
              "description": "Our primary imaging measure of integrity of macroscopic brain networks will be mean resting-state fMRI functional connectivity within the default-mode network",
              "timeFrame": "From enrollment until the end of the treatment periods at 5 months"
            },
            {
              "measure": "Change in motor evoked potential (MEP) amplitude",
              "description": "Our primary transcranial magnetic stimulation (TMS) measure of plasticity in cortical excitability will be the change in MEP amplitude 10 minutes after intermittent theta-burst stimulation",
              "timeFrame": "From enrollment until the end of the treatment periods at 5 months"
            },
            {
              "measure": "Change in beta power after theta-burst stimulation",
              "description": "Our primary transcranial magnetic stimulation (TMS) measure of plasticity in cortical oscillations will be change in resting-state electroencephalogram (EEG) beta power after theta-burst stimulation",
              "timeFrame": "From enrollment until the end of the treatment periods at 5 months"
            }
          ],
          "otherOutcomes": [
            {
              "measure": "Transcranial magnetic stimulation (TMS)-evoked N45 electroencephalogram (EEG) potential",
              "description": "The change in the N45 component of the TMS-evoked EEG potential with motor cortex stimulation, will serve as a measure of target engagement with levetiracetam therapy, and as a covariate in subsequent analyses.",
              "timeFrame": "From enrollment until the end of the treatment periods at 5 months"
            },
            {
              "measure": "Interictal Epileptiform Discharges",
              "description": "The presence or absence of interictal epileptiform discharges on the baseline ambulatory 24-hour EEG or the baseline high-density EEG will be used a primary baseline measure of cortical hyperexcitability",
              "timeFrame": "Baseline"
            },
            {
              "measure": "Baseline motor cortical hyperexcitability",
              "description": "TMS-EMG Input-Output Curve Inflection Point: This is a relatively novel measure of hyperexcitability that shows increased excitability between AD and age-matched older adults. We will divide participants into tertiles based on their IO curve inflection point, and assess LEV effects by tertiles",
              "timeFrame": "Baseline"
            },
            {
              "measure": "Baseline TMS-EEG Parietal Cortical Excitability",
              "description": "Participants will be classified by baseline parietal cortical excitability as measured by TMS-EEG using source space modeling. We will use the same ROIs and time windows as used in our publication from this same dataset. This analysis provides a complementary measure of cortical excitability in a disease-relevant brain region. We will divide participants into tertiles and assess LEV effects by tertile.",
              "timeFrame": "Baseline"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\nInclusion Criteria for the Subjects with early Alzheimer's Disease (AD)\n\n* Age 50-90 years old.\n* On a stable dose of medications for memory loss including cholinesterase inhibitors (for example: donepezil, rivastigmine or memantine) as defined by 4 consecutive weeks of treatment at an unchanging dose\n* Meeting the National Institute of Neurological and Communicative Disorders and Stroke and the Alzheimer's Disease and Related Disorders Association (NINCDS-ADRDA) criteria for probable AD.\n* Mini Mental State Examination (MMSE) ≥ 20.\n* Positive amyloid status (as defined by cerebral spinal fluid biomarkers or amyloid positron emission tomography (PET) study.\n* Clinician Dementia Rating (CDR) of 0.5-1.0.\n\nInclusion Criteria for Healthy Control Subjects\n\n* Age 50-90 years old.\n* Normal neurologic exam\n* Mini Mental State Examination (MMSE) \\> 28\n* Clinician Dementia Rating (CDR) of 0\n\nExclusion Criteria:\n\nExclusion Criteria Subjects with early Alzheimer's Disease\n\n* Diagnosis of epilepsy, or immediate (1st degree relative) family history epilepsy with the exception of a single seizure of benign etiology (e.g. febrile seizures) in the judgment of a board-certified neurologist. Evidence of epileptiform discharges and electroencephalogram (EEG) abnormalities will be included;\n* Current or past history of any neurological disorder other than dementia, such as epilepsy, stroke (cortical stroke), progressive neurologic disease (e.g. multiple sclerosis) or intracranial brain lesions; and history of previous neurosurgery or head trauma that resulted in residual neurologic impairment. Non-cortical disease such as scattered white matter changes (including lacunar infarcts \\< 1 cm) and asymptomatic, subacute, cerebellar infarcts may be included upon review of a medically responsible neurologist. However, subjects with significant vascular disease, as defined by a score greater than 2 on the age-related white matter changes (ARWMC) scale, will be excluded.\n* Any current diagnosis of a major psychiatric disorder (e.g., schizophrenia, bipolar disorder) with the exception of depression. As co-morbidity of anxiety / depression in AD is high, anxiety / depression will not be an automatic exclusion. However, the study physician will assess any subject with a Geriatric Depression Score (GDS) score of 9 or above, and will exclude subjects with a past history of multiple psychiatric hospitalizations or suicide attempts, or current active suicidality.\n* Evidence of significant kidney impairment as defined as an estimated glomerular filtration rate (eGFR) \\<30\n* Medications will be reviewed by the responsible covering physician and a decision about inclusion will be made based on the participant's past medical history, drug dose, history of recent medication changes or duration of treatment, and combination with other central nervous system active drugs. Current use of an antiepileptic drug will be an absolute exclusion.\n\nExclusion Criteria Healthy Control Subjects\n\n* History of seizures, diagnosis of epilepsy, or immediate (1st degree relative) family history epilepsy with the exception of a single seizure of benign etiology (e.g. febrile seizures) in the judgment of a board-certified neurologist.\n* Current or past history of any neurological disorder, such as epilepsy, stroke (cortical stroke), progressive neurologic disease (e.g. multiple sclerosis) or intracranial brain lesions; and history of previous neurosurgery or head trauma that resulted in residual neurologic impairment.\n* Any current diagnosis of a major psychiatric disorder (e.g., schizophrenia, bipolar disorder, major depressive disorder).\n* Abnormal Neurologic or Cognitive exam\n* Use of medications that could alter cortical excitability, as determined by the investigators.\n\nExclusion Criteria for All Subjects regarding magnetic resonance imaging (MRI) and transcranial magnetic stimulation (TMS)\n\n* History of head trauma resulting in prolonged loss of consciousness.\n* Current history of poorly controlled headaches including chronic medication for migraine prevention.\n* History of fainting spells of unknown or undetermined etiology that might constitute seizures.\n* Chronic (particularly) uncontrolled medical conditions that may cause a medical emergency in case of a provoked seizure (cardiac malformation, cardiac dysrhythmia, asthma, etc.).\n* Any metal in the brain or skull (excluding dental fillings) or elsewhere in the body unless cleared by the responsible covering MD (e.g. MRI compatible joint replacement).\n* Any devices such as pacemaker, medication pump, nerve stimulator, ventriculo-peritoneal shunt unless cleared by the responsible covering physician.\n* Substance use disorders within the past six months.",
          "healthyVolunteers": true,
          "sex": "ALL",
          "minimumAge": "50 Years",
          "maximumAge": "90 Years",
