        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "To Determine if the Frequency of Premenstrual Dysphoric Disorder Differs Among Various Antiepileptic Drug Monotherapies.",
              "description": "Proportion of women who meet the Endicott Daily Record of Severity of Problems (DRSP) criteria for PMDD for two consecutive menstrual cycles in women with epilepsy and the control group (no epilepsy). To meet PMDD designation, women must have reached the PMDD criteria for both menstrual cycles. The less stringent threshold for PMDD designation referred to (1) having more severe symptoms during the premenstrual phase than during the midfollicular phase regardless of whether the midfollicular symptom scores exceeded the Endicott cutoff and (2) meeting the other three Endicott criteria",
              "timeFrame": "Assessment of PMDD Designation after two consecutive menstrual cycles"
            },
            {
              "measure": "Proportion of Women With PMDD in WWE and the Control Group",
              "description": "Proportion of women who meet the Endicott Daily Record of Severity of Problems (DRSP) criteria for PMDD for two consecutive menstrual cycles in women with epilepsy and the control group (no epilepsy). To meet PMDD designation, women must have reached the PMDD criteria for both menstrual cycles. The less stringent threshold for PMDD designation referred to (1) having more severe symptoms during the premenstrual phase than during the midfollicular phase regardless of whether the midfollicular symptom scores exceeded the Endicott cutoff and (2) meeting the other three Endicott criteria.",
              "timeFrame": "Assessment of PMDD Designation after two consecutive menstrual cycles"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Women with epilepsy, 18-45 years of age. Women will be on one of 4 established (≥ 3 months) AED monotherapies: LTG, CBZ, PHT or LEV and with documented therapeutic range serum AED level during the year prior to enrollment.\n* Normal Control women, 18-45 years of age, in good general health by history\n\nExclusion Criteria:\n\n* Concomitant use of prescribed or OTC reproductive hormones\n* Concomitant use of antidepressant and anxiolytic medications such as SSRIs, bupropion, tricyclics, benzodiazepines",
          "healthyVolunteers": true,
          "sex": "FEMALE",
          "minimumAge": "18 Years",
          "maximumAge": "45 Years",
          "stdAges": [
            "ADULT"
          ],
          "studyPopulation": "Three regional epilepsy centers",
