        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Percent change in catamenial seizure frequency."
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Responder rate"
            },
            {
              "measure": "Number of days free from seizures per week"
            },
            {
              "measure": "Ratio of catamenial seizure frequency to non-catamenial seizure frequency"
