        "oversightModule": {
          "oversightHasDmc": true
        },
        "descriptionModule": {
          "briefSummary": "To show that the use of intravenous levetiracetam(LEV;Keppra)for seizure prevention in patients in the Neuroscience Intensive Care Unit will result in fewer side effects compared to the current standard of care anticonvulsant and will be at least as effective as the current standard of care in preventing clinical and sub-clinical seizure activity.",
          "detailedDescription": "To show that the use of intravenous levetiracetam(LEV;Keppra)for seizure prophylaxis in the Neuroscience Intensive Care Unit will result in fewer adverse effects compared to the current standard of care anticonvulsant(phenytoin) and will be at least as effective as phenytoin in preventing clinical and sub-clinical seizure activity."
        },
        "conditionsModule": {
          "conditions": [
            "Traumatic Brain Injury",
            "Subarachnoid Hemorrhage"
          ],
          "keywords": [
            "Seizures",
            "Traumatic Brain Injury",
            "Subarachnoid Hemorrhage"
          ]
        },
        "designModule": {
          "studyType": "INTERVENTIONAL",
          "phases": [
            "PHASE4"
          ],
          "designInfo": {
            "allocation": "RANDOMIZED",
            "interventionModel": "PARALLEL",
            "primaryPurpose": "TREATMENT",
            "maskingInfo": {
              "masking": "SINGLE",
              "whoMasked": [
                "OUTCOMES_ASSESSOR"
              ]
            }
          },
          "enrollmentInfo": {
            "count": 52,
            "type": "ACTUAL"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Levetiracetam",
              "type": "ACTIVE_COMPARATOR",
              "description": "Group 1 - The levetiracetam (Keppra®) group will receive a loading dose of 20 mg/kg IV over 15 minutes (rounded to the nearest 250mg) up to a maximum of 2000 mg, then started on maintenance dose (1000 mg, IV BID)as prophylaxis for 7 days.",
              "interventionNames": [
                "Drug: Levetiracetam"
              ]
            },
            {
              "label": "Phenytoin",
              "type": "ACTIVE_COMPARATOR",
              "description": "Group 2-The phenytoin group will receive a loading dose of 20 mg/kg IV to a maximum of 2000mg, then started on maintenance dose at 5 mg/kg/day (rounded to nearest 100mg dose, IV, divided into three doses a day) as prophylaxis for 7 days. Phenytoin levels are to be checked daily and dose adjusted as needed to maintain therapeutic levels of 10-20 µg/dL.",
              "interventionNames": [
                "Drug: Phenytoin"
              ]
            }
          ],
          "interventions": [
            {
              "type": "DRUG",
              "name": "Levetiracetam",
              "description": "Levetiracetam group will receive a loading dose of 20 mg/kg IV(rounded to nearest 250mg) to a maximum of 2000mg, then started on maintenance dose (1000 mg,IV q 12h) as prophylaxis for seven days.",
              "armGroupLabels": [
                "Levetiracetam"
              ],
              "otherNames": [
                "Keppra"
              ]
            },
            {
              "type": "DRUG",
              "name": "Phenytoin",
              "description": "The group will receive a loading dose of fosphenytoin 20 mg/kg IV to a maximum of 2000 mg, then started on maintenance dose of 5mg/kg/day, rounded to nearest 100mg dose, IV, q 12h for seven days.",
              "armGroupLabels": [
                "Phenytoin"
              ],
              "otherNames": [
                "Dilantin"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Seizure Incidence",
              "description": "This was the number of patients in each group who demonstrated seizure activity during the course of the study",
              "timeFrame": "Duration of study, up to 6 months after the injury"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Extended Glasgow Outcome Score",
              "description": "This is an 8 point validated scale that measures disability after brain injury. It is assessed through an in person exam or by phone interview at hospital discharge, 3 months and 6 months after injury. The categories are: 1 = dead; 2 = vegetative state; 3 = severe disability, low level; 4 = severe disability, high level; 5 = moderate disability, low level; 6 = moderate disability, high level; 7 = good recovery - low level; 8 = good recovery - high level. Specific questions and activities are assessed to determine into which category the patient falls.",
              "timeFrame": "at discharge; 3 and 6 months following injury"
            },
            {
              "measure": "Disability Rating Scale (DRS)",
              "description": "The Disability rating scale (DRS) is frequently used in the rehabilitation literature as a measure of disability. It is a reliable, easily performed test that assesses 8 items (eye opening, verbalization, motor response, feeding, toileting, grooming, level of functioning, employability), and assigns each a numerical score ranging from 0 - 5 based on the category. The domains these 8 items are felt to assess include: alertness, cognition for self-care, dependence, and psychosocial adaptability. The scoring range is from 0-30, with increasing disability levels assigned to higher numerical values. The total DRS is then dichotomized into favorable (disability = none, mild, partial or moderate disability) and unfavorable (disability = moderately severe, severe, extremely severe, vegetative state, extreme vegetative state, death) outcomes. A DRS score of 0-6 was favorable, with any score greater than 6 categorized as unfavorable.",
              "timeFrame": "Discharge; 3 and 6 months following injury"
            },
            {
              "measure": "Incidence of Adverse Events",
              "timeFrame": "discharge; 3 and 6 months following injury"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Subjects with traumatic brain injury\n* Glasgow Coma Score (GCS) score 3-8(inclusive),or GCS motor score of 5 or less and abnormal admission CT scan showing intracranial pathology\n* Hemodynamically stable with a systolic BP \\>90 mm Hg\n* At least one reactive pupil\n* A negative pregnancy test in females\n* Age at least 18 years\n* Signed informed consent and Health Insurance Portability and Accountability Act (HIPAA) authorization for research form OR\n* Subjects with subarachnoid hemorrhage (SAH)\n* SAH documented by CT scan\n* Hunt-Hess grade 3-5, inclusive\n* Hemodynamically stable with a systolic BP\\> 90 mm Hg\n* At least one reactive pupil\n* A negative pregnancy test in females\n* Age of at least 18 years\n* Signed informed consent and HIPAA authorization for research form\n\nExclusion Criteria for enrollment\n\n* No venous access\n* Spinal cord injury\n* History of or CT confirmation of previous brain injury such as brain tumor, cerebral infarct, or spontaneous intracerebral hemorrhage\n* Hemodynamically unstable\n* Suspected anoxic events\n* Other peripheral trauma likely to result in liver failure\n* Positive pregnancy test in females\n* Age less than 18 years of age\n* Known hypersensitivity to any anticonvulsant\n* An injury that, in the opinion of the principal investigator, has a high likelihood of death within the first 72 hours.\n* Any treatment, condition, or injury that contraindicates treatment with LEV (levetiracetam) or phenytoin (PHT).\n* Inability to obtain signed informed consent or HIPAA authorization for research.",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ]
        },
        "contactsLocationsModule": {
          "overallOfficials": [
            {
              "name": "Lori Shutter, MD",
              "affiliation": "University of Pittsburgh",
              "role": "PRINCIPAL_INVESTIGATOR"
            }
          ],
