          "briefTitle": "Effect of Valproate Versus Levetiracetam Monotherapy on Reproductive Functions in Epileptic Males",
          "officialTitle": "Effect of Valproate Versus Levetiracetam Monotherapy on Reproductive Functions in Newly Diagnosed Epileptic Males"
        },
        "statusModule": {
          "statusVerifiedDate": "2019-05",
          "overallStatus": "COMPLETED",
