              "interventionNames": [
                "Drug: Effect of valporate on Reproductive Functions in Newly Diagnosed Epileptic Males"
              ]
            },
            {
              "label": "group 2",
              "description": "25 participants were treated by levetiracetam (LEV) with the same regimens of valproate as a monotherapy, with ages ranged from 20-45 years.",
              "interventionNames": [
                "Drug: Effect of levetiracetam on epileptic males reproductive function"
              ]
            }
          ],
          "interventions": [
            {
              "type": "DRUG",
