                "Effect of levepex on epileptic males reproductive function"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "the effect of valproate on males' sex hormones in newly diagnosed epileptic males.",
              "description": "percent of valproate treated patients with change in luteinizing hormone and follicle stimulating hormones and prolactin serum level.",
              "timeFrame": "8-weeks"
            },
            {
              "measure": "the effect of valproate on sperm parameters in newly diagnosed epileptic males.",
              "description": "percent of valproate treated patients with change in semen analysis parameters.",
              "timeFrame": "8-weeks"
            },
            {
              "measure": "the effect of levetiracetam on males' sex hormones in newly diagnosed epileptic males.",
