          "organization": {
            "fullName": "University of Rochester",
            "class": "OTHER"
          },
          "briefTitle": "Enteral Levetiracetam For Seizure Control In Pediatric Cerebral Malaria",
          "officialTitle": "A Dose-Escalation, Safety And Feasibility Study Of Enteral Levetiracetam For Seizure Control In Pediatric Cerebral Malaria",
          "acronym": "LVT1"
        },
        "statusModule": {
          "statusVerifiedDate": "2016-08",
          "overallStatus": "COMPLETED",
          "expandedAccessInfo": {
            "hasExpandedAccess": false
          },
          "startDateStruct": {
            "date": "2013-01"
          },
          "primaryCompletionDateStruct": {
            "date": "2013-07",
