            "class": "OTHER"
          },
          "briefTitle": "Levetiracetam for Benign Rolandic Epilepsy",
          "officialTitle": "Efficacy of Levetiracetam for Language Dysfunction Associated With Benign Epilepsy With Centrotemporal Spikes"
        },
        "statusModule": {
          "statusVerifiedDate": "2009-03",
          "overallStatus": "COMPLETED",
          "expandedAccessInfo": {
            "hasExpandedAccess": false
          },
          "startDateStruct": {
            "date": "2005-03"
          },
          "completionDateStruct": {
