            "type": "ACTUAL"
          },
          "studyFirstSubmitDate": "2005-09-10",
          "studyFirstSubmitQcDate": "2005-09-10",
          "studyFirstPostDateStruct": {
            "date": "2005-09-16",
            "type": "ESTIMATED"
          },
          "lastUpdateSubmitDate": "2009-03-26",
          "lastUpdatePostDateStruct": {
            "date": "2009-03-27",
            "type": "ESTIMATED"
          }
        },
        "sponsorCollaboratorsModule": {
          "leadSponsor": {
            "name": "Johns Hopkins University",
            "class": "OTHER"
          },
          "collaborators": [
            {
              "name": "UCB Pharma",
              "class": "INDUSTRY"
            }
          ]
        },
        "descriptionModule": {
          "briefSummary": "This study is designed to test if the language problems commonly seen in children with benign rolandic epilepsy would improve by switching anticonvulsants to levetiracetam.",
          "detailedDescription": "This is a 6 month study in which children on another anticonvulsant would have EEG, language testing, and a clinic visit at baseline. They would then be rapidly transitioned off of their current anticonvulsant and onto levetiracetam (Keppra). Repeat EEG and language testing would be done after 6 months to evaluate for improvement."
        },
        "conditionsModule": {
          "conditions": [
            "Epilepsy"
          ],
          "keywords": [
            "Epilepsy",
            "Benign rolandic",
            "Levetiracetam"
          ]
        },
        "designModule": {
          "studyType": "INTERVENTIONAL",
          "phases": [
            "PHASE4"
          ],
          "designInfo": {
