        "armsInterventionsModule": {
          "interventions": [
            {
              "type": "DRUG",
              "name": "Levetiracetam"
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Language improvement"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Seizure control"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Ages 6-12\n* Benign rolandic epilepsy\n* Language difficulties as reported by parents or teachers\n* On another anticonvulsant other than levetiracetam\n\nExclusion Criteria:\n\n* Prior use of levetiracetam\n* On 2 or more anticonvulsants\n* Language problems prior to epilepsy\n* Another seizure disorder\n* Status epilepticus within the past 6 months\n* Significant psychiatric disease\n* Progressive neurologic disease",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "6 Years",
          "maximumAge": "12 Years",
          "stdAges": [
            "CHILD"
          ]
        },
