        "oversightModule": {
          "oversightHasDmc": true
        },
        "descriptionModule": {
          "briefSummary": "Our primary objective is to compare two treatment options for prevention of seizures following a subarachnoid hemorrhage and determine if a short-course regimen of levetiracetam is as efficacious in the prevention of in-hospital seizures when compared to an extended course.",
          "detailedDescription": "This is a prospective, single-center, randomized, controlled trial. Patients admitted with spontaneous SAH (and meet enrollment criteria) will be randomized to either levetiracetam 1000 mg twice daily for 3 days or levetiracetam 1000mg twice daily until hospital discharge."
        },
        "conditionsModule": {
          "conditions": [
            "Subarachnoid Hemorrhage"
          ],
          "keywords": [
            "Subarachnoid Hemorrhage",
            "Seizure Prophylaxis",
            "Levetiracetam"
          ]
        },
        "designModule": {
