          },
          "briefTitle": "Levetiracetam in Early Psychosis",
          "officialTitle": "A Randomized, Double-blind, Placebo-controlled Trial Investigating the Effects of Levetiracetam in Early Psychosis"
        },
        "statusModule": {
          "statusVerifiedDate": "2022-10",
          "overallStatus": "COMPLETED",
