        "descriptionModule": {
          "briefSummary": "The main purpose of this study is to evaluate the effectiveness of the study drug lacosamide (200-600 mg/day) when added to a stable dose of levetiracetam (1000-3000 mg/day) with withdrawal of the concomitant sodium channel blocking-antiepileptic drug (AEDs) in subjects not well controlled on their current regimen."
        },
        "conditionsModule": {
          "conditions": [
            "Epilepsy"
          ],
          "keywords": [
