      "resultsSection": {
        "participantFlowModule": {
          "preAssignmentDetails": "The participant flow consists of subjects in the Safety Set (SS). The SS is all subjects who received at least 1 dose of lacosamide.",
          "recruitmentDetails": "The recruitment for the SP0980 study began in December 2011. It concluded in January 2014. This was a multicenter study with subjects enrolled by 30 sites across North America, 12 in Western Europe, 10 in Eastern Europe, and 2 in Oceania.",
          "groups": [
            {
              "id": "FG000",
              "title": "Lacosamide",
              "description": "Lacosamide will be added to levetiracetam while withdrawing the sodium channel blocking antiepileptic drug (AED).\n\nLacosamide: 50 mg and 100 mg lacosamide tablets will be combined and taken in two equal doses per day to provide the required total daily dosage of 100 - 600 mg/day. Subjects were titrated to a minimum of 200 mg/ day during the Treatment Period.\n\nMaximum duration of study drug administration is approximately 23 weeks."
            }
          ],
