        "descriptionModule": {
          "briefSummary": "The primary objective is to determine the most effective and/or the least effective treatment of benzodiazepine-refractory status epilepticus (SE) among patients older than 2 years. There are three active treatment arms being compared: fosphenytoin (FOS),levetiracetam (LEV), and valproic acid (VPA).\n\nThe second objective is comparison of three drugs with respect to secondary outcomes.\n\nThe final objective is to ensure that the trial is informative for treatment of established SE in children by describing the effectiveness, safety, and rate of adverse reactions of these drugs in children."
        },
        "conditionsModule": {
          "conditions": [
            "Benzodiazepine Refractory Status Epilepticus"
          ],
          "keywords": [
            "status epilepticus, refractory, benzodiazepine, fosphenytoin, levetiracetam, valproic acid"
          ]
        },
        "designModule": {
          "studyType": "INTERVENTIONAL",
          "phases": [
