          ],
          "designInfo": {
            "allocation": "RANDOMIZED",
            "interventionModel": "PARALLEL",
            "interventionModelDescription": "ESETT had 478 enrollments. They were 16 re-enrollers. This was an EFIC trial so all consents happened after treatment and all enrollments went through the same process of consent even if they were re-enrolled. Some information presented here only includes the first 400 patients since there was a prespecified stopping rule and the trial stopped early for futility.",
            "primaryPurpose": "TREATMENT",
