        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Fosphenytoin (FOS)",
              "type": "ACTIVE_COMPARATOR",
              "description": "Administer 20 mg/Kg fosphenytoin intravenously up to a maximum dose of 1500 mg ( 75 Kg) over 10 minutes. Those weighing more than 75 Kg receive a fixed dose of 1500 fosphenytoin over 10 minutes.",
              "interventionNames": [
                "Drug: Fosphenytoin"
              ]
            },
            {
              "label": "Valproic acid",
              "type": "ACTIVE_COMPARATOR",
              "description": "Administer 40 mg/Kg valproic acid intravenously up to a maximum dose of 3000 mg (75 Kg) over 10 minutes. Those weighing more than 75 Kg receive a fixed dose of 3000 valproic acidover 10 minutes.",
              "interventionNames": [
                "Drug: Valproic acid"
              ]
            },
            {
              "label": "Levetiracetam",
              "type": "ACTIVE_COMPARATOR",
              "description": "Administer 60 mg/Kg levetiracetam intravenously up to a maximum dose of 4500 mg ( 75 Kg) over 10 minutes. Those weighing more than 75 Kg receive a fixed dose of 4500 levetiracetam over 10 minutes.",
              "interventionNames": [
                "Drug: Levetiracetam"
              ]
            }
          ],
