        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Number of Participants With Clinical Cessation of Status Epilepticus - Intention to Treat",
              "description": "Determined by the absence of clinically apparent seizures and improving consciousness at 1 hour without other anticonvulsant medications. Intention to treat",
              "timeFrame": "Within 60 minutes after the start of study drug infusion"
            },
            {
              "measure": "Number of Participants With Clinical Cessation of Status Epilepticus - Per-protocol Analysis",
              "description": "Determined by the absence of clinically apparent seizures and improving consciousness at 1 hour without other anticonvulsant medications. Per-protocol analysis",
              "timeFrame": "Within 60 minutes after the start of study drug infusion"
            },
            {
              "measure": "Number of Participants With Clinical Cessation of Status Epilepticus - Adjudicated Outcomes Analysis",
              "description": "Determined by the absence of clinically apparent seizures and improving consciousness at 1 hour without other anticonvulsant medications. The Adjudicated outcomes analysis is different from Outcome measure 1 because a central clinical phenomenology core of four neurologists adjudicated from the medical records the time to seizure cessation, the time in status epilepticus before trial-drug initiation, and the cause of the seizure. For each enrollment, two neurologists from this core group conducted independent initial reviews and then determined a consensus or consulted a third adjudicator, as needed. Adjudicators were unaware of the treatment assignments and made determinations by medical record review.",
              "timeFrame": "Within 60 minutes after the start of study drug infusion"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Number of Participants With Admission to Intensive Care Unit",
              "description": "ICU admission is recorded as occurring only if the ICU is the initial inpatient unit for the patient.",
              "timeFrame": "Admission to intensive care unit after start of study drug infusion, where the ICU is the initial inpatient unit for the patient"
            },
            {
              "measure": "Length of ICU Stay",
              "description": "Length of stay is determined by the number of calendar days after the day of ED arrival until hospital discharge or subject end-of-study.",
              "timeFrame": "number of calendar days after the day of ED arrival until hospital discharge or subject end-of-study"
            },
            {
              "measure": "Minutes From Start of Trial Drug Infusion to Termination of Seizures for Patients With Treatment Success",
              "description": "The time to termination of seizures is the interval from the start of study drug infusion to cessation of clinically apparent seizure in those who meet the primary outcome.",
              "timeFrame": "start of drug infusion to seizure cessation"
            },
            {
              "measure": "Number of Participants With Seizure Cessation Within 20 Minutes for Patients With Treatment Success",
              "description": "Number of participants with seizure cessation within 20 minutes of study drug initiation for patients with treatment success. This outcome measure was only reported in the Supplementary materials to the Primary Paper.",
              "timeFrame": "within 20 minutes"
            },
            {
              "measure": "Length of Hospital Stay",
              "description": "Length of hospital stay in days",
              "timeFrame": "length of hospital stay"
            }
          ],
          "otherOutcomes": [
            {
              "measure": "Number of Participants With Safety Outcome: Life Threatening Hypotension",
              "description": "Life-threatening hypotension within 60 minutes of the start of study drug infusion",
              "timeFrame": "within 60 minutes of the start of study drug infusion"
            },
            {
              "measure": "Number of Participants With Safety Outcome: Life-threatening Cardiac Arrhythmia",
              "description": "Life-threatening cardiac arrhythmia within 60 minutes of the start of study drug infusion",
              "timeFrame": "within 60 minutes of the start of study drug infusion"
            },
            {
              "measure": "Number of Participants With Safety Outcome: Endotracheal Intubation",
              "description": "Endotracheal intubation within 60 minutes of start of study drug infusion",
              "timeFrame": "within 60 minutes of start of study drug infusion"
            },
            {
              "measure": "Number of Participants With Safety Outcome: Acute Anaphylaxis",
              "description": "Acute anaphylaxis is defined as a clinical presentation consistent with life threatening allergic reaction occurring within 6 hours of the start of study drug infusions and manifested as urticaria in combination with either (1) a systolic blood pressure of \\< 90 mmHg sustained for greater than 5 minutes, or (2) objective evidence of airway obstruction, and for which the patient was treated with antihistamines and/or steroids.",
              "timeFrame": "within 6 hours of the start of study drug infusions"
            },
            {
              "measure": "Number of Participants With Safety Outcome: Acute Respiratory Depression",
              "description": "Respiratory depression is defined as impairment of ventilation or oxygenation necessitating definitive endotracheal intubation and mechanical ventilation. It is distinct from intubations performed only for airway protection in those with decreased levels of consciousness. It does not include those getting only supraglottic airways or transient bag-valve-mask support.",
              "timeFrame": "24 hours"
            },
            {
              "measure": "Number of Participants With Safety Outcome: Hepatic Transaminase or Ammonia Elevations",
              "description": "Safety outcome: Hepatic transaminase or ammonia elevations",
              "timeFrame": "24 hours"
            },
            {
              "measure": "Number of Participants With Safety Outcome: Purple Glove Syndrome",
              "description": "Purple glove syndrome is defined as the presence of all three of the findings of the objective edema: discoloration, and pain in the distal extremity in which study drug was administered, with or without known extravasation, and for which there is no other evident etiology.",
              "timeFrame": "24 hours"
            },
            {
              "measure": "Number of Participants With Safety Outcome: Death",
              "description": "Safety outcome: Death",
              "timeFrame": "30 days"
            },
            {
              "measure": "Number of Participants With Safety Outcome: Acute Seizure Recurrence",
              "description": "acute seizure recurrence 60 minutes to 12 hours after start of study drug infusion",
              "timeFrame": "60 minutes to 12 hours after start of study drug infusion"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria: Patient witnessed to seize for greater than 5 minute duration prior to treatment with study drug; Patient received adequate dose of benzodiazepines. The last dose of a benzo was administered in the 5-30 minutes prior to study drug administration. The doses may be divided.; continued or recurring seizure in the Emergency Department; Age 2 years or older\n\nExclusion Criteria:Known pregnancy; Prisoner; Opt-out identification; Treatment with a second line anticonvulsant (FOS, PHT, VPA, LEV, phenobarbital or other agents defined in the MoP) for this episode of SE; Treatment with sedatives with anticonvulsant properties other than benzodiazepines (propofol, etomidate, ketamine or other agents defined in the MoP); Endotracheal intubation; Acute traumatic brain injury; Known metabolic disorder; Known liver disease; Known severe renal impairment; Known allergy or other known contraindication to FOS, PHT, LEV, or VPA; Hypoglycemia \\< 50 mg/dL; Hyperglycemia \\> 400 mg/dL; Cardiac arrest and post-anoxic seizures",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "2 Years",
          "stdAges": [
            "CHILD",
            "ADULT",
            "OLDER_ADULT"
          ]
        },
