      "resultsSection": {
        "participantFlowModule": {
          "recruitmentDetails": "ESETT had a total of 478 enrollments. This number includes 16 re-enrollers. This was an EFIC trial so all consents happened after treatment. All enrollments went through the same process of consent even if they were reenrolled. The first 400 patients were used in several parts of analyses since the trial stopped early for futility (prespecified).",
          "groups": [
            {
              "id": "FG000",
              "title": "Fosphenytoin (FOS)",
              "description": "Administer 20 mg/Kg fosphenytoin intravenously up to a maximum dose of 1500 mg ( 75 Kg) over 10 minutes. Those weighing more than 75 Kg receive a fixed dose of 1500 fosphenytoin over 10 minutes.\n\nFosphenytoin"
            },
            {
              "id": "FG001",
              "title": "Valproic Acid",
              "description": "Administer 40 mg/Kg valproic acid intravenously up to a maximum dose of 3000 mg (75 Kg) over 10 minutes. Those weighing more than 75 Kg receive a fixed dose of 3000 valproic acidover 10 minutes.\n\nValproic acid"
            },
            {
              "id": "FG002",
              "title": "Levetiracetam",
              "description": "Administer 60 mg/Kg levetiracetam intravenously up to a maximum dose of 4500 mg ( 75 Kg) over 10 minutes. Those weighing more than 75 Kg receive a fixed dose of 4500 levetiracetam over 10 minutes.\n\nLevetiracetam"
            }
          ],
