          "briefTitle": "A Comparative Study of Artekin With Standard Malarial Treatment Regimes in Afghanistan",
          "officialTitle": "Randomized Clinical Trial of the Efficacy and Safety of Dihydroartimisinine+Papiraquine (Artekin) Compared With First Line Drugs for Treatment of Vivax and Uncomplicated Falciparum Malaria in Afghanistan"
        },
        "statusModule": {
          "statusVerifiedDate": "2018-05",
          "overallStatus": "COMPLETED",
          "expandedAccessInfo": {
