          },
          "studyFirstSubmitDate": "2012-01-13",
          "studyFirstSubmitQcDate": "2012-01-13",
          "studyFirstPostDateStruct": {
            "date": "2012-01-18",
            "type": "ESTIMATED"
          },
          "lastUpdateSubmitDate": "2019-12-13",
          "lastUpdatePostDateStruct": {
            "date": "2019-12-16",
            "type": "ACTUAL"
          }
        },
        "sponsorCollaboratorsModule": {
          "responsibleParty": {
            "type": "SPONSOR"
          },
          "leadSponsor": {
            "name": "National Institute of Allergy and Infectious Diseases (NIAID)",
            "class": "NIH"
          }
        },
        "descriptionModule": {
          "briefSummary": "Background:\n\n\\- Some clinical trials require larger amounts of plasma and white blood cells than can be collected through simple blood donations. Apheresis is a procedure used to collect parts of the blood for study and return the rest of the blood to the donor. Healthy volunteers who provide plasma and white blood cells for study may need to give multiple donations. Researchers want to use apheresis to collect plasma and white blood cells from healthy volunteers in Mali.\n\nObjectives:\n\n\\- To collect plasma and white blood cells from healthy volunteers in Mali.\n\nEligibility:\n\n* Healthy volunteers between 18 and 55 years of age.\n* Volunteers must be in National Institute of Allergy and Infectious Diseases clinical trials.\n\nDesign:\n\n* Participants will be screened with a physical exam and medical history. They will also provide basic blood and urine samples.\n* Participants will have apheresis to collect plasma and white blood cells for study. Before each collection, they will provide a small blood sample for testing. They will be monitored during and after donation to prevent side effects.\n* Under this protocol, participants may have apheresis up to six times per year.\n* No treatment will be provided as part of this protocol....",
          "detailedDescription": "To carry out in vitro research procedures on plasma or leukocyte components of whole blood, it is often necessary to obtain larger quantities of plasma or leukocytes than can be safely obtained by simple phlebotomy. These components can be easily and safely obtained using a well-established standard apheresis procedure that is in common use at the National Institutes of Health Apheresis Unit. This protocol describes the implementation of the same apheresis procedure at the National Blood Transfusion Center in Bamako, Mali. This is not a research protocol per se, but rather an adjunct protocol which allows healthy donors 18-55 years of age to undergo apheresis. Subjects must already be enrolled in another protocol which has been approved by the National Institute of Allergy and Infectious Diseases Institutional Review Board and the Faculty of Medicine, Pharmacy, and Odonto-Stomatology Ethics Committee."
        },
        "conditionsModule": {
          "conditions": [
            "Malaria"
          ],
          "keywords": [
            "Apheresis",
            "Leukocytes",
            "Plasma",
            "Plamodium Falciparum Malaria",
            "Immunology"
          ]
        },
        "designModule": {
          "studyType": "OBSERVATIONAL",
          "designInfo": {
            "timePerspective": "PROSPECTIVE"
          },
          "enrollmentInfo": {
            "count": 0,
            "type": "ACTUAL"
          }
        },
        "eligibilityModule": {
          "eligibilityCriteria": "* INCLUSION CRITERIA:\n\nIndividuals 18-55 years of age are eligible to enter the study if they:\n\n* Are enrolled on another NIAID/FMPOS-approved protocol.\n* Weigh greater than or equal to 50 kg.\n* Agree to have blood specimens stored for future studies.\n* Agree to undergo genetic testing.\n* Agree to undergo HIV, hepatitis B, and hepatitis C virus testing.\n\nEXCLUSION CRITERIA:\n\nThe following criteria are exclusionary:\n\n* Positive at screening for HIV, hepatitis B, and/or hepatitis C.\n* Cardiovascular instability (blood pressure \\<90/50 or \\>180/100; pulse \\<40 or \\>110.\n* Inadequate peripheral venous access.\n* Anemia (hemoglobin \\<11 g/dL).\n* Current use of corticosteroids or other immunosuppressants.\n* Underlying heart disease, lung disease, bleeding disorder, or other conditions that, in the judgment of the investigator, contraindicates apheresis.\n* Temperature greater than or equal to 37.5 degree C or other clinical evidence of an acute infection.\n* Currently pregnant or breastfeeding.",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
