            "type": "ACTUAL"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Control",
              "type": "NO_INTERVENTION",
              "description": "1. Information and Education Campaigns (IEC) campaigns will formally encourage breeding site management through; good practice household-level water storage (covering and cleaning of water storage containers) and waste management (removal of potential breeding sites in and around the home).\n2. Epidemiological surveillance: test and treat malaria cases in children 6 - 10 years of age"
            },
            {
              "label": "Mesh",
              "type": "EXPERIMENTAL",
              "description": "1. Information and Education Campaigns (IEC) campaigns will formally encourage breeding site management through; good practice household-level water storage (covering and cleaning of water storage containers) and waste management (removal of potential breeding sites in and around the home).\n2. Epidemiological surveillance: test and treat malaria cases in children 6 - 10 years of age\n3. Mesh product distributed to households",
              "interventionNames": [
                "Combination Product: Mesh - spatial repellent impregnated with transfluthrin (2500mg)",
                "Behavioral: Information and Education Campaigns (IEC)",
                "Diagnostic Test: test and treat malaria cases"
              ]
            }
          ],
          "interventions": [
            {
              "type": "COMBINATION_PRODUCT",
              "name": "Mesh - spatial repellent impregnated with transfluthrin (2500mg)",
              "description": "Mesh is one of the first spatial repellent tools to provide long-lasting protection to users, with predicted efficacy of 6-months. The active ingredient of Mesh is transfluthrin, a fast-acting volatile pyrethroid with low persistency, which can act either by killing or via sublethal toxicity that causes deviation (repellency) in host attraction, reducing host-contact and risk of infectious bites. The chemical passively releases into the air and interacts with vector odour receptors causing irritation. The design of Mesh is simple with a transfluthrin-infused sheet protected by plastic mesh and encased in a plastic frame.\n\nMesh will be distributed to the intervention arm only.",
              "armGroupLabels": [
                "Mesh"
              ]
            },
            {
              "type": "BEHAVIORAL",
              "name": "Information and Education Campaigns (IEC)",
              "description": "IEC campaigns will formally encourage breeding site management through; good practice household-level water storage (covering and cleaning of water storage containers) and waste management (removal of potential breeding sites in and around the home) using leaflets and word of mouth. IEC will be conducted in both arms.",
              "armGroupLabels": [
                "Mesh"
              ]
            },
            {
              "type": "DIAGNOSTIC_TEST",
              "name": "test and treat malaria cases",
              "description": "All children in the cohort (both arms) will be tested by rapid diagnostic testing (RDT) monthly. If any children test positive, they will be treated with a course of 3-day artemisinin combination therapy (ACT) according to standard protocol and local guidelines. All children in the cohort will receive ACT to provide clearance of any malaria parasites during the baseline of the study.",
              "armGroupLabels": [
                "Mesh"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "entomological outcome: vector density",
              "description": "the relative infestation rate of disease vectors (females of any of Anopheles malaria vectors, Aedes aegypti, or phlebotomine sand flies",
              "timeFrame": "7 months"
            },
            {
              "measure": "epidemiological outcome: malaria incidence",
              "description": "Malaria incidence will be estimated as the total number of malaria episodes per person over the course of the trial.",
              "timeFrame": "7 months"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "feasibility, acceptance and uptake of Mesh",
              "description": "To measure community and household acceptance and uptake of Mesh, a questionnaire will be conducted with the Mesh-receiving households.",
              "timeFrame": "7 months"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Shelters with 1 or more children from 6-10 years old\n* Shelters with an adult/head of the household\n\nExclusion Criteria:\n\n* Shelters without children from 6-10 years old",
