          "briefTitle": "IPT of Malaria With SP in Different Zones of Drug Resistance in Rwanda",
          "officialTitle": "Intermittent Preventive Treatment of Malaria With Sulfadoxine-Pyrimethamine in Different Zones of Drug Resistance in Rwanda"
        },
        "statusModule": {
          "statusVerifiedDate": "2010-09",
