        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "malaria infection will be defined as the presence of asexual stage parasites on thick smears made with maternal side placental blood and Maternal peripheral blood",
              "timeFrame": "maternal placental blood at delivery; maternal peripheral blood at monthly visits between 16 weeks of gestation and delivery"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "LBW = birth weight <2,500 grams",
              "timeFrame": "at delivery"
            },
            {
              "measure": "Premature delivery = delivery prior to 37 weeks gestation",
              "timeFrame": "at delivery"
            },
            {
              "measure": "Spontaneous miscarriage = any spontaneous abortion before the end of gestation",
              "timeFrame": "at delivery"
            },
            {
              "measure": "Stillbirth",
              "timeFrame": "at delivery"
            },
            {
              "measure": "Cord blood parasitaemia = presence of asexual stage parasites in thick smears",
              "timeFrame": "at delivery"
            },
            {
              "measure": "Neonatal death = infant death within the first 28 days of life",
              "timeFrame": "7days and 6 weeks after delivery"
            },
            {
              "measure": "Maternal anemia = Hb <11.0 g/dL",
              "timeFrame": "at monthly visits between 16 weeks of gestation and delivery"
            },
            {
              "measure": "Maternal severe anemia = Hb <6 g/dL",
              "timeFrame": "at monthly visits between 16 weeks of gestation and delivery"
            },
            {
              "measure": "Symptomatic maternal malaria infection = axillary temperature 37.5°C and asexual parasitaemia",
              "timeFrame": "at monthly visits between 16 weeks of gestation and delivery"
            },
            {
              "measure": "Severe maternal adverse reactions to SP = severe cutaneous reactions (e.g., erythema multiform, Stevens-Johnson syndrome, or toxic epidermal necrolysis)",
              "timeFrame": "at monthly visits between 16 weeks of gestation and delivery plus at day 7 and week 6 after delivery"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n1. Pregnant women between 16-28 weeks of gestation;\n2. Residence within the catchment's area of the health facility;\n3. Willing to deliver at the health facility;\n4. Willing to ; adhere to all requirements of the study;\n5. Willing to provide written informed consent;\n6. Aged 21 years and above\n\nExclusion Criteria:\n\n1. Severe anemia (Hb \\< 6 g/dL)\n2. History of allergic reactions to sulfa drugs;\n3. Taking other sulfa drugs as CTX;\n4. History of known pregnancy complications (e.g. breech presentation, severe pre-eclampsia, prior caesarian section);\n5. History or presence of major illnesses likely to influence pregnancy outcome including diabetes mellitus, severe renal or heart disease, or active tuberculosis, prior to randomization;\n6. Any significant illness that requires hospitalization;\n7. Intent to move out of the study catchment's area before delivery or deliver at relative's home out of the catchment's area;\n8. Prior enrollment in the study or concurrent enrollment in another study",
          "healthyVolunteers": true,
