        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "LIG optimum detection of hypoglycemia",
              "description": "To determine the Low Interstitial Glucose (LIG) parameters that have the optimum performance for detection and identification of patient-reported-hypoglycemia (PRH); 〖LIG〗\\_PRH (h\\_opt,t\\_opt).",
              "timeFrame": "week 10"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Secondary outcome 1",
              "description": "To evaluate the impact of symptomatic and asymptomatic hypoglycaemia on different domains of Quality of Life (QoL) and health economic variables measured by a bespoke mobile phone application.\n\nWe will use the definition of LIG identified in the primary objective, 〖LIG〗\\_PRH (h\\_opt,t\\_opt), to evaluate the impact of symptomatic and asymptomatic hypoglycaemia on various outcome variables. To do this, we will divide the days into one of 4 categories LIG-PRH- :no hypoglycaemia LIG+PRH- :asymptomatic biochemical hypoglycaemia ( CGM false positive) LIG+PRH+ :symptomatic biochemical hypoglycaemia LIG-PRH+ :symptomatic without biochemical hypoglycaemia (CGM false negative) We will then compare the scores in different domains collected on the app ( eg reported mood, quality of sleep, alertness, productivity, time off work) between the 4 categories.",
              "timeFrame": "week 10"
            },
            {
              "measure": "Secondary outcome 2",
              "description": "To evaluate the impact of adding co-variates such as change of glucose for 30 minutes prior to the event and area under the curve to the threshold and duration parameters to see if this can improve the sensitivity and specificity of 〖LIG〗\\_PRH (h\\_opt,t\\_opt),",
              "timeFrame": "week 10"
            },
            {
              "measure": "Secondary outcome 3",
              "description": "To evaluate the impact on these optimal parameters \\[〖LIG〗\\_PRH (h\\_opt,t\\_opt \\] on Type of diabetes ( Type 1 with normal awareness, Type 2, Type 1 with impaired awareness) Awake vs sleeping ( as determined by Fitbit) Usual Mode of glucose monitoring (SMBG vs Flash vs CGM) Rate of 〖LIG〗\\_PRH during the study",
              "timeFrame": "week 10"
            },
            {
              "measure": "Secondary outcome 4",
              "description": "To evaluate the impact of the rate of 〖LIG〗\\_PRH over the whole study duration on Rate of Patient reported hypoglycaemia ( non-severe) Rate of severe hypoglycaemia Overall EQ-5D-5L scores WPAI ( productivity) PROMIS - (sleep quality) Hypo fear scores Baseline C-peptide levels",
              "timeFrame": "week 10"
            },
            {
              "measure": "Secondary outcome 5",
              "description": "To determine the parameters (threshold and duration) of low interstitial glucose (LIG) that best identify a pre-specified reduction/ change in QoL. \\[ 0.07 reduction in EQ-5D-5L\\] 〖LIG〗\\_(EQ-5D) (h\\_opt,t\\_opt).",
              "timeFrame": "week 10"
            },
            {
              "measure": "Secondary outcome 6",
              "description": "To determine the parameters ( threshold and duration) of low interstitial glucose (LIG) that best identify a pre-specified health economic outcome. \\[1.5 hour loss of effective work/ activity\\] 〖LIG〗\\_productivity (h\\_opt,t\\_opt).",
              "timeFrame": "week 10"
            },
            {
              "measure": "Secondary outcome 7",
              "description": "Determining the predictors of 〖LIG〗\\_PRH by looking at variables such as mean glucose, variability, activity (step count and intensity).",
              "timeFrame": "week 10"
            },
            {
              "measure": "Secondary outcome 8",
              "description": "We will evaluate the impact of activity ( step count) on the risk of 〖LIG〗\\_PRH the following night. A generalized linear mixed models (GLMM) with step count as the independent variable and the rate of LIG\\_PRH as the response variable will address this research question",
              "timeFrame": "week 10"
            },
            {
              "measure": "Secondary outcome 9",
              "description": "We will try to understand some of the causes of hypoglycaemia. To do this we will look at the 4 hours prior to every available 〖LIG〗\\_PRH (h\\_opt,t\\_opt) and PRH and describe the category of events (if also insulin data is available) by classifying them into those with Bolus within range \\[ \\< 10 mmol/l\\] within 4 hours Bolus and correction \\[ \\> 10 mmol/l \\] within 4 hours No bolus within 4 hours Activity \\[ as identified by the Fitbit charge 3\\] within 2 hours.",
              "timeFrame": "week 10"
            },
            {
              "measure": "Secondary outcome 10",
              "description": "Evaluating the effect of personality (assessed by DS-14) on number and severity of hypoglycaemia and the effect of hypoglycaemia on quality of life measures",
              "timeFrame": "week 10"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n1. Age 18 - 85 years\n2. HbA1c 5 - 10% \\[31 - 86 mmol/mol\\]\n3. Confirmed diagnosis of type 1 or type 2 diabetes\n4. Using \\> 1 injection of insulin / day or insulin pump.\n5. Ability to provide written informed consent\n6. Performing regular SMBG \\[ \\> 1 / day on a 4-week download\\] . For those using flash or continuous glucose monitoring, this should be used at least 70% of the time.\n7. At least 1 episode of hypoglycaemia \\[ either biochemical or symptomatic\\] in the last month\n8. On stable therapy for at least 3 months.\n9. Willing to complete study procedures including wearing the Fitbit and CGM devices and completing the EMA questionnaires on the uMotif app three times a day for 10 weeks ( we expect minimum 80% data completeness)\n\nExclusion Criteria:\n\n1. Concurrent conditions that can affect glucose readings \\[renal impairment GFR \\< 30 ml/min, hepatic impairment, untreated adrenal or thyroid insufficiency, as judged by the investigator.\n2. Severe cognitive impairment or psychological illness that can impair performance of EMA tasks, visual impairment that will preclude use of the EMA or sensors.\n3. Severe psychiatric / psychological illness including extreme fear of hypo- or hyper- glycaemia ( in the opinion of the investigator)\n4. Pregnant or plans for pregnancy in the next 6 months\n5. Use of automated insulin delivery systems such as closed loop or automated threshold suspend or predictive low glucose suspend insulin pumps.\n6. Known allergies to adhesives required for the CGM systems\n7. People who work regular night shifts\n8. Any other condition which in the opinion of the study team would impair their ability to complete the study",
          "sex": "ALL",
          "minimumAge": "18 Years",
          "maximumAge": "85 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ],
          "studyPopulation": "A total of 600 participants will be recruited in the following categories.\n\n* Type 1 diabetes with intact awareness of hypoglycaemia \\[ Gold score \\< 3\\]; a maximum of 50% will be using flash or continuous glucose monitoring \\[ n = 200 \\]\n* Type 1 diabetes with impaired awareness of hypoglycaemia \\[ gold score \\> 4 \\];\\[n=50\\] a maximum of 50% will be using flash or continuous glucose monitoring\n* Type 2 diabetes on \\> 1 injections; a minimum of 25% of these participants will be over 60 years of age; a maximum of 50% will be using flash or continuous glucose monitoring. \\[n=350\\]",
          "samplingMethod": "NON_PROBABILITY_SAMPLE"
        },
