          "briefTitle": "School-Based Eating Disorder Prevention",
          "officialTitle": "Universal Prevention Program \"Claudia Carraro\" for Improving Body Image and Promoting Healthy Lifestyles in Adolescent Boys and Girls: a Cluster Randomized Controlled Trial With 24-week Follow-up"
        },
        "statusModule": {
          "statusVerifiedDate": "2025-09",
          "overallStatus": "COMPLETED",
          "expandedAccessInfo": {
            "hasExpandedAccess": false
          },
          "startDateStruct": {
            "date": "2020-01-10",
