          "interventions": [
            {
              "type": "OTHER",
              "name": "impliminting Online Distance Learning",
              "description": "as a result of (COVID-19) social distancing measures, the Online Distance Learning will be implemented without prior planning for undergraduate nursing students",
              "armGroupLabels": [
                "group of students who are learning by Online Distance"
              ]
            }
          ]
