          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "OFR Team Practice as Usual",
              "type": "NO_INTERVENTION",
              "description": "Data are collected regarding standard OFR Team practice and outcomes before implementation of the FORTRESS Intervention"
            },
            {
              "label": "FORTRESS",
              "type": "EXPERIMENTAL",
              "description": "Participating counties receive both training in data-driven decision making and inventory of overdose-prevention strategies",
              "interventionNames": [
                "Behavioral: Data-Driven Decision Making (DDDM)",
                "Behavioral: Overdose-prevention strategies inventory"
              ]
            }
          ],
          "interventions": [
            {
              "type": "BEHAVIORAL",
              "name": "Data-Driven Decision Making (DDDM)",
              "description": "The intervention consists of providing real-time data on overdose touchpoints to OFRs and training in DDDM for continuous quality improvement cycles, leading to improved OFR recommendations and implementation of overdose prevention strategies.",
              "armGroupLabels": [
                "FORTRESS"
              ]
            },
            {
              "type": "BEHAVIORAL",
              "name": "Overdose-prevention strategies inventory",
              "description": "A list of overdose prevention and harm reduction strategies will be provided to OFRs for possible implementation, depending on local needs and final dashboard development.",
              "armGroupLabels": [
                "FORTRESS"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Organizational readiness to implement change",
              "description": "12-items that assess perceived readiness to implement new innovations that will be administered to 15 OFR team members and 5 system leaders per each of 18 counties.",
              "timeFrame": "Months 18, 24, 30, 36, 42, 48, 54, & 60"
            },
            {
              "measure": "Cultural Exchange Inventory (adapted to evaluate OFR team alliance)",
              "description": "15-items that measure knowledge and attitudes between organizations that will be administered to 15 OFR team members and 5 system leaders per each of 18 counties.",
              "timeFrame": "Months 18, 24, 30, 36, 42, 48, 54, & 60"
            },
            {
              "measure": "Harm reduction acceptability scale",
              "description": "25-items that measures the adoption of a harm reduction approach in responding to people who use substances that will be administered to 15 OFR team members and 5 system leaders per each of 18 counties.",
              "timeFrame": "Months 18, 24, 30, 36, 42, 48, 54, & 60"
            },
            {
              "measure": "Systems Usability Scale",
              "description": "10-items that assesses the usability of dashboard for OFRs that will be administered to 15 OFR team members and 5 system leaders per each of 18 counties.",
              "timeFrame": "Months 18, 24, 30, 36, 42, 48, 54, & 60"
            },
            {
              "measure": "Stages of Implementation Completion (SIC)",
              "description": "The SIC is a measure of implementation process fidelity and allows for continuous measurement of implementation success. The SIC is an observation-based assessment tool that qualitatively measures intervention implementation process and fidelity. Assessment of the SIC results will be ongoing across the intervention time period and into sustainment.",
              "timeFrame": "Baseline through study completion, an average of 5 years"
            },
            {
              "measure": "OFR Fidelity Tool",
              "description": "To be developed fidelity assessment tool that will be completed by each OFR facilitator after a monthly meeting.",
              "timeFrame": "Months 18-54"
            },
            {
              "measure": "Dashboard Aggregate Usage",
              "description": "Web Cookies and anonymized IDs for each unique user to track dashboard usage that will be tracked on an on-going basis. Dr. Reda will review results monthly.",
              "timeFrame": "Months 14-54"
            },
            {
              "measure": "Organization's implementation climate (adapted to evaluate overdose prevention strategies)",
              "description": "18-items that assesses the degree to which the climate is supportive of adopting new innovations that will be administered to 15 OFR team members and 5 system leaders per each of 18 counties.",
              "timeFrame": "Months 18, 24, 30, 36, 42, 48, 54, & 60"
            },
            {
              "measure": "Quality OFR Recommendations",
              "description": "OFR team recommendations will be gathered monthly. We will be coding the quality of OFR team recommendations using the coding system that we developed in phase 1 of our FORTRESS project. This measure involves qualitative assessments of whether a recommendation meets certain standards of quality. The qualitative coding will be conducted by research staff in a digital spreadsheet.",
              "timeFrame": "Months 14-54"
            },
            {
              "measure": "Uptake of OFR Interventions",
              "description": "OFR team recommendations will be gathered monthly. Uptake of an intervention will be defined as implementation of the recommendation. OFR team overdose prevention recommendations will be coded for uptake (whether or not they were implemented). This measure involves quantitative assessment of the incidence of uptake.",
              "timeFrame": "Months 14-54"
            },
            {
              "measure": "Overdose",
              "description": "Mortality data is collected via death certificates that are submitted by county coroners to the IDOH Division of Vital Records, which include information on underlying cause of Death. Data will include all fatal accidental drug overdose deaths (X40-X44).",
              "timeFrame": "Month 35-40 (interim) and month 53-57 (final)"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria for FORTRESS staff personnel recruited to complete surveys, focus groups and/or interviews:\n\n* 1\\) member of local overdose fatality review (OFR) team; OR 2) local county leader of organizations represented by OFR (OFR facilitator, public jail administrators, chief of police, judge, addiction treatment CEO/CFO, public health director, etc.).\n\nInclusion criteria for FORTRESS administrative data:\n\n* all residents of Indiana that have experienced fatal and/or non-fatal overdose as identified by administrative data sources.\n\nExclusion Criteria\n\n* N/A",
