          "briefTitle": "Ilioinguinal-iliohypogastric Nerve Block Prior to Shouldice Inguinal Hernia Repair",
          "officialTitle": "Ilioinguinal-iliohypogastric Nerve Block Prior to Shouldice Inguinal Hernia Repair",
          "acronym": "NBSS"
        },
        "statusModule": {
