        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "1",
              "description": "Patients that received the ilioinguinal-iliohypogastric nerve block \\[IINB\\] were chosen by the anesthetists prior to surgery based on patient suitability, consultation with patients, and availability of time and resources. The Ilioinguinal-iliohypogastric nerve block contained one of 0.5% Bupivacaine and 2% Lidocaine, 0.5% Marcaine and 2% Lidocaine, 0.25% Marcaine with Epinephrine, 0.25% or 0.1% Bupivacaine 2ith 2% Lidocaine (mixtures such as: 0.5% Bupivacaine (also called Marcaine) and 2% Lidocaine, with or without Epinephrine mix)."
            },
            {
              "label": "2",
              "description": "Matched patients in terms of biometric and peroperative data, who did not receive an Ilioinguinal-iliohypogastric nerve block."
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Compare pain and pain medication use between patients receiving an ilioinguinal-iliohypogastric nerve block prior to hernia surgery with those who do not.",
              "description": "Aldrete scoring/system",
              "timeFrame": "3 days after surgery"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Evaluate the impact of the ilioinguinal-iliohypogastric nerve block on patients with pain conditions, mental health conditions, and substance use histories.",
              "description": "Aldrete scoring/system",
              "timeFrame": "3 days after surgery"
            },
            {
              "measure": "Determine sample size for future prospective trial.",
              "timeFrame": "3 days after surgery"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Patients of all gender\n* Shouldice repair due to a groin hernia operation at Shouldice Hospital.\n\nExclusion Criteria:\n\n* Missing information in patient charts or patients are unable to be matched 1:1",
          "sex": "ALL",
          "minimumAge": "16 Years",
          "maximumAge": "99 Years",
          "stdAges": [
            "CHILD",
            "ADULT",
            "OLDER_ADULT"
          ],
          "studyPopulation": "The population will focus on all patients that had a hernia operation at Shouldice Hospital. The exclusion criteria are if there is missing information in patient charts or patients are unable to be matched 1:1. As this is the first study of its kind at Shouldice Hospital the required sample size is unknown, and we intend to include a small pilot analysis.\n\nThe patients that receive the ilioinguinal-iliohypogastric nerve block are having it administered in the operating room when on the table. The onset of the block is within minutes and lasts up to 12 hours after administration. The ilioinguinal-iliohypogastric nerve block is an option for almost everyone and may provide additional support for patients with lower pain thresholds and/or substance use issues. There is no difference in postoperative course for those patients who do and do not receive the nerve block, and there are no additional risks.",
          "samplingMethod": "NON_PROBABILITY_SAMPLE"
        },
