          "interventions": [
            {
              "type": "OTHER",
              "name": "Interstitial lung disease induction algorithm",
              "description": "Patients failing first line mycophenolic acid (MFA) will be randomized to MFA plus rituximab or intravenous cyclophosphamide. If they fail the second line they will be crossed over to the other option.",
              "armGroupLabels": [
                "Interstitial lung disease induction"
              ]
            },
            {
              "type": "OTHER",
              "name": "Pulmonary arterial hypertension algorithm",
              "description": "Patients diagnosed with pulmonary arterial hypertension secondary to systemic sclerosis will be randomized to receive anticoagulation (warfarin, rivaroxaban or apixaban)",
              "armGroupLabels": [
                "Pulmonary arterial hypertension"
              ]
            },
            {
              "type": "OTHER",
              "name": "Raynaud's phenomenon algorithm",
              "description": "Patients with mild Raynaud's phenomenon not responding to the first line treatment (nifedipine), will be randomized to receive losartan or nifedipine plus atorvastatin or nifedipine plus losartan. If they fail the second line they will be crossed over to the other options randomly.\n\nPatients with severe Raynaud's phenomenon not responding to the first line treatment (nifedipine) or failing the previous mild Raynaud's algorithm, will be randomized to receive nifedipine plus sildenafil or nifedipine plus intravenous iloprost. If they fail the second line they will be crossed over to the other option.",
              "armGroupLabels": [
                "Raynaud's phenomenon"
              ]
            },
            {
              "type": "OTHER",
              "name": "Digital ulcer algorithm",
              "description": "Patients with active digital ulcers not healing after 3 months or developing new ones with nifedipine will be randomized to nifedipine plus sildenafil or nifedipine plus intravenous iloprost. If they fail the second line they will be crossed over to the other option.\n\nPatients who develop new digital ulcers under treatment with nifedipine will be randomized to nifedipine plus atorvastatin plus standard of care or nifedipine plus standard of care. If they fail the second line they will be crossed over to the other option.",
              "armGroupLabels": [
                "Digital ulcers"
              ]
            },
            {
              "type": "OTHER",
              "name": "Inflammatory arthritis algorithm",
              "description": "Patients with inflammatory arthritis failing methotrexate and/or prednisone and/or hydroxychloroquine and/or sulfasalazine will be randomized to receive intravenous rituximab or subcutaneous tocilizumab. If they fail the second line they will be crossed over to the other option.",
              "armGroupLabels": [
                "Inflammatory arthritis"
              ]
            },
            {
              "type": "OTHER",
              "name": "Gastroesophageal reflux algorithm",
              "description": "Patients with gastroesophageal reflux failing standard doses of proton pump inhibitors (PPI) will be randomized to receive double doses of PPI or standard dose of PPI plus ranitidine or double doses of PPI plus domperidone or double doses of PPI plus prucalopride/erythromycin. If they fail the second line they will be crossed over to the other options randomly.",
              "armGroupLabels": [
                "Gastroesophageal reflux"
              ]
            },
            {
              "type": "OTHER",
              "name": "Bacterial overgrowth algorithm",
              "description": "Patients with bacterial overgrowth will be randomized to receive erythromycin or metronidazole or amoxicillin. If they fail the second line they will be crossed over to the other options randomly.",
              "armGroupLabels": [
                "Bacterial overgrowth"
              ]
            },
            {
              "type": "OTHER",
              "name": "Constipation algorithm",
              "description": "Patients with constipation will be randomized to receive bisacodyl or magnesium sulphate or polyethylene glycol or senna.If they fail the second line they will be crossed over to the other options randomly.",
              "armGroupLabels": [
                "Constipation"
              ]
            },
            {
              "type": "OTHER",
              "name": "Skin involvement algorithm",
              "description": "Patients with skin involvement and modified Rodnan skin score \\<32 will be randomized to receive methotrexate or mycophenolic acid or methotrexate plus mycophenolic acid. If they fail the second line they will be crossed over to the other option.\n\nPatients with skin involvement and modified Rodnan skin score \\>32 will be randomized to receive methotrexate plus mycophenolic acid or intravenous cyclophosphamide. If they fail the second line they will be crossed over to the other option.",
              "armGroupLabels": [
                "Skin involvement"
              ]
            },
            {
              "type": "OTHER",
              "name": "Pain algorithm",
              "description": "Patients with pain failing first line treatment with acetaminophen or celecoxib or ibuprofen will be randomized to receive pregabalin or duloxetine. Patients with skin involvement and modified Rodnan skin score \\<32 will be randomized to receive methotrexate or mycophenolic acid or methotrexate plus mycophenolic acid. If they fail the second line they will be crossed over to the other option. In case they fail the second line they will be treated with medical marijuana.",
              "armGroupLabels": [
                "Pain"
              ]
            }
          ]
        },
